-- LAC NOIR : SCÈNE COMPLÈTE, VERSION HUECO (25/11/2026) : le lac et l'île (démo de 40 s) + la cathédrale P2 (forme finale v10, effets v12).
-- Généré par atelier/builds/lac_noir_scene_complete/build.py : ne pas éditer à la main. lac_cath 0 : la cathédrale coupée.
-- LAC + ÎLE (pièce 3, passe 3) : le lac de la pièce 3 assemblé avec la démo de l'île, de nuit. Console : lac_eau_demo,
-- lac_eau_stop, lac_eau_matiere 1|2|3 (shader3, 4, 5). Généré par atelier/builds/lac_noir_lac_demo/build.py.
-- Démo jouée en direct (25/11/2026) : l'île I4, le trône K5 et l'épée retenue (katana 50 + griffes) du Lac noir de Nobleza,
-- avec la tornade J3, la lueur du hamon H2 et les particules de l'épée (repris de l'écran « tornade » de l'Atelier, moteur/film.py).
-- Généré par atelier/builds/lac_noir_ile_demo/build.py à partir de ce modèle (ne pas éditer zz_lac_eau_demo.lua à la main).
-- Une boucle de 40 s, caméra scriptée, nuit simulée :
--   0 à 8 s   calme       : brume basse, clapotis et ondes, veines éteintes (fissures sombres), trône éteint, épée froide
--   8 à 20 s  l'éveil     : la tornade se lève (grandit 2 s puis tourne), secousse et poussière, veines qui partent des griffes
--                           vers le trône, onde de choc sur l'eau, braises qui tombent sur la dalle, fente du trône qui s'embrase
--   20 à 28 s le plein feu : la tornade tourne au plus fort, veines et fente battent
--   28 à 40 s le siège vide : la tornade retombe (1,2 s), puis tout s'éteint (du trône vers l'épée), la brume se fige,
--                           rai de lumière froide sur l'assise avec sa poussière, silence, un seul battement
-- Console : lac_eau_demo (rejouer depuis le début), lac_eau_stop (arrêter, rendre la caméra).
-- Solo sur gm_flatgrass seulement. Rien dans le dupe : tout est rendu côté client. Retiré du jeu après la démo.
if not string.find(game.GetMap(), "hueco", 1, true) then return end
-- Q : regroupeur de quads et objets de travail partagés (optimisation 25/11), défini en tête du fichier : le module du lac s'en sert
local Q = { n = 0, reste = 0, MAX = 4000, coul_ile = Color(0, 0, 0, 0), v = Vector(), v2 = Vector(), c4 = Color(0, 0, 0, 0), nul = Color(0, 0, 0, 0),   -- v : vecteur de travail réutilisé      -- 4 000 quads = 24 000 indices (limite moteur 32 768 par lot)
   cache = nil, cle = nil, lit = {}, litl = {} }
function Q.debut(total)
  Q.reste, Q.n = total, 0
  if total > 0 then mesh.Begin(MATERIAL_QUADS, math.min(Q.MAX, total)) end
end
function Q.quad(q, r, g, b, a)
  if Q.n == Q.MAX then mesh.End(); Q.reste = Q.reste - Q.MAX; Q.n = 0; mesh.Begin(MATERIAL_QUADS, math.min(Q.MAX, Q.reste)) end
  for j = 1, 4 do mesh.Position(q[j]); mesh.Color(r, g, b, a); mesh.AdvanceVertex() end
  Q.n = Q.n + 1
end
function Q.fin() if Q.reste > 0 then mesh.End() end end
-- lumières dynamiques (optimisation 25/11) : chaque effet demande sa lumière, un seul passage par image n'allume que les plus
-- importantes (lac_qualite 0 : 2 lumières, 1 : 5, 2 : toutes). noworld : le sol de la carte est caché sous l'horizon noir,
-- inutile de recalculer ses lightmaps ; les props de l'île restent éclairés comme avant.
Q.L, Q.nL, Q.VL = {}, 0, { 1, 2, 3, 6 }
function Q.lum(id, prio, x, y, z, r, g, b, br, size)
  if br <= 0 or size <= 0 then return end
  Q.nL = Q.nL + 1
  local l = Q.L[Q.nL]; if not l then l = { pos = Vector() }; Q.L[Q.nL] = l end
  l.id, l.r, l.g, l.b, l.br, l.size, l.score, l.pris = id, r, g, b, br, size, prio * math.min(br, 3), false
  l.pos:SetUnpacked(x, y, z)
end
function Q.lum_emettre(now)
  local q = Q.qualite and Q.qualite:GetInt() or 1
  local max = q == 0 and 2 or q == 1 and 5 or 99
  for _ = 1, math.min(max, Q.nL) do
    local best
    for i = 1, Q.nL do local l = Q.L[i]; if not l.pris and (not best or l.score > best.score) then best = l end end
    best.pris = true
    local d = DynamicLight(best.id)
    if d then
      d.pos = best.pos; d.r, d.g, d.b = best.r, best.g, best.b; d.brightness = best.br; d.size = best.size
      d.decay = 0; d.dietime = now + 0.2; d.noworld = true
    end
  end
  Q.nL = 0
end
function Q.bande(pa, na, wa, pb, nb, wb) return { pa - na * wa, pa + na * wa, pb + nb * wb, pb - nb * wb } end
local function lisse(u) u = math.Clamp(u, 0, 1) return u * u * (3 - 2 * u) end

-- ---------- niveaux selon la phase ----------
local function pouls(d) return 0.55 + 0.45 * (0.5 + 0.5 * math.sin(CurTime() * 2.2 - d / 55)) end
local function lumiere(d)                         -- lumière d'un point de veine à la distance d du pied de l'épée
  if phase == "eveil" then
    if instant < 1 then return 0 end                -- v79 : les veines partent au boum
    local F = (instant - 1) * 330
    if d > F then return 0 end
    return pouls(d) + 1.1 * math.max(0, 1 - (F - d) / 110)
  elseif phase == "plein" then
    return pouls(d) * 1.12
  elseif phase == "siege" then
    local s = math.max(0, instant - RETOMBE)
    local E = DMAX - s * (DMAX / 2.4)
    local l = math.Clamp((E - d) / 110, 0, 1) * pouls(d)
    if d < 45 and s > 2.4 and s < 9 then l = math.max(l, 0.12) end
    return l
  end
  return 0
end
local function niveau_fente()
  if phase == "eveil" then return lisse((instant - 2.6) / 0.6) end
  if phase == "plein" then return 1 end
  if phase == "siege" then return 1 - lisse((instant - RETOMBE - 0.3) / 1.5) end
  return 0
end
local function niveau_froid() if phase == "siege" then return lisse((instant - RETOMBE - 1.5) / 1.5) end return 0 end
local function fige() return phase == "siege" and instant >= RETOMBE + 1 end

-- ---------- veines ----------
-- Passe 2 (Adrien 2 h 20 « revoir les traits rouges ») : tracés organiques et ramifiés (générés par le build), largeur qui
-- s'affine de l'épée vers le trône, bande continue (normales lissées aux jonctions : pas de pointillés), braise à deux couches
-- (bord carmin sombre, cœur orangé plus clair), halo doux et serré, léger scintillement, tête de braise qui court à l'allumage.
local normales = {}
local function normale(v, i)
  normales[v] = normales[v] or {}
  local nv = normales[v]
  if not nv[i] then
    local a, b = v[math.max(1, i - 1)], v[math.min(#v, i + 1)]
    local d = Vector(b[1] - a[1], b[2] - a[2], 0); d:Normalize()
    nv[i] = Vector(-d.y, d.x, 0)
  end
  return nv[i]
end
local function front()                            -- distance atteinte par l'allumage (nil hors de l'éveil)
  if phase == "eveil" and instant >= 0.5 then return (instant - 0.5) * 330 end
end
