-- ---- scène complète : la boîte (relative au repère, quel que soit l'endroit du collage) et le temps des cloches ----
local SC = { X0 = -4047, X1 = 4047, Y0 = -2646, Y1 = 5647, Z0 = -91, Z1 = 1854,   -- boîte 8 094 x 8 293 x 1 945
  DECALE = 7.5, manuel = false }            -- 4 coups de cloche seuls avant le boum : le lac est décalé d'autant après 8 s
BOUCLE = BOUCLE + SC.DECALE
SC.BORD = {}                                     -- v71 : points des bancs de brume du bord (repère de l'île)
for x = SC.X0 + 150, SC.X1 - 150, 600 do SC.BORD[#SC.BORD + 1] = { x, SC.Y0 + 150 }; SC.BORD[#SC.BORD + 1] = { x, SC.Y1 - 150 } end
for y = SC.Y0 + 750, SC.Y1 - 750, 600 do SC.BORD[#SC.BORD + 1] = { SC.X0 + 150, y }; SC.BORD[#SC.BORD + 1] = { SC.X1 - 150, y } end
function SC.TL(T) if T < 8 then return T elseif T < 8 + SC.DECALE then return 7.99 end return T - SC.DECALE end   -- temps brut -> temps du lac
-- lac_boite 1 : seuls les joueurs dans la boîte voient et entendent ; 0 : partout (banc solo : le joueur du banc
-- est posé à chaque vue, pas dans la boîte, et la démo joue sa propre caméra)
SC.cam = CreateClientConVar("lac_camera", "0", false, false, "Lac noir : 1 = caméra du film, 0 = vue libre", 0, 1)
SC.boite = CreateClientConVar("lac_boite", "1", false, false, "Lac noir : 1 = seulement dans la boîte de la scène", 0, 1)
SC.etat = nil
print("[lac_cloche] sound/lac_noir/cloche.wav " .. (file.Exists("sound/lac_noir/cloche.wav", "GAME") and "trouvée" or "ABSENTE")
  .. ", durée " .. SoundDuration("lac_noir/cloche_der.wav"))
function SC.dans()                                -- joueur dans la boîte de la scène (repère du dupe collé)
  local ply = LocalPlayer()
  if not off or not IsValid(ply) then return false end
  local p = ply:GetPos()
  local x, y, z = p.x - off.x, p.y - off.y, p.z - off.z
  local d = x >= SC.X0 and x <= SC.X1 and y >= SC.Y0 and y <= SC.Y1 and z >= SC.Z0 - 300 and z <= SC.Z1 + 20000
  if d ~= SC.etat then SC.etat = d; print(string.format("[lac_boite] joueur %s de la boîte (%.0f, %.0f, %.0f du repère)", d and "dans" or "hors", x, y, z)) end
  return d or not SC.boite:GetBool()
end
