local REFRACTIONS = { "models/shadertest/shader3", "models/shadertest/shader4", "models/shadertest/shader5" }
local refraction = 1
local function dans_lac(x, y, m) m = m or 0 return x > LAC_X0 + m and x < LAC_X1 - m and y > LAC_Y0 + m and y < LAC_Y1 - m end
local function lac_cercle(c, r, larg, col, N)             -- cercle coupé aux bords du lac (alpha nul dehors)
  N = N or 120                                            -- optimisation : aucun Vector ni Color créé par point
  local v, nul, cx, cy, cz, ox, oy = Q.v, Q.nul, c.x, c.y, c.z, off.x, off.y
  render.StartBeam(N + 1)
  for i = 0, N do
    local a = i / N * 6.2832; local x, y = cx + math.cos(a) * r, cy + math.sin(a) * r
    v:SetUnpacked(x, y, cz)
    render.AddBeam(v, larg, 0, dans_lac(x - ox, y - oy) and col or nul)
  end
  render.EndBeam()
end
local function bord_irr(c, an, r, t, g)                   -- passe 4 : un rayon qui n'est jamais un cercle parfait
  local k = 1 + 0.04 * math.sin(an * 5 + 1.3 + g) + 0.025 * math.sin(an * 11 - t * 1.7 + g) + 0.015 * math.sin(an * 23 + t * 3)
  return c + Vector(math.cos(an) * r * k, math.sin(an) * r * k, 0)
end
local function lac_anneau(c, r, larg, col, g, N)          -- anneau doux, irrégulier, d'épaisseur variable, coupé au lac
  N = N or 120; local t = CurTime()
  render.SetMaterial(HALO)
  render.StartBeam(N + 1)
  g = g or 0
  local v, nul, cx, cy, cz, ox, oy = Q.v, Q.nul, c.x, c.y, c.z, off.x, off.y
  for i = 0, N do                                         -- optimisation : bord irrégulier calculé en nombres
    local an = i / N * 6.2832
    local k = 1 + 0.04 * math.sin(an * 5 + 1.3 + g) + 0.025 * math.sin(an * 11 - t * 1.7 + g) + 0.015 * math.sin(an * 23 + t * 3)
    local x, y = cx + math.cos(an) * r * k, cy + math.sin(an) * r * k
    v:SetUnpacked(x, y, cz)
    local w = larg * (0.55 + 0.45 * math.sin(an * 9 + t * 2.5 + g))
    render.AddBeam(v, w, i * 0.1, dans_lac(x - ox, y - oy) and col or nul)
  end
  render.EndBeam()
end
-- le battement du cœur (passe 4) : lub-dub toutes les 1,6 s, calé pour qu'un battement tombe à 36 s (le son du siège vide)
local COEUR_P = 1.6
local function coeur_ph() if not t0 then return 0 end return ((CurTime() - t0 - 36 - SC.DECALE) % COEUR_P) / COEUR_P end
local function coeur()
  local ph = coeur_ph()
  return math.max(0, 1 - ph / 0.1) + 0.6 * math.max(0, 1 - math.abs(ph - 0.19) / 0.08)
end

                -- calme / eveil / siege, et le temps depuis le début de la phase

local CATH                                        -- scène complète : la cathédrale (module en fin de fichier)
local PIECES = {}                                 -- scène complète : monolithes, aqueducs, flamme, éclipse (modules en fin de fichier ; une seule locale : limite de 200)
-- ---------- repérage : le dupe collé, la fente du trône ----------
SC.MOIT = { Vector(-30.521, -2317.987, 327.428), Vector(30.521, -2317.987, 327.428) }   -- v86 : moitiés du dossier, depuis la plaque
function SC.moities(p, liste)                    -- v86 : les deux moitiés à leur place autour de la plaque p (20 u près), ou nil
  local r = {}
  for i, v in ipairs(SC.MOIT) do
    local cible = p + v
    for _, e in ipairs(liste) do if IsValid(e) and e:GetPos():DistToSqr(cible) < 400 then r[i] = e break end end
    if not r[i] then return nil end
  end
  return r
end
function SC.repere()                             -- v86 : la plaque du build reconnue à son motif, la plus proche du joueur
  local ply, plaques, liste = LocalPlayer(), ents.FindByModel(REF), ents.FindByModel(MOITIE)
  local best, bd, bm
  for _, e in ipairs(plaques) do
    local m = IsValid(e) and SC.moities(e:GetPos(), liste)
    if m then
      local d = IsValid(ply) and e:GetPos():DistToSqr(ply:GetPos()) or 0
      if not best or d < bd then best, bd, bm = e, d, m end
    end
  end
  local cle = #plaques .. "/" .. #liste .. "/" .. tostring(best)
  if cle ~= SC.diag then
    SC.diag = cle
    print(string.format("[lac_repere] %d plaque(s) 8x8 et %d moitié(s) vues : %s", #plaques, #liste,
      best and ("build du Lac noir trouvé en " .. tostring(best:GetPos())) or "motif du build introuvable"))
  end
  return best, bm
end
function SC.dans_boite(p)                        -- v86 : position dans la boîte du build repéré (marge 300 u)
  if not off then return false end
  local x, y, z = p.x - off.x, p.y - off.y, p.z - off.z
  return x >= SC.X0 - 300 and x <= SC.X1 + 300 and y >= SC.Y0 - 300 and y <= SC.Y1 + 300 and z >= SC.Z0 - 300 and z <= SC.Z1 + 300
end
local function reperer()
  local d, m = SC.repere()
  if SC.OS then m = SC.moities(SC.OS + SOL, ents.FindByModel(MOITIE)) end   -- v87 : le serveur fait foi
  if not d and not SC.OS then                                    -- v86 : motif introuvable ; v85 : build retiré (ou pas encore collé) : plus rien du tout
    off = nil
    if t0 then t0 = nil; SC.couper(); RunConsoleCommand("stopsound") end
    if CATH and CATH.oublier then CATH.oublier() end
    return
  end
  off = SC.OS or (d:GetPos() - SOL)
  if CATH then CATH.reperer(off) end
  if m then                                        -- v86 : les deux moitiés du motif
    local a1, b1 = m[1]:WorldSpaceAABB(); local a2, b2 = m[2]:WorldSpaceAABB()
    if a1.x > a2.x then a1, b1, a2, b2 = a2, b2, a1, b1 end
    fente = { x = (b1.x + a2.x) / 2, l = a2.x - b1.x, y = math.min(a1.y, a2.y), z0 = math.max(a1.z, a2.z), z1 = math.min(b1.z, b2.z) }
  end
end
local function W(x, y, z) return Vector(x, y, z) + off end
local function veines_geo()                     -- géométrie fixe des veines, recalculée seulement si le build est recollé
  if Q.cache and Q.cle == off then return Q.cache end
  local z, seg = ZI + 0.7, {}
  for k, v in ipairs(VEINES) do
    local vv = {}
    for i = 1, #v - 1 do
      local a, b = v[i], v[i + 1]
      local pa, pb = W(a[1], a[2], z), W(b[1], b[2], z)
      local na, nb = normale(v, i), normale(v, i + 1)
      local wa, wb = a[4] or 1.5, b[4] or 1.5
      vv[#vv + 1] = { a = a, b = b, i = i, pa = pa, pb = pb, wa = wa, wb = wb, m = (a[3] + b[3]) / 2,
        sombre = Q.bande(pa, na, wa + 1.1, pb, nb, wb + 1.1), braise = Q.bande(pa, na, wa, pb, nb, wb),
        coeur = Q.bande(pa, na, wa * 0.42, pb, nb, wb * 0.42), halo = pa + Vector(0, 0, 0.6) }
    end
    seg[k] = vv
  end
  Q.cache, Q.cle = seg, Vector(off.x, off.y, off.z)
  return seg
end
local function veines()
  local seg = veines_geo()
  local t, F = CurTime(), front()
  local lit, litl, n, total = Q.lit, Q.litl, 0, 0
  for k = 1, #seg do
    local vv = seg[k]; total = total + #vv
    for i = 1, #vv do
      local s = vv[i]
      local l = lumiere(s.m)
      if l > 0.02 then n = n + 1; lit[n] = s; litl[n] = l end
    end
  end
  if not Q.brulure and #FUMEE > 0 then Q.brulure = Material(FUMEE[1]) end   -- v72 : la brûlure au pied de l'épée
  if Q.brulure then
    render.SetMaterial(Q.brulure); Q.v:SetUnpacked(off.x, -140 + off.y, ZI + 0.45 + off.z)
    local c = Q.c3; c.r, c.g, c.b, c.a = 12, 3, 5, 235
    render.DrawQuadEasy(Q.v, Q.haut, 300, 230, c, 15); render.DrawQuadEasy(Q.v, Q.haut, 200, 170, c, 70)
  end
  render.SetColorMaterial()
  Q.debut(total + 2 * n)
  for k = 1, #seg do local vv = seg[k] for i = 1, #vv do Q.quad(vv[i].sombre, 12, 5, 6, 255) end end   -- la fissure, sombre
  for j = 1, n do
    local s, l = lit[j], litl[j]
    local sc = 0.88 + 0.12 * math.sin(t * 7.3 + s.a[3] * 0.09) * math.sin(t * 3.1 + s.i * 0.7)        -- scintillement
    local c, chaud = math.min(1, l) * sc, math.max(0, l - 1)
    s.c, s.chaud = c, chaud
    Q.quad(s.braise, 205, 22 + 60 * chaud, 18, 255 * c)
    Q.quad(s.coeur, 255, 95 + 110 * chaud + 25 * c, 45 + 80 * chaud, 235 * c)
  end
  Q.fin()
  local lb = lumiere(40)                           -- v72 : la brûlure rougeoie avec les veines
  if lb > 0.02 then render.SetMaterial(HALO); local c = Q.c3; c.r, c.g, c.b, c.a = 190, 28, 18, math.min(255, 110 * lb)
    Q.v:SetUnpacked(off.x, -140 + off.y, ZI + 1 + off.z); render.DrawQuadEasy(Q.v, Q.haut, 230, 190, c, 15) end
  -- halo : un ruban doux par veine allumée (le milieu de la texture de halo donne le profil doux en travers)
  if n > 0 then
    render.SetMaterial(HALO)
    for k = 1, #seg do
      local vv = seg[k]
      local deb = nil
      for i = 1, #vv + 1 do
        local s = vv[i]
        local on = s and s.c ~= nil
        if on and not deb then deb = i end
        if (not on) and deb then
          local nb = i - deb + 1
          if nb >= 2 then
            render.StartBeam(nb)
            for j = deb, i do
              local q = vv[math.min(j, #vv)]
              local p = (j <= #vv) and q.halo or q.pb
              local w = (j <= #vv) and q.wa or q.wb
              local c, chaud = q.c or 0, q.chaud or 0
              local col = Q.coul_ile; col.r, col.g, col.b, col.a = 220, 25 + 70 * chaud, 25, math.min(255, 95 * c)
              render.AddBeam(p, ((5 + 4.5 * w) * c + 16 * chaud) * 2, 0.5, col)
            end
            render.EndBeam()
          end
          deb = nil
        end
      end
    end
  end
  if F then                                          -- la tête de braise qui progresse (peu d'appels : un seul point)
    render.SetMaterial(HALO)
    for k = 1, #seg do
      local vv = seg[k]
      for i = 1, #vv do
        local s = vv[i]
        if s.a[3] <= F and F < s.b[3] then
          local p = LerpVector((F - s.a[3]) / math.max(0.1, s.b[3] - s.a[3]), s.pa, s.pb) + Vector(0, 0, 1)
          render.DrawSprite(p, 22, 22, Color(255, 150, 60, 200))
          render.DrawSprite(p, 7, 7, Color(255, 240, 200, 255))
        end
      end
    end
  end
  for j = 1, n do lit[j].c = nil end
end

-- ---------- reflets humides : un éclat court qui glisse le long des arêtes ----------
local function aretes()
  if fige() then return end
  render.SetMaterial(HALO)
  local t = CurTime()                             -- optimisation 25/11 : aucun Vector ni Color par arête
  local v, v2, col, ox, oy, oz = Q.v, Q.v2, Q.c4, off.x, off.y, off.z + 0.5
  col.r, col.g, col.b = 190, 210, 240
  for i, a in ipairs(ARETES) do
    local u = (t * 0.18 + i * 0.37) % 1.6
    if u < 1 then
      local u2 = math.min(1, u + 0.12)
      local ax, ay, az, dx, dy, dz = a[1] + ox, a[2] + oy, a[3] + oz, a[4] - a[1], a[5] - a[2], a[6] - a[3]
      v:SetUnpacked(ax + dx * u, ay + dy * u, az + dz * u); v2:SetUnpacked(ax + dx * u2, ay + dy * u2, az + dz * u2)
      col.a = 120 * math.sin(u * math.pi)
      render.DrawBeam(v, v2, 4, 0, 1, col)
    end
  end
end

-- ---------- ondes, onde de choc ----------
local anneaux, prochaineOnde = {}, 0
local function cercle(c, r, larg, col)            -- optimisation : vecteur de travail réutilisé (AddBeam copie la position)
  local N, v, cx, cy, cz = 40, Q.v, c.x, c.y, c.z
  render.StartBeam(N + 1)
  for i = 0, N do local a = i / N * 6.2832; v:SetUnpacked(cx + math.cos(a) * r, cy + math.sin(a) * r, cz); render.AddBeam(v, larg, 0, col) end
  render.EndBeam()
end
local function ondes()
  render.SetColorMaterial()
  local t = CurTime()
  for i = #anneaux, 1, -1 do
    local o = anneaux[i]; local a = (t - o.t0) / o.vie
    if a >= 1 then table.remove(anneaux, i) else
      cercle(o.c, 6 + o.r * a, 2.4, Color(150, 175, 215, 190 * (1 - a) ^ 1.4))
      if a > 0.25 then cercle(o.c, 3 + o.r * (a - 0.25), 1.4, Color(150, 175, 215, 110 * (1 - a))) end
    end
  end
end

-- ---------- onde de choc volumique (Adrien 2 h 26 : « trop plate ») ----------
-- 3 vagues qui suivent en s'amortissant : un mur d'eau qui se soulève puis retombe derrière le front (corps sombre, crête
-- d'écume), gerbes de gouttes le long du front, anneau d'air déformé (réfraction), brume chassée, flash carmin au pied de l'épée.
local CHOC = { { t = 1.0, a = 1.0 }, { t = 1.45, a = 0.55 }, { t = 2.0, a = 0.3 } }   -- instant de l'éveil, amplitude
local CHOC_V, CHOC_R0, CHOC_VIE = 900, 230, 6.0                -- passe 3 du lac : elle traverse tout le lac
local REFRACT = Material("sprites/heatwave")
local EAUX = {}
for _, n in ipairs({"effects/splash2", "effects/splash1", "effects/splash4"}) do if not Material(n):IsError() then EAUX[#EAUX + 1] = n end end
local function choc_u(o) if phase ~= "eveil" then return end local u = instant - o.t if u >= 0 and u < CHOC_VIE then return u end end
local function mur(c, R, h, a, al)                -- passe 4 du lac : mur d'eau irrégulier, crête épaisse et douce, coupé au lac
  local N, t = 120, CurTime()                     -- optimisation 25/11 : calcul en nombres, objets de travail réutilisés
  local cx, cy, cz, ox, oy = c.x, c.y, c.z, off.x, off.y
  local p1, p2, q1, q2, col = Q.v, Q.v2, Q.v3, Q.v4, Q.c2
  col.r, col.g, col.b, col.a = 34, 44, 58, 170 * al
  render.SetColorMaterial()
  local px, py, qx, qy, qz
  for i = 0, N do
    local an = i / N * 6.2832
    local k = 1 + 0.04 * math.sin(an * 5 + 1.3) + 0.025 * math.sin(an * 11 - t * 1.7) + 0.015 * math.sin(an * 23 + t * 3)
    local hh = h * (0.65 + 0.35 * math.sin(an * 7 + t * 2))
    local ca, sa, rq = math.cos(an), math.sin(an), (R - hh * 0.6) * k
    local nx, ny, mx, my, mz = cx + ca * R * k, cy + sa * R * k, cx + ca * rq, cy + sa * rq, cz + hh
    if i > 0 and dans_lac(px - ox, py - oy) then
      p1:SetUnpacked(px, py, cz); p2:SetUnpacked(nx, ny, cz); q1:SetUnpacked(qx, qy, qz); q2:SetUnpacked(mx, my, mz)
      render.DrawQuad(p1, p2, q2, q1, col); render.DrawQuad(q1, q2, p2, p1, col)
    end
    px, py, qx, qy, qz = nx, ny, mx, my, mz
  end
  local cc = Q.c3
  cc.r, cc.g, cc.b = 190, 204, 222
  render.SetMaterial(HALO)
  render.StartBeam(N + 1)
  for i = 0, N do
    local an = i / N * 6.2832; local hh = h * (0.65 + 0.35 * math.sin(an * 7 + t * 2))
    local k = 1 + 0.04 * math.sin(an * 5 + 1.3) + 0.025 * math.sin(an * 11 - t * 1.7) + 0.015 * math.sin(an * 23 + t * 3)
    local rq = (R - hh * 0.6) * k
    local x, y = cx + math.cos(an) * rq, cy + math.sin(an) * rq
    p1:SetUnpacked(x, y, cz + hh)
    local w = (12 + 12 * a) * (0.5 + 0.5 * math.sin(an * 9 + t * 2.5))
    cc.a = dans_lac(x - ox, y - oy) and 95 * al or 0
    render.AddBeam(p1, w, i * 0.1, cc)
  end
  render.EndBeam()
end
local function choc_dessin()
  local c = W(EPEE.x, EPEE.y, EAU + 1.5)
  for k, o in ipairs(CHOC) do
    local u = choc_u(o)
    if u then
      local R, al = CHOC_R0 + CHOC_V * u, math.Clamp(1 - u / CHOC_VIE, 0, 1)
      local h = 46 * o.a * math.sin(math.min(1, u / 0.5) * math.pi * 0.5) * al ^ 0.6     -- se soulève vite, retombe en s'étalant
      mur(c, R, h, o.a, al)
      lac_anneau(c, R + 14, 26 * o.a, Color(255, 50, 40, 200 * al * o.a), k * 1.7)                   -- liseré carmin du front, sur l'eau
      lac_anneau(c, R - 60, 14, Color(150, 170, 205, 60 * al), k * 0.9 + 3)                            -- l'eau qui retombe derrière
      if k == 1 and REFRACT and not REFRACT:IsError() then                             -- l'air déformé au-dessus du front
        render.UpdateRefractTexture(); render.SetMaterial(REFRACT)
        local v, col = Q.v, Q.coul_ile; col.r, col.g, col.b, col.a = 255, 255, 255, 255 * al
        for i = 0, 35 do local a = i / 36 * 6.2832
          v:SetUnpacked(c.x + math.cos(a) * (R - 20), c.y + math.sin(a) * (R - 20), c.z + 40); render.DrawSprite(v, 120, 90, col) end
      end
    end
  end
  if phase == "eveil" and instant >= 0.95 and instant < 1.6 then                       -- flash carmin au pied de l'épée
    local f = 1 - (instant - 0.95) / 0.65
    render.SetMaterial(HALO)
    local p = W(EPEE.x, EPEE.y, ZI + 20)
    render.DrawSprite(p, 520 * f, 300 * f, Color(255, 40, 35, 230 * f))
    render.DrawSprite(p, 160 * f, 110 * f, Color(255, 200, 170, 255 * f))
  end
end
local gerbes_t = 0
local function gerbes(e, now)                    -- gouttes projetées le long du front de la 1re et de la 2e vague
  if #EAUX == 0 or now < gerbes_t then return end
  gerbes_t = now + 0.03
  for k = 1, 2 do
    local o = CHOC[k]; local u = choc_u(o)
    if u and u < 4 then
      local R = CHOC_R0 + CHOC_V * u
      for _ = 1, math.floor(10 * o.a) do
        local a = math.Rand(0, 6.283)
        local gx, gy = EPEE.x + math.cos(a) * R, EPEE.y + math.sin(a) * R
        local p = dans_lac(gx, gy) and (W(gx, gy, EAU) - EyePos()):Length() < 3500 and e:Add(EAUX[math.random(#EAUX)], W(gx, gy, EAU + 4))
        if p then
          p:SetVelocity(Vector(math.cos(a), math.sin(a), 0) * math.Rand(60, 170) + Vector(0, 0, math.Rand(140, 300) * o.a))
          p:SetGravity(Vector(0, 0, -520)); p:SetDieTime(math.Rand(0.7, 1.2)); p:SetStartAlpha(200); p:SetEndAlpha(0)
          p:SetStartSize(math.Rand(6, 12)); p:SetEndSize(math.Rand(16, 26)); p:SetRoll(math.Rand(0, 360)); p:SetColor(190, 205, 225)
        end
      end
    end
  end
end

-- ---------- braises ----------
local braises, prochaineBraise = {}, 0
local function sur_ile(p) local q = p - off return q.x > -560 and q.x < 560 and q.y > -440 and q.y < 445 end
local function braise_neuve()
  local a, r = math.Rand(0, 6.283), math.Rand(20, 330)
  braises[#braises + 1] = { p = W(EPEE.x, EPEE.y, ZI) + Vector(math.cos(a) * r, math.sin(a) * r, math.Rand(160, 520)),
                            v = Vector(math.Rand(-14, 14), math.Rand(-14, 14), math.Rand(-90, -50)) }
end
local function braises_dessin()
  render.SetMaterial(HALO)
  local t, col = CurTime(), Q.c4                  -- optimisation 25/11 : couleur de travail réutilisée
  for _, b in ipairs(braises) do
    if b.sol then
      local a = math.Clamp((t - b.sol) / 2.4, 0, 1)
      col.r, col.g, col.b, col.a = 255, 110 - 80 * a, 30, 230 * (1 - a); render.DrawSprite(b.p, 13 * (1 - a) + 2, 13 * (1 - a) + 2, col)
      col.r, col.g, col.b, col.a = 255, 225, 170, 255 * (1 - a); render.DrawSprite(b.p, 3.5 * (1 - a), 3.5 * (1 - a), col)
    else
      col.r, col.g, col.b, col.a = 255, 130, 45, 210; render.DrawSprite(b.p, 12, 12, col)
      col.r, col.g, col.b, col.a = 255, 235, 180, 255; render.DrawSprite(b.p, 3.5, 3.5, col)
    end
  end
end

-- ---------- l'épée : tornade J3, lueur du hamon H2, particules de l'épée ----------
-- Repris de l'écran « tornade » de l'Atelier (moteur/film.py, validé par Adrien : « magnifique ») : flammes étirées en
-- entonnoir autour de la lame (jamais à moins de 120 u, effacées entre le regard et la lame), brasier au pied, fumée éclairée,
-- braises, 10 langues de feu en deux couches, colonne de chaleur. Ici l'émetteur ne se dessine pas tout seul : il est dessiné
-- après l'assombrissement de la nuit (sinon les flammes sortent ternes), comme les veines.
for _, f in ipairs({"particles/fire_01.pcf", "particles/watcher_map.pcf", "particles/watcher_stuff.pcf", "particles/ali_aura.pcf"}) do
  if file.Exists(f, "GAME") then game.AddParticles(f) end
end
local function tor_mat(n) local m = Material(n); if m and not m:IsError() then return m end end
local TOR_FLAMME = {}
for _, n in ipairs({"effects/fire_cloud1", "effects/fire_cloud2", "particle/fire"}) do if tor_mat(n) then TOR_FLAMME[#TOR_FLAMME + 1] = n end end
local TOR_BRAISE = tor_mat("effects/fire_embers1") and "effects/fire_embers1" or "effects/spark"
local TOR_LANGUE, TOR_LASER = tor_mat("effects/fire_cloud1") or tor_mat("particle/fire"), tor_mat("effects/laser1")
local TOR_PCF = { {"aura_rouge", 12}, {"[1]_campfire_red", 10}, {"[1]embers", 200} }
for _, x in ipairs(TOR_PCF) do PrecacheParticleSystem(x[1]) end
local TOR_H, TOR_RAYON, TOR_W = 700, 120, 4.2
local TOR_VUE = Vector(0, -100000, 0)
local function tor_niveau()                       -- échelle (taille) et force de la tornade selon la phase
  if phase == "eveil" then return 0.1 + 0.9 * lisse(instant / 2), 1 end
  if phase == "plein" then return 1, 1.35 end
  if phase == "siege" and instant < RETOMBE then local u = instant / RETOMBE; return 1 - 0.9 * lisse(u), 1 - u end
  return 0, 0
end
local function tor_couleur(u)                     -- jaune-orange au pied, carmin au milieu, rouge sang en haut
  if u < 0.3 then local k = u / 0.3; return 255, 190 + (70 - 190) * k, 70 + (25 - 70) * k end
  if u < 0.65 then local k = (u - 0.3) / 0.35; return 255 + (220 - 255) * k, 70 + (20 - 70) * k, 25 + (30 - 25) * k end
  local k = (u - 0.65) / 0.35; return 220 + (140 - 220) * k, 20 + (8 - 20) * k, 30 + (18 - 30) * k
end
local function tor_rayon(h, s)                    -- serré au pied, évasé en haut ; jamais plus près de la lame que TOR_RAYON
  local r = 40 + 0.24 * h / s
  if h < 0.86 * TOR_H * s then r = math.max(r, TOR_RAYON) end
  return r * s
end
local function tor_devant(c, a, h, s)             -- 0 à 1 : ce point est-il entre le regard et la lame ?
  if h > 0.86 * TOR_H * s then return 0 end
  local dx, dy = TOR_VUE.x - c.x, TOR_VUE.y - c.y
  local l = math.sqrt(dx * dx + dy * dy)
  if l < 1 then return 0 end
  return math.max(0, (math.cos(a) * dx + math.sin(a) * dy) / l) * 0.95
end
local tor_ps, tor_em, tor_der = {}, nil, nil
local function tor_arreter()
  for _, p in pairs(tor_ps) do if p:IsValid() then p:StopEmission() end end
  tor_ps, tor_der = {}, nil
end
local function emetteur_feu()
  if not (tor_em and tor_em:IsValid()) then tor_em = ParticleEmitter(W(EPEE.x, EPEE.y, ZI), false); tor_em:SetNoDraw(true) end
  return tor_em
end
local function tor_emettre(c, s, force, now)
  for i, x in ipairs(TOR_PCF) do                  -- les 3 particules de l'épée : aura, feu au pied, braises
    local p = tor_ps[i]
    if not (p and p:IsValid()) and CreateParticleSystemNoEntity then p = CreateParticleSystemNoEntity(x[1], c + Vector(0, 0, x[2] * s)); tor_ps[i] = p end
    if p and p:IsValid() then p:SetControlPoint(0, c + Vector(0, 0, x[2] * s)) end
  end
  Q.lum(7830, 3, c.x, c.y - 120, c.z + 200 * s, 255, 40, 30, (2.4 + 1.4 * math.sin(now * 5)) * s * force, 750 * s)   -- lumière rouge qui bat
  if #TOR_FLAMME == 0 then return end
  local em = emetteur_feu()
  local n = math.min(150, math.floor((now - (tor_der or now)) * 700 * force))
  if not tor_der or n >= 1 then tor_der = now end
  local H, rot = TOR_H * s, now * TOR_W
  for _ = 1, n do                                 -- flammes étirées le long de la spirale (4 bras)
    local h = math.Rand(0, 1) ^ 0.8 * H; local u = h / H
    local a = rot + math.random(0, 3) * 1.571 + h * 0.010 + math.Rand(-0.1, 0.1)
    local r = tor_rayon(h, s) * math.Rand(0.9, 1.05)
    local p = em:Add(TOR_FLAMME[math.random(#TOR_FLAMME)], c + Vector(math.cos(a) * r, math.sin(a) * r, h))
    if p then
      p:SetVelocity(Vector(-math.sin(a), math.cos(a), 0) * r * TOR_W + Vector(0, 0, math.Rand(130, 230) * s))
      p:SetDieTime(math.Rand(0.35, 0.6)); p:SetStartAlpha(255 * (1 - tor_devant(c, a, h, s))); p:SetEndAlpha(0)
      local z = math.Rand(12, 20) * (1.3 - 0.5 * u) * 0.55 * s
      p:SetStartSize(z); p:SetEndSize(z * 0.3); p:SetStartLength(math.Rand(45, 80) * 1.8 * s); p:SetEndLength(30 * s)
      p:SetColor(tor_couleur(u))
    end
  end
  for _ = 1, math.floor(n / 3) do                 -- brasier au pied, écarté de la lame
    local h = math.Rand(0, 60 * s); local a = rot * 1.3 + math.Rand(0, 6.283); local r = tor_rayon(h, s) * math.Rand(0.55, 1.0)
    local p = em:Add(TOR_FLAMME[math.random(#TOR_FLAMME)], c + Vector(math.cos(a) * r, math.sin(a) * r, h))
    if p then
      p:SetVelocity(Vector(-math.sin(a), math.cos(a), 0) * r * TOR_W + Vector(0, 0, math.Rand(80, 180) * s))
      p:SetDieTime(math.Rand(0.3, 0.55)); p:SetStartAlpha(255 * (1 - tor_devant(c, a, h, s))); p:SetEndAlpha(0)
      p:SetStartSize(math.Rand(18, 30) * s); p:SetEndSize(5 * s); p:SetStartLength(math.Rand(30, 55) * s); p:SetEndLength(10 * s)
      p:SetColor(255, math.Rand(110, 190), math.Rand(30, 70))
    end
  end
  for _ = 1, math.floor(n / 8) do                 -- fumée éclairée en haut : la silhouette de l'entonnoir
    if #FUMEE == 0 then break end
    local h = math.Rand(0.74, 1.08) * H; local a = rot + math.Rand(0, 6.283); local r = tor_rayon(h, s) * math.Rand(0.7, 1.1)
    local p = em:Add(FUMEE[math.random(#FUMEE)], c + Vector(math.cos(a) * r, math.sin(a) * r, h))
    if p then
      p:SetVelocity(Vector(-math.sin(a), math.cos(a), 0) * r * TOR_W * 0.5 + Vector(0, 0, 60 * s)); p:SetDieTime(math.Rand(1.2, 2))
      p:SetStartAlpha(160); p:SetEndAlpha(0); p:SetStartSize(50 * s); p:SetEndSize(120 * s)
      p:SetRoll(math.Rand(0, 360)); p:SetRollDelta(math.Rand(-0.6, 0.6)); p:SetColor(95, 28, 22)
    end
  end
  for _ = 1, math.max(1, math.floor(n / 10)) do   -- braises éjectées vers l'extérieur
    local h = math.Rand(0.04, 0.86) * H; local a = rot + math.Rand(0, 6.283); local r = tor_rayon(h, s)
    local p = em:Add(TOR_BRAISE, c + Vector(math.cos(a) * r, math.sin(a) * r, h))
    if p then
      p:SetVelocity(Vector(math.cos(a), math.sin(a), 0) * math.Rand(120, 260) + Vector(0, 0, math.Rand(60, 200)))
      p:SetGravity(Vector(0, 0, -150)); p:SetDieTime(math.Rand(0.8, 1.5)); p:SetStartAlpha(255); p:SetEndAlpha(0)
      p:SetStartSize(3); p:SetEndSize(1); p:SetColor(255, 140, 50)
    end
  end
end
local function tor_langues(c, s, force, now)      -- 10 langues de feu en deux couches, avec un cœur chaud
  if not TOR_LANGUE or s <= 0.01 then return end
  local H, v3, col, ma = TOR_H * s, Q.v, Q.c4, MIR_A or 1   -- optimisation 25/11 : vecteur et couleur de travail réutilisés
  local cx, cy, cz = c.x, c.y, c.z
  for j = 0, 9 do
    local couche = j % 2 == 0 and 1.0 or 0.72
    local hb = (now * 230 * s + j * 71 * s) % (0.886 * H)
    local fade = math.min(1, (0.886 * H - hb) / (200 * s)) * math.min(1, force)
    for coeur = 0, 1 do
      render.SetMaterial(TOR_LANGUE); render.StartBeam(12)
      for i = 0, 11 do
        local v = i / 11
        local h = 10 * s + hb + v * 200 * s
        local a = now * TOR_W + j * 1.047 + v * 1.4 + h * 0.010
        local r = tor_rayon(h, s) * couche * (coeur == 1 and 0.98 or 1)
        local dv = 1 - tor_devant(c, a, h, s)
        local wz = cz + h
        if MIROIR then wz = 2 * MIROIR - wz end          -- miroir du lac : la langue dessinée à l'envers
        v3:SetUnpacked(cx + math.cos(a) * r, cy + math.sin(a) * r, wz)
        if coeur == 0 then
          local R, G, B = tor_couleur(math.min(1, h / H))
          local vac = 0.75 + 0.25 * math.sin(now * 23 + i * 2.1 + j * 1.7)
          col.r, col.g, col.b, col.a = R, G, B, 255 * fade * dv * ma
          render.AddBeam(v3, (20 + 55 * math.sin(math.pi * v)) * fade * vac * 0.95 * s, v - now * 2.5, col)
        else
          col.r, col.g, col.b, col.a = 255, 150 - 90 * v, 50, 220 * fade * dv * ma
          render.AddBeam(v3, (6 + 20 * math.sin(math.pi * v) * (1 - v * 0.6)) * fade * 1.4 * s, v * 1.3 - now * 3.1, col)
        end
      end
      render.EndBeam()
    end
  end
  if MIROIR then return end                       -- pas de colonne de chaleur dans le reflet
  render.SetMaterial(HALO)                        -- colonne de chaleur le long de la lame
  local f = (0.8 + 0.2 * math.sin(now * 9)) * math.min(1, force)
  col.r, col.g, col.b, col.a = 255, 90, 30, 22 * f
  for i = 0, 6 do v3:SetUnpacked(cx, cy, cz + (40 + i * 95) * s); render.DrawSprite(v3, (150 - i * 8) * s, (150 - i * 8) * s, col) end
end
local hamon, hamon_t = {}, 0
local function tor_trempe(c, force, now)          -- la ligne de trempe (hamon) : lueur carmin qui bat avec le feu
  if now > hamon_t then
    hamon_t = now + 2; hamon = {}
    for _, x in ipairs(ents.FindByModel("models/hunter/plates/plate025x16.mdl")) do
      local p = x:GetPos()
      if math.abs(p.x - c.x) < 80 and math.abs(p.y - c.y) < 80 then hamon[#hamon + 1] = { x, p, x:GetRight(), x:GetUp() } end
    end
  end
  for k, h in ipairs(hamon) do
    if IsValid(h[1]) then
      local p, ax, nz = h[2], h[3], h[4]
      local f = (0.75 + 0.25 * math.sin(now * 6 + k * 0.9)) * force
      local A, B, col = Q.v, Q.v2, Q.c4             -- optimisation 25/11 : aucun Vector ni Color par trait
      for sg = -1, 1, 2 do
        local o = 0.9 * sg
        A:SetUnpacked(p.x - ax.x * 66 + nz.x * o, p.y - ax.y * 66 + nz.y * o, p.z - ax.z * 66 + nz.z * o)
        B:SetUnpacked(p.x + ax.x * 66 + nz.x * o, p.y + ax.y * 66 + nz.y * o, p.z + ax.z * 66 + nz.z * o)
        col.r, col.g, col.b, col.a = 255, 70, 40, 70 * f
        render.SetMaterial(HALO); render.DrawBeam(A, B, 9, 0, 1, col)
        col.r, col.g, col.b, col.a = 255, 190, 150, 170 * f
        if TOR_LASER then render.SetMaterial(TOR_LASER); render.DrawBeam(A, B, 1.6, 0, 1, col) end
      end
    end
  end
end
local function epee_dessin(now)
  TOR_VUE = EyePos()
  local s, force = tor_niveau()
  local c = W(EPEE.x, EPEE.y, ZI)
  if s > 0.01 then tor_langues(c, s, force, now); tor_trempe(c, math.min(1, force), now) end
  if tor_em and tor_em:IsValid() then tor_em:Draw() end
end

-- ---------- les lanternes du trône (Adrien 2 h 26 : « en faire un vrai moment ») ----------
-- Flamme spectrale bleu froid : elle tranche avec le carmin des veines et du fil de braise, et annonce le rai froid du siège.
-- Éteintes au calme ; à l'éveil, chacune s'allume quand l'allumage des veines arrive à sa hauteur (l'une après l'autre) ;
-- au siège vide, celle de droite se souffle avec un filet de fumée, celle de gauche reste allumée, faible et vacillante :
-- une veille pour un roi qui ne vient pas (l'absence se lit mieux avec une flamme qui attend qu'avec le noir complet).
local LANT = {}                                   -- { x, y, z de la flamme ; d : distance des veines la plus proche }
-- foyer mesuré sur le maillage (huecomundosetails25 : pied z -35 à -15, fût, tête en coupe z +15 à +25, chapeau), par le build
for _, f in ipairs({ {-166.0, 195.0, 203.3}, {166.0, 195.0, 203.3} }) do LANT[#LANT + 1] = { x = f[1], y = f[2], z = f[3], sd = f[1] < TRONE.x and -1 or 1 } end
for _, l in ipairs(LANT) do
  local best, bd = 1e9, DMAX
  for _, v in ipairs(VEINES) do for _, p in ipairs(v) do
    local q = (p[1] - l.x) ^ 2 + (p[2] - l.y) ^ 2
    if q < best then best, bd = q, p[3] end
  end end
  l.d = bd
end
table.sort(LANT, function(a, b) return a.d < b.d end)
LANT[1].t = 0.5 + LANT[1].d / 330 + 0.25; LANT[2].t = math.max(0.5 + LANT[2].d / 330 + 0.25, LANT[1].t + 0.8)
local VEILLE = LANT[1].sd == -1 and 1 or 2        -- la lanterne de gauche (côté -x) reste allumée
local SOUFFLE = { [3 - VEILLE] = RETOMBE + 1.6, [VEILLE] = RETOMBE + 3.4 }   -- au siège : soufflée (l'autre ne fait que baisser)
local function lant_niveau(i)
  local l = LANT[i]
  if phase == "eveil" then return lisse((instant - l.t) / 0.35) end
  if phase == "plein" then return 1 end
  if phase == "siege" then
    local u = instant - SOUFFLE[i]
    if i == VEILLE then return 1 - 0.72 * lisse(u / 1.2) end
    return 1 - lisse(u / 0.25)
  end
  return 0
end
local function lanternes_dessin(now)
  render.SetMaterial(HALO)
  for i, l in ipairs(LANT) do
    local n = lant_niveau(i)
    if n > 0.01 then
      local vac = 0.85 + 0.1 * math.sin(now * 11 + i * 2) + 0.05 * math.sin(now * 27 + i)
      if i == VEILLE and phase == "siege" then vac = vac * (0.8 + 0.2 * math.sin(now * 3.7)) end
      local p = W(l.x, l.y, l.z); local k = n * vac
      render.DrawSprite(p + Vector(0, 0, 4), 70 * k, 70 * k, Color(70, 130, 255, 90 * k))            -- lueur
      render.DrawSprite(p + Vector(0, 0, 6), 13 * k, 26 * k, Color(120, 185, 255, 230 * k))          -- flamme
      render.DrawSprite(p + Vector(0, 0, 4), 5 * k, 10 * k, Color(225, 240, 255, 255 * k))           -- cœur
    end
  end
end
local lant_avant, lant_etin = {}, 0
local function lanternes_vie(now, e)              -- allumage (éclat d'étincelles), lumière, souffle (fumée)
  for i, l in ipairs(LANT) do
    local n = lant_niveau(i)
    local p = W(l.x, l.y, l.z + 6)
    local etait = lant_avant[i] or 0
    if n > 0.5 and etait <= 0.5 then
      LocalPlayer():EmitSound("ambient/fire/ignite.wav", 70, 140, 0.5)
      for _ = 1, 18 do
        local q = e:Add("effects/spark", p)
        if q then q:SetVelocity(VectorRand() * 60 + Vector(0, 0, 50)); q:SetGravity(Vector(0, 0, -200)); q:SetDieTime(math.Rand(0.4, 0.8))
          q:SetStartAlpha(255); q:SetEndAlpha(0); q:SetStartSize(1.5); q:SetEndSize(0); q:SetStartLength(6); q:SetEndLength(0); q:SetColor(150, 200, 255) end
      end
    end
    if phase == "siege" and i ~= VEILLE and n < 0.5 and etait >= 0.5 and #FUMEE > 0 then   -- soufflée : un filet de fumée
      for j = 0, 10 do
        local q = e:Add(FUMEE[math.random(#FUMEE)], p + Vector(0, 0, j * 2))
        if q then q:SetVelocity(Vector(math.Rand(-3, 3), math.Rand(-3, 3), math.Rand(18, 30))); q:SetDieTime(math.Rand(2.5, 3.5))
          q:SetStartAlpha(70); q:SetEndAlpha(0); q:SetStartSize(3); q:SetEndSize(22); q:SetRoll(math.Rand(0, 360)); q:SetRollDelta(math.Rand(-0.4, 0.4)); q:SetColor(150, 155, 170) end
      end
    end
    lant_avant[i] = n
    if n > 0.3 and now > lant_etin and math.random() < 0.25 then                            -- petites étincelles qui montent
      local q = e:Add("effects/spark", p + Vector(math.Rand(-2, 2), math.Rand(-2, 2), 4))
      if q then q:SetVelocity(Vector(math.Rand(-6, 6), math.Rand(-6, 6), math.Rand(25, 50))); q:SetDieTime(math.Rand(0.5, 0.9))
        q:SetStartAlpha(220 * n); q:SetEndAlpha(0); q:SetStartSize(0.8); q:SetEndSize(0); q:SetStartLength(3); q:SetEndLength(0); q:SetColor(160, 210, 255) end
    end
    if n > 0.05 then
      Q.lum(7840 + i, 2, l.x + off.x, l.y - 10 + off.y, l.z + 10 + off.z, 90, 150, 255, 2.2 * n, 260 * n)
    end
  end
  lant_etin = now + 0.04
end

-- ---------- trône : fil de braise de la fente, rai froid sur l'assise ----------
local function trone_dessin()
  if not fente then return end
  local f = niveau_fente()
  if f > 0.01 then
    local p = 0.62 + 0.38 * math.min(1, coeur())                     -- passe 4 du lac : le trône bat, le lac répond
    local y = fente.y - 0.6; local h = fente.z1 - fente.z0 - 4; local zm = (fente.z0 + fente.z1) / 2
    render.SetColorMaterial()
    render.DrawQuadEasy(Vector(fente.x, y, zm), Vector(0, -1, 0), fente.l * 0.7, h, Color(255, 40 + 50 * p, 30, 255 * f), 0)
    render.SetMaterial(HALO)
    render.DrawBeam(Vector(fente.x, y - 0.5, fente.z0 + 2), Vector(fente.x, y - 0.5, fente.z1 - 2), 14 * p, 0, 1, Color(255, 50, 40, 200 * p * f))
    for i = 0, 9 do
      render.DrawSprite(Vector(fente.x, y - 1, fente.z0 + (fente.z1 - fente.z0) * i / 9), 26 * p, 26 * p, Color(220, 20, 35, 110 * p * f))
    end
  end
  local c = niveau_froid()
  if c > 0.01 then                                                     -- le rai : un faisceau pâle qui tombe sur l'assise
    render.SetMaterial(HALO)
    local haut, bas = Vector(fente.x, fente.y - 90, fente.z1 + 260), Vector(fente.x, fente.y - 55, ASSISE + off.z + 6)
    render.DrawBeam(haut, bas, 150, 0, 1, Color(150, 190, 255, 26 * c))
    render.DrawBeam(haut, bas, 60, 0, 1, Color(190, 215, 255, 30 * c))
  end
end

-- ---------- particules : brume, poussière de la secousse, poussière du rai ----------
local em, brumes = nil, {}
local function emetteur() if not (em and em:IsValid()) then em = ParticleEmitter(W(EPEE.x, EPEE.y, ZI), false) end return em end
local function brume(n)
  if #FUMEE == 0 then return end
  for _ = 1, n do
    local c = CONTOUR[math.random(#CONTOUR)]
    local cx, cy = c[1] + math.Rand(-40, 40), c[2] + math.Rand(-40, 40)
    local d = Vector(cx - EPEE.x, cy, 0); d:Normalize()
    local p = emetteur():Add(FUMEE[math.random(#FUMEE)], W(cx, cy, EAU + math.Rand(6, 26)))
    if p then
      p:SetVelocity(d * math.Rand(5, 14) + Vector(-d.y, d.x, 0) * math.Rand(-4, 4))
      p:SetDieTime(math.Rand(8, 11)); p:SetStartAlpha(85); p:SetEndAlpha(0)
      p:SetStartSize(math.Rand(60, 90)); p:SetEndSize(math.Rand(130, 170))
      p:SetRoll(math.Rand(0, 360)); p:SetRollDelta(math.Rand(-0.08, 0.08)); p:SetColor(160, 166, 182)
      brumes[#brumes + 1] = p
    end
  end
end
local function chasser_brume()                    -- l'onde de choc pousse la brume vers le large
  local c = W(EPEE.x, EPEE.y, EAU)
  for _, p in ipairs(brumes) do
    local d = p:GetPos() - c; d.z = 0; local l = d:Length(); d:Normalize()
    p:SetVelocity(d * math.Clamp(9000 / math.max(l, 200), 25, 160) + Vector(0, 0, 8)); p:SetAirResistance(35)
  end
end
local function figer_brume()
  for _, p in ipairs(brumes) do
    p:SetVelocity(Vector()); p:SetRollDelta(0); p:SetColor(190, 196, 212)
    p:SetDieTime(math.max(p:GetDieTime(), p:GetLifeTime() + 12)); p:SetEndAlpha(70)
  end
end
-- optimisation 25/11 : les 130 particules de la secousse sont semées sur 0,4 s (avant : toutes dans la même image, au
-- changement de plan de l'éveil, d'où l'accroc). secousse() lance, Q.secousse_pas(now) sème la part due à chaque image.
Q.sec_t0, Q.sec_fait, Q.SEC_N, Q.SEC_D = nil, 0, 130, 0.4
local function secousse() Q.sec_t0, Q.sec_fait = CurTime(), 0 end
function Q.secousse_un(i)
  if i <= 80 then
    if #FUMEE == 0 then return end
    local c = CONTOUR[math.random(#CONTOUR)]
    local p = emetteur():Add(FUMEE[math.random(#FUMEE)], W(c[1] * 0.92, c[2] * 0.92, math.Rand(ZI - 30, ZI + 5)))
    if p then
      p:SetVelocity(Vector(math.Rand(-20, 20), math.Rand(-20, 20), math.Rand(-40, 30))); p:SetDieTime(math.Rand(1.5, 2.5))
      p:SetStartAlpha(120); p:SetEndAlpha(0); p:SetStartSize(25); p:SetEndSize(85); p:SetColor(95, 85, 80)
      p:SetRoll(math.Rand(0, 360)); p:SetRollDelta(math.Rand(-0.5, 0.5))
    end
  else
    local a, r = math.Rand(0, 6.283), math.Rand(30, 420)
    local p = emetteur():Add("effects/fleck_cement" .. math.random(1, 2), W(EPEE.x, EPEE.y, ZI + 2) + Vector(math.cos(a) * r, math.sin(a) * r, 0))
    if p then
      p:SetVelocity(Vector(0, 0, math.Rand(60, 150))); p:SetGravity(Vector(0, 0, -600)); p:SetDieTime(1.3)
      p:SetStartAlpha(255); p:SetEndAlpha(255); p:SetStartSize(2); p:SetEndSize(2); p:SetColor(70, 66, 72)
      p:SetCollide(true); p:SetBounce(0.3); p:SetRoll(math.Rand(0, 360)); p:SetRollDelta(math.Rand(-8, 8))
    end
  end
end
function Q.secousse_pas(now)
  if not Q.sec_t0 then return end
  local cible = math.floor(math.min(1, (now - Q.sec_t0) / Q.SEC_D) * Q.SEC_N)
  for i = Q.sec_fait + 1, cible do Q.secousse_un(i) end
  Q.sec_fait = cible
  if cible >= Q.SEC_N then Q.sec_t0 = nil end
end
local function poussiere_rai(c)
  if not fente then return end
  local q = emetteur():Add("sprites/light_glow02_add",
    Vector(fente.x + math.Rand(-45, 45), fente.y - math.Rand(25, 95), ASSISE + off.z + math.Rand(-10, 150)))
  if q then
    q:SetVelocity(Vector(math.Rand(-2, 2), math.Rand(-2, 2), math.Rand(-3, 1))); q:SetDieTime(math.Rand(4, 7))
    q:SetStartAlpha(0); q:SetEndAlpha(0); q:SetStartSize(1.8); q:SetEndSize(1.3); q:SetColor(200, 225, 255)
    q:SetNextThink(CurTime()); q:SetThinkFunction(function(pa)
      local u = pa:GetLifeTime() / pa:GetDieTime(); pa:SetStartAlpha(110 * c * math.sin(u * math.pi)); pa:SetNextThink(CurTime() + 0.05) end)
  end
end

