-- secousse de caméra souple (optimisation 25/11) : remplace util.ScreenShake (bruit sec à 30-40 Hz, amplitude 14, qui faisait
-- accrocher et traverser l'image au boom). Ici des sinus lents qui s'amortissent : à l'éveil (8 s) puis à l'onde de choc (9 s).
Q.SECOUSSES = { { 8, 3, 1.2 }, { 9, 8, 1.6 } }   -- instant, amplitude (u), durée (s)
function Q.tremble(T)
  local k = 0
  for _, e in ipairs(Q.SECOUSSES) do local u = (T - e[1]) / e[3]; if u >= 0 and u < 1 then k = k + e[2] * (1 - u) * (1 - u) end end
  return k
end
-- ---------- caméra : 4 plans, glissés lentement ----------
local PLANS = {   -- de, à : {x, y, z} dans le repère de l'île ; cible ; fov ; t début, t fin (passe 3 : le lac et l'île)
  { 24.5, 28, { 260, -1500, 40 }, { 230, -1380, 46 }, { 0, 4800, 520 }, 34 },        -- scène complète : plan court, bas, longue focale : épée, tornade, trône, la cathédrale derrière, le haut coupé
  { 34, 40, { 0, 520, 262 }, { 0, 575, 252 }, { 0, 4800, 545 }, 22 },              -- contrechamp depuis le trône vers la cathédrale (long : l'attente, le battement)
  { 0, 8, { -520, -2250, 38 }, { -320, -1750, 48 }, { 0, 0, 150 }, 55 },                     -- au ras de l'eau : l'île et son reflet
  { 8, 14, { -2300, -2150, 1500 }, { -1950, -1750, 1350 }, { 0, 600, 0 }, 64 },              -- l'onde traverse le lac, les veines s'allument
  { 14, 20, { 650, 450, 60 }, { 1050, 1100, 55 }, { 2600, 3400, 0 }, 62 },                   -- le long d'une veine, vers le large
  { 20, 28, { 950, -1350, 55 }, { 720, -1050, 75 }, { 0, -65, 300 }, 60 },                  -- la tornade au plus fort et son reflet
  { 28, 40, { 230, -1750, 32 }, { 170, -1350, 40 }, { 0, TRONE.y + 20, ASSISE }, 42 },       -- le siège vide et son reflet
}
local function camera(T)
  for _, p in ipairs(PLANS) do
    if T >= p[1] and T < p[2] then
      local u = lisse((T - p[1]) / (p[2] - p[1]))
      local a, b, c = p[3], p[4], p[5]
      local pos = W(Lerp(u, a[1], b[1]), Lerp(u, a[2], b[2]), Lerp(u, a[3], b[3]))
      local ang = (W(c[1], c[2], c[3]) - pos):Angle()
      local k = Q.tremble(T)
      if k > 0.01 then
        pos.x = pos.x + k * (0.6 * math.sin(T * 71) + 0.4 * math.sin(T * 113))
        pos.y = pos.y + k * (0.6 * math.sin(T * 83 + 1.7) + 0.4 * math.sin(T * 127))
        pos.z = pos.z + k * (0.7 * math.sin(T * 97 + 0.6) + 0.3 * math.sin(T * 149))
        ang.p = ang.p + k * 0.06 * math.sin(T * 89); ang.y = ang.y + k * 0.05 * math.sin(T * 79 + 2.1)
      end
      return pos, ang, p[6]
    end
  end
end

local lac_lumiere, lac_plouf
-- ======================================================================================================================
-- LE LAC (pièce 3, passe 3, Adrien 2 h 46 : « go pour toutes les améliorations ») : inséré par lac_noir_lac_demo/build.py
-- dans la démo de l'île (même ligne de temps de 40 s). Repère : celui de l'île (le lac s'étend de LAC_X0 à LAC_Y1).
--  - vrai miroir : copie à l'envers de l'île, du trône et de l'épée (ClientsideModel, matrice z négative), des langues de
--    feu de la tornade et des lanternes, de l'éclipse ; rendu au pochoir (stencil) là où l'eau est visible, assombri, teinté
--    bleu nuit, qui ondule ; la couche de réfraction (shadertest) posée par-dessus le déforme vraiment
--  - veines du lac en deux couches : magma flou et sombre au fond (sous la réfraction), cœur net qui affleure par moments ;
--    elles s'allument quand le liseré carmin de l'onde de choc passe sur elles, s'éteignent du large vers l'île
--  - reflets en larges bandes (feu de la tornade qui tremble, chemin de lumière de l'éclipse pailleté en continu)
--  - rive vivante (écume sombre, hauts-fonds plus clairs), brume en nappe et brume de bord, rides, braises qui sifflent
-- ======================================================================================================================
-- ---------- le miroir ----------
local miroirs, miroir_ms, fps_n, fps_s = {}, 0, 0, 0
local S = Matrix(); S:Scale(Vector(1, 1, -1))
local function miroir_creer()
  for _, m in ipairs(miroirs) do if IsValid(m.e) then m.e:Remove() end end
  miroirs = {}
  for _, d in ipairs(MODELES) do
    local e = ClientsideModel(d[1], RENDERGROUP_OPAQUE)
    if IsValid(e) then
      e:SetNoDraw(true)
      local R = Matrix(); R:SetAngles(Angle(d[5], d[6], d[7]))
      local Rp = S * R * S                                   -- rotation miroir (z → -z dans le monde)
      e:SetAngles(Rp:GetAngles())
      local k = Matrix(); k:Scale(Vector(d[8], d[8], -d[8])); e:EnableMatrix("RenderMultiply", k)
      if d[12] ~= "" then e:SetMaterial(d[12]) end
      miroirs[#miroirs + 1] = { e = e, x = d[2], y = d[3], z = 2 * MZ - d[4], r = d[9] / 255, g = d[10] / 255, b = d[11] / 255 }
    end
  end
end
local function eclipse_miroir()                         -- l'éclipse à l'envers : anneau pâle, liseré sang
  local cx, cy, cz = ECLIPSE.x + off.x, ECLIPSE.y + off.y, 2 * MZ - ECLIPSE.z + off.z   -- optimisation 25/11 : objets réutilisés
  local v, col = Q.v, Q.coul
  render.SetColorMaterial()
  col.r, col.g, col.b, col.a = 190, 200, 222, 110
  render.StartBeam(61)
  for i = 0, 60 do local a = i / 60 * 6.2832
    v:SetUnpacked(cx + math.cos(a) * ECL_R, cy, cz + math.sin(a) * ECL_R); render.AddBeam(v, 26, 0, col) end
  render.EndBeam()
  col.r, col.g, col.b, col.a = 150, 20, 25, 120
  render.StartBeam(61)
  for i = 0, 60 do local a = i / 60 * 6.2832
    v:SetUnpacked(cx + math.cos(a) * (ECL_R - 30), cy, cz + math.sin(a) * (ECL_R - 30)); render.AddBeam(v, 8, 0, col) end
  render.EndBeam()
  col.r, col.g, col.b, col.a = 120, 135, 175, 40
  v:SetUnpacked(cx, cy, cz); render.SetMaterial(HALO); render.DrawSprite(v, ECL_R * 3.2, ECL_R * 3.2, col)
end
local function lanternes_miroir(now)
  render.SetMaterial(HALO)
  for i, l in ipairs(LANT) do
    local n = lant_niveau(i)
    if n > 0.01 then
      local p = W(l.x, l.y, 2 * MZ - l.z); local k = n * (0.85 + 0.15 * math.sin(now * 11 + i * 2))
      render.DrawSprite(p - Vector(0, 0, 5), 80 * k, 110 * k, Color(70, 130, 255, 60 * k))
      render.DrawSprite(p - Vector(0, 0, 6), 12 * k, 28 * k, Color(120, 185, 255, 150 * k))
    end
  end
end
-- optimisation 25/11 : objets de travail réutilisés (AddBeam, DrawSprite, DrawQuad et mesh.Position copient leurs valeurs)
Q.v2, Q.v3, Q.v4, Q.haut = Vector(), Vector(), Vector(), Vector(0, 0, 1)
Q.c2, Q.c3, Q.noir = Color(0, 0, 0, 0), Color(0, 0, 0, 0), Color(0, 0, 0, 255)
local function eau_quad(z, col)                          -- toute la surface du lac
  local ox, oy, oz = off.x, off.y, off.z + z
  Q.v:SetUnpacked(LAC_X0 + ox, LAC_Y0 + oy, oz); Q.v2:SetUnpacked(LAC_X0 + ox, LAC_Y1 + oy, oz)
  Q.v3:SetUnpacked(LAC_X1 + ox, LAC_Y1 + oy, oz); Q.v4:SetUnpacked(LAC_X1 + ox, LAC_Y0 + oy, oz)
  render.DrawQuad(Q.v, Q.v2, Q.v3, Q.v4, col)
end
local function lac_profond(t)                            -- veines du fond : magma flou et sombre (sous la réfraction)
  render.SetMaterial(HALO)
  local v, col, ox, oy, z = Q.v, Q.c2, off.x, off.y, off.z + NOIR_Z + 2.6
  col.r, col.g, col.b = 150, 12, 16
  for _, ve in ipairs(LVEINES) do
    render.StartBeam(#ve)
    for i, a in ipairs(ve) do
      local l = lac_lumiere(a, t); if l > 1 then l = 1 end
      v:SetUnpacked(a[1] + ox, a[2] + oy, z); col.a = 150 * l
      render.AddBeam(v, (34 + 10 * a[4]) * (0.6 + 0.4 * l), i * 0.15, col)
    end
    render.EndBeam()
  end
end
-- passe 4 : le voile dépend de l'angle (Fresnel). Au ras de l'eau le lac renvoie le ciel et l'île (reflet fort), vu de haut
-- on voit dans l'eau, noire. Grille polaire autour du pied de l'œil, alpha par sommet ; zones calmes (miroir) et ridées.
local VOILE = CreateMaterial("lac_eau_voile_p4", "UnlitGeneric", { ["$basetexture"] = "color/white", ["$vertexcolor"] = 1, ["$vertexalpha"] = 1, ["$translucent"] = 1 })
local ANNEAUX_V = { 0, 40, 90, 160, 260, 400, 600, 850, 1200, 1700, 2400, 3300, 4500, 6000, 8000, 11000 }
local SECT_V = 36
local function zone(x, y, t)                               -- 1 : plaque calme en miroir ; ~0,45 : eau ridée
  return 0.72 + 0.28 * math.sin(x / 650 + t * 0.04) * math.cos(y / 820 - t * 0.03) + 0.1 * math.sin((x + y) / 310 + t * 0.07)
end
local function fresnel(h, d)
  local c = h / math.sqrt(h * h + d * d)
  return 0.03 + 0.97 * (1 - c) ^ 5
end
local VS = { ox = 0, oy = 0, h = 0, z = 0, k = 0, t = 0 }   -- état du voile pour l'image (aucune fermeture créée par image)
function VS.f(r, an)
  local x, y = VS.ox + math.cos(an) * r, VS.oy + math.sin(an) * r
  local q = 0.62 * fresnel(VS.h, r) * math.Clamp(zone(x - off.x, y - off.y, VS.t), 0.35, 1) * VS.k
  Q.v:SetUnpacked(x, y, VS.z); mesh.Position(Q.v); mesh.Color(1, 2, 6, 255 * (1 - q)); mesh.AdvanceVertex()
end
local function voile_fresnel(t)
  local o = EyePos(); local h = math.max(4, o.z - (MZ + off.z))
  VS.ox, VS.oy, VS.h, VS.z, VS.t = o.x, o.y, h, NOIR_Z + off.z + 2.3, t
  VS.k = math.Clamp(1 - (h - 90) / 450, 0.03, 1)             -- vu de haut, le lac reste noir
  local sommet = VS.f
  render.SetMaterial(VOILE)
  mesh.Begin(MATERIAL_QUADS, (#ANNEAUX_V - 1) * SECT_V)
  for i = 1, #ANNEAUX_V - 1 do
    local r1, r2 = ANNEAUX_V[i], ANNEAUX_V[i + 1]
    for j = 0, SECT_V - 1 do
      local a1, a2 = j / SECT_V * 6.2832, (j + 1) / SECT_V * 6.2832
      sommet(r1, a1); sommet(r2, a1); sommet(r2, a2); sommet(r1, a2)
    end
  end
  mesh.End()
end
local function miroir_passe(t)
  local t1 = SysTime()
  render.ClearStencil(); render.SetStencilEnable(true)
  render.SetStencilWriteMask(255); render.SetStencilTestMask(255); render.SetStencilReferenceValue(1)
  render.SetStencilCompareFunction(STENCIL_ALWAYS); render.SetStencilPassOperation(STENCIL_REPLACE)
  render.SetStencilFailOperation(STENCIL_KEEP); render.SetStencilZFailOperation(STENCIL_KEEP)
  render.OverrideColorWriteEnable(true, false)
  render.SetColorMaterial(); eau_quad(NOIR_Z + 2.0, Q.noir)   -- l'eau visible (l'île la cache où elle est devant)
  render.OverrideColorWriteEnable(false, false)
  render.SetStencilCompareFunction(STENCIL_EQUAL); render.SetStencilPassOperation(STENCIL_KEEP)
  render.ClearBuffersObeyStencil(46, 52, 68, 255, true) -- le ciel renvoyé (le voile de Fresnel l'assombrit), profondeur remise à zéro
  -- les modèles à l'envers, éclairés de façon plate (ils sont sous le sol : l'éclairage du jeu les rendrait noirs)
  render.CullMode(MATERIAL_CULLMODE_CW)
  render.SuppressEngineLighting(true)
  render.ResetModelLighting(0.85, 0.86, 0.98)
  render.SetModelLighting(BOX_BOTTOM, 1.5, 1.5, 1.7)     -- le haut des objets, vu à l'envers
  local fige_eau = fige()
  for i, m in ipairs(miroirs) do
    if IsValid(m.e) then
      -- la houle (passe 4) : lente et large, chaque pièce dérive un peu différemment, le reflet se tord doucement
      local hx = fige_eau and 0 or math.sin(t * 0.45 + m.y / 520) * 9 + math.sin(t * 1.3 + m.y / 140 + i * 0.2) * 2.5
      local hy = fige_eau and 0 or math.cos(t * 0.38 + m.x / 610 + m.z / 90) * 6
      m.e:SetPos(W(m.x + hx, m.y + hy, m.z))
      render.SetColorModulation(math.max(0.35, m.r) * 0.9, math.max(0.35, m.g) * 0.9, math.max(0.4, m.b))
      m.e:DrawModel()
    end
  end
  render.SetColorModulation(1, 1, 1)
  render.SuppressEngineLighting(false)
  render.CullMode(MATERIAL_CULLMODE_CCW)
  -- la tornade à l'envers (ses langues de feu), les lanternes, l'éclipse
  local s, force = tor_niveau()
  if s > 0.01 then MIROIR, MIR_A = MZ + off.z, 0.5; tor_langues(W(EPEE.x, EPEE.y, ZI), s, force, CurTime()); MIROIR, MIR_A = nil, 1 end
  lanternes_miroir(CurTime())
  eclipse_miroir()
  -- le voile de l'eau : assombrit et teinte le reflet (lie-de-vin très sombre près de l'île quand le feu est là)
  voile_fresnel(t)
  lac_profond(t)
  render.SetStencilEnable(false)
  miroir_ms = miroir_ms * 0.95 + (SysTime() - t1) * 1000 * 0.05
end
local HZ = { cle = nil, sol = nil, mur = nil, c = Color(5, 5, 8, 255) }
HZ.bandes = { { -400, 900, 255, 255 }, { 900, 3400, 255, 0 } }
function HZ.geo()                                -- optimisation : géométrie fixe, calculée une fois par collage
  local z, F = NOIR_Z + 0.6, 60000
  HZ.sol = {
    { W(-F, LAC_Y1, z), W(F, LAC_Y1, z), W(F, F, z), W(-F, F, z) },
    { W(-F, -F, z), W(F, -F, z), W(F, LAC_Y0, z), W(-F, LAC_Y0, z) },
    { W(-F, LAC_Y0, z), W(LAC_X0, LAC_Y0, z), W(LAC_X0, LAC_Y1, z), W(-F, LAC_Y1, z) },
    { W(LAC_X1, LAC_Y0, z), W(F, LAC_Y0, z), W(F, LAC_Y1, z), W(LAC_X1, LAC_Y1, z) } }
  local cx, cy, R, N = (LAC_X0 + LAC_X1) / 2, (LAC_Y0 + LAC_Y1) / 2, 15000, 72
  HZ.mur = {}
  for i = 0, N - 1 do
    local a1, a2 = i / N * 6.2832, (i + 1) / N * 6.2832
    local x1, y1, x2, y2 = cx + math.cos(a1) * R, cy + math.sin(a1) * R, cx + math.cos(a2) * R, cy + math.sin(a2) * R
    for _, b in ipairs(HZ.bandes) do
      HZ.mur[#HZ.mur + 1] = { W(x1, y1, b[1]), b[3], W(x2, y2, b[1]), b[3], W(x2, y2, b[2]), b[4], W(x1, y1, b[2]), b[4] }
    end
  end
  HZ.cle = Vector(off.x, off.y, off.z)
end
local function horizon()                                    -- passe 5 : l'herbe et les collines de gm_flatgrass disparaissent
  if not HZ.cle or HZ.cle ~= off then HZ.geo() end
  render.SetColorMaterial()
  render.CullMode(MATERIAL_CULLMODE_NONE)
  for i = 1, 4 do local q = HZ.sol[i]; render.DrawQuad(q[1], q[2], q[3], q[4], HZ.c) end
  render.SetMaterial(VOILE)
  mesh.Begin(MATERIAL_QUADS, #HZ.mur)
  for i = 1, #HZ.mur do
    local q = HZ.mur[i]
    for j = 1, 7, 2 do mesh.Position(q[j]); mesh.Color(14, 16, 22, q[j + 1]); mesh.AdvanceVertex() end
  end
  mesh.End()
  render.CullMode(MATERIAL_CULLMODE_CCW)
end
hook.Add("PostDrawOpaqueRenderables", "lac_eau_demo", function(prof, ciel)
  if prof or ciel or not t0 or not off then return end
  horizon()
  if CATH then CATH.opaque() end              -- la cathédrale avant le miroir (le pied passe sous l'eau)
  miroir_passe(CurTime())
end)

-- ---------- les veines du lac : allumées par le liseré de l'onde de choc, éteintes du large vers l'île ----------
local function choc_rayon() if phase == "eveil" and instant >= CHOC[1].t then return CHOC_R0 + CHOC_V * (instant - CHOC[1].t) end end
local function coeur_force() if phase == "siege" then return 0.7 end return niveau_fente() end
local function coeur_rayon()                                -- l'onde douce du dernier battement, partie de l'île
  local s = coeur_ph() * COEUR_P
  return s * 2400, math.max(0, 1 - s / 1.5)
end
local lumiere_base
lac_lumiere = function(a, t)
  local l = lumiere_base(a, t)
  local f = coeur_force()
  if f > 0.02 then
    local R, fade = coeur_rayon()
    l = l + 0.5 * f * fade * math.exp(-((a[5] - R) / 230) ^ 2)
  end
  return l
end
lumiere_base = function(a, t)                               -- a = {x, y, d, largeur, distance à l'épée}
  local dort = 0                                          -- v80 : fissures noires avant le boum
  if phase == "calme" then return dort end
  if phase == "eveil" then
    local R = choc_rayon()
    if not R or a[5] > R then return dort end
    return 0.65 + 0.35 * (0.5 + 0.5 * math.sin(t * 1.6 - a[3] / 160)) + 1.2 * math.max(0, 1 - (R - a[5]) / 260)
  end
  if phase == "plein" then return (0.65 + 0.35 * (0.5 + 0.5 * math.sin(t * 1.6 - a[3] / 160))) * 1.1 end
  local s = math.max(0, instant - RETOMBE)
  local E = LMAX - s * (LMAX / 3.0)
  return math.Clamp((E - a[5]) / 300, 0, 1) * (0.65 + 0.35 * (0.5 + 0.5 * math.sin(t * 1.6 - a[3] / 160)))
end
local lnorm = {}
local function lnormale(v, i)
  lnorm[v] = lnorm[v] or {}
  if not lnorm[v][i] then
    local a, b = v[math.max(1, i - 1)], v[math.min(#v, i + 1)]
    local d = Vector(b[1] - a[1], b[2] - a[2], 0); d:Normalize(); lnorm[v][i] = Vector(-d.y, d.x, 0)
  end
  return lnorm[v][i]
end
-- Optimisation (25/11, mesure : 12,8 ms par image pour 2 600 points) : géométrie calculée une fois par collage, lumière
-- calculée une fois par point, une seule couleur réutilisée, rien derrière la caméra ni au-delà de la distance de qualité
-- (convar lac_qualite 0/1/2), bords et cœurs dans un seul maillage (Q, lots de 4 000 quads au plus).
Q.qualite = CreateClientConVar("lac_qualite", "1", true, false, "Lac noir : qualité des effets (0 bas, 1 normal, 2 haut)", 0, 2)
Q.coul = Color(0, 0, 0, 0)
local function lac_geo(z)
  if Q.lgeo and Q.lcle == off then return Q.lgeo end
  local g = {}
  for k, v in ipairs(LVEINES) do
    local wp, seg = {}, {}
    for i, a in ipairs(v) do wp[i] = W(a[1], a[2], z + 0.2) end
    for i = 1, #v - 1 do
      local a, b = v[i], v[i + 1]
      local pa, pb = W(a[1], a[2], z), W(b[1], b[2], z)
      local na, nb = lnormale(v, i), lnormale(v, i + 1)
      seg[i] = { bord = Q.bande(pa, na, a[4] * 0.45, pb, nb, b[4] * 0.45), coeur = Q.bande(pa, na, a[4] * 0.16, pb, nb, b[4] * 0.16),
        mx = (pa.x + pb.x) * 0.5, my = (pa.y + pb.y) * 0.5, mz = (pa.z + pb.z) * 0.5 }
    end
    g[k] = { wp = wp, seg = seg, l = {}, c = {} }
  end
  Q.lgeo, Q.lcle = g, Vector(off.x, off.y, off.z)
  return g
end
local function lac_veines(t)                             -- le cœur net, qui affleure par moments (au-dessus de la réfraction)
  local z = MZ + 1.4
  local R = choc_rayon()
  local g = lac_geo(z)
  local q = Q.qualite:GetInt()
  local dmax = (q == 0 and 2500) or (q == 1 and 4500) or 1e9
  local dmax2 = dmax * dmax
  local eye, fwd = EyePos(), EyeAngles():Forward()
  local ex, ey, ez, fx, fy, fz = eye.x, eye.y, eye.z, fwd.x, fwd.y, fwd.z
  local tous = (phase == "eveil" or phase == "plein")
  local col = Q.coul
  -- 1. lumière une fois par point
  for k = 1, #LVEINES do
    local v, gk = LVEINES[k], g[k]
    local L, C = gk.l, gk.c
    for i = 1, #v do
      local a = v[i]
      local l = lac_lumiere(a, t)
      local af = tous and 1 or math.Clamp(math.sin(t * 0.6 + a[3] / 420 + k) * 2, 0, 1)
      L[i] = l; C[i] = math.min(1, l) * af
    end
  end
  -- 2. halo large et doux : un ruban par veine (sauté en qualité 0)
  if q > 0 then
    render.SetMaterial(HALO)
    for k = 1, #LVEINES do
      local v, gk = LVEINES[k], g[k]
      local w1 = gk.wp[1]
      local dx, dy = w1.x - ex, w1.y - ey
      if dx * dx + dy * dy < dmax2 * 1.5 then
        render.StartBeam(#v)
        for i = 1, #v do
          col.r, col.g, col.b, col.a = 200, 22, 24, 75 * gk.c[i]
          render.AddBeam(gk.wp[i], 9 + 5 * v[i][4], i * 0.2, col)
        end
        render.EndBeam()
      end
    end
  end
  -- 3. bords et cœurs : segments allumés, visibles et assez proches
  local lit, n = Q.lit, 0
  for k = 1, #LVEINES do
    local gk = g[k]
    local seg, C = gk.seg, gk.c
    for i = 1, #seg do
      if C[i] > 0.03 then
        local s = seg[i]
        local dx, dy, dz = s.mx - ex, s.my - ey, s.mz - ez
        local d2 = dx * dx + dy * dy + dz * dz
        if d2 < dmax2 and (d2 < 90000 or dx * fx + dy * fy + dz * fz > 0) then n = n + 1; lit[n] = k * 100000 + i end
      end
    end
  end
  render.SetColorMaterial()
  Q.debut(2 * n)
  for j = 1, n do
    local k = math.floor(lit[j] / 100000); local i = lit[j] - k * 100000
    local gk = g[k]
    local l, c = gk.l[i], gk.c[i]
    local chaud = math.max(0, l - 1)
    local s = gk.seg[i]
    Q.quad(s.bord, 150, 14 + 40 * chaud, 16, 150 * c)                                   -- bord sombre, étroit
    Q.quad(s.coeur, 255, 95 + 110 * chaud, 45 + 80 * chaud, 210 * c * c)                -- le cœur : un fil fin et chaud
  end
  Q.fin()
  if R then                                                  -- la tête de braise, là où le liseré croise la veine
    render.SetMaterial(HALO)
    for k, v in ipairs(LVEINES) do
      for i = 1, #v - 1 do
        local a, b = v[i], v[i + 1]
        if a[5] <= R and R < b[5] then
          local p = g[k].wp[i]
          render.DrawSprite(p, 40 + 6 * a[4], 40 + 6 * a[4], Color(255, 140, 55, 210))
          render.DrawSprite(p, 10, 10, Color(255, 235, 200, 255))
        end
      end
    end
  end
end

-- ---------- reflets en larges bandes (feu de la tornade, chemin de l'éclipse) ----------
local function sur_eau(src)
  local o = EyePos(); local m = Vector(src.x, src.y, 2 * (MZ + off.z) - src.z)
  local d = m - o
  if d.z >= -0.01 then return end
  local u = (MZ + off.z + 1.5 - o.z) / d.z
  if u <= 0 then return end
  return o + d * u
end
local function bandes(src, R, G, B, al, large, long, t)    -- 3 bandes larges, cassées par la houle, floues au loin
  if EyePos().z - off.z > 260 then return end                -- vu de haut, la traînée se dresse en éclats verticaux : seulement au ras de l'eau
  local p = sur_eau(src)
  if not p then return end
  local vers = EyePos() - p; vers.z = 0; local dist = vers:Length(); vers:Normalize()
  if dist < 500 then return end
  local L = math.min(long, dist - 450)
  local cote = Vector(-vers.y, vers.x, 0)
  render.SetMaterial(HALO)
  for j = -1, 1 do
    render.StartBeam(12)
    for k = 0, 11 do
      local u = k / 11
      local flou = 1 + u * 0.8
      local q = p + vers * (u * L) + cote * (j * large * 0.32 * flou + math.sin(t * 0.8 + u * 6 + j) * large * 0.1) + Vector(0, 0, 0.3)
      local f = (0.55 + 0.45 * math.sin(t * 1.1 + u * 9 + j * 2.1)) * (1 - u * 0.7) * (j == 0 and 1 or 0.6)
      render.AddBeam(q, large * 0.4 * flou, u * 2 - t * 0.15, Color(R, G, B, al * f))
    end
    render.EndBeam()
  end
  return p, vers, L
end
local paillettes, prochainePaillette = {}, 0
local function lac_reflets(t)
  local p, vers, L = bandes(W(ECLIPSE.x, ECLIPSE.y, ECLIPSE.z), 160, 178, 215, fige() and 50 or 30, 520, 4200, t)
  if p and not fige() and t > prochainePaillette then     -- chemin de lumière : scintillement continu
    prochainePaillette = t + 0.02
    for _ = 1, 3 do
      local u = math.Rand(0, 1) ^ 0.7
      paillettes[#paillettes + 1] = { p = p + vers * (u * L) + Vector(-vers.y, vers.x, 0) * math.Rand(-150, 150) * (1 + u) + Vector(0, 0, 0.8), t = t }
    end
  end
  render.SetMaterial(HALO)
  for i = #paillettes, 1, -1 do
    local q = paillettes[i]; local a = (t - q.t) / 0.5
    if a >= 1 then table.remove(paillettes, i) else
      local f = math.sin(a * math.pi); render.DrawSprite(q.p, 12 * f, 4 * f, Color(215, 228, 255, 150 * f)) end
  end
  local s, force = tor_niveau()                            -- le feu de la tornade : il tremble avec les vagues
  if s > 0.02 then
    local f = s * math.min(1.3, force)
    bandes(W(EPEE.x, EPEE.y, ZI + 380 * s), 255, 50, 30, 100 * f * (0.8 + 0.2 * math.sin(t * 5)), 380, 2600, t)
    bandes(W(EPEE.x, EPEE.y, ZI + 120 * s), 255, 130, 50, 70 * f * (0.75 + 0.25 * math.sin(t * 7)), 180, 1500, t + 1.7)
  end
end

-- ---------- rive vivante : écume sombre, hauts-fonds plus clairs ----------
local function rive(t)
  local N = #CONTOUR
  render.SetColorMaterial()
  if not Q.rive or Q.rive_cle ~= off then                  -- optimisation : hauts-fonds calculés une fois par collage
    Q.rive = {}
    for i = 1, N do
      local a, b = CONTOUR[i], CONTOUR[i % N + 1]
      Q.rive[i] = { W(a[1], a[2], MZ + 1.2), W(b[1], b[2], MZ + 1.2), W(b[1] * 1.2, b[2] * 1.2, MZ + 1.2), W(a[1] * 1.2, a[2] * 1.2, MZ + 1.2) }
    end
    Q.rive_cle = Vector(off.x, off.y, off.z)
  end
  Q.debut(N)                                               -- hauts-fonds : anneau d'eau un peu plus claire, un seul maillage
  for i = 1, N do Q.quad(Q.rive[i], 28, 42, 52, 55) end
  Q.fin()
  local v, col, ox, oy, z = Q.v, Q.coul, off.x, off.y, off.z + MZ + 1.5
  render.SetMaterial(HALO)                                 -- l'écume : un liseré qui respire
  render.StartBeam(N + 1)
  for i = 0, N do
    local a = CONTOUR[i % N + 1]; local k = 1.03 + 0.015 * math.sin(t * 1.4 + i * 0.7)
    v:SetUnpacked(a[1] * k + ox, a[2] * k + oy, z); col.r, col.g, col.b, col.a = 125, 135, 150, 70 + 30 * math.sin(t * 2 + i)
    render.AddBeam(v, 22, i * 0.3 - t * 0.2, col)
  end
  render.EndBeam()
  local f = math.max(coeur_force() * (0.55 + 0.45 * math.min(1, coeur())), phase == "calme" and 0.18 or 0)
  if f > 0.02 then                                         -- passe 4 : liseré carmin où l'île touche l'eau (il bat avec le trône)
    render.StartBeam(N + 1)
    col.r, col.g, col.b, col.a = 220, 24, 32, 150 * f
    for i = 0, N do
      local a = CONTOUR[i % N + 1]
      v:SetUnpacked(a[1] * 1.005 + ox, a[2] * 1.005 + oy, z + 0.2)
      render.AddBeam(v, 12, i * 0.3, col)
    end
    render.EndBeam()
  end
end
local function coeur_onde()                                -- l'onde douce du battement, sur l'eau
  local f = coeur_force()
  if f < 0.02 then return end
  local R, fade = coeur_rayon()
  if R > 60 then lac_anneau(W(EPEE.x, EPEE.y, MZ + 1.5), R, 70, Color(150, 18, 24, 45 * f * fade), 2.1, 90) end
end

-- ---------- rides, brume du lac, brume de bord, braises qui sifflent ----------
local rides, prochaineRide = {}, 0
local function rides_dessin(t)
  render.SetColorMaterial()
  for i = #rides, 1, -1 do
    local o = rides[i]; local a = (t - o.t0) / o.vie
    if a >= 1 then table.remove(rides, i) else
      local r = o.r0 + o.v * (t - o.t0)
      lac_cercle(o.c, r, o.l, Color(120, 135, 165, o.al * math.sin(a * math.pi)), 32)
    end
  end
end
local function ride(p, r0, v, vie, al, l) rides[#rides + 1] = { c = p, t0 = CurTime(), vie = vie, v = v, r0 = r0, al = al, l = l } end
local plouf_t = 0
lac_plouf = function(p)                                      -- une braise tombe dans le lac
  ride(Vector(p.x, p.y, MZ + off.z + 1.3), 2, 26, 1.6, 120, 1.2)
  if CurTime() > plouf_t then
    plouf_t = CurTime() + 0.25
    sound.Play("ambient/levels/canals/toxic_slime_sizzle" .. math.random(1, 4) .. ".wav", p, 65, math.random(120, 150), 0.45)
  end
end
local lbrumes, prochaineLBrume = {}, 0
local function lac_brume(n, bord)
  if #FUMEE == 0 then return end
  local o = EyePos() - off
  for _ = 1, n do
    local x, y
    if bord then                                           -- brume de bord : le lac ne s'arrête pas net
      local c = math.random(4); local u = math.Rand(0, 1)
      if c == 1 then x, y = Lerp(u, LAC_X0, LAC_X1), LAC_Y0 elseif c == 2 then x, y = Lerp(u, LAC_X0, LAC_X1), LAC_Y1
      elseif c == 3 then x, y = LAC_X0, Lerp(u, LAC_Y0, LAC_Y1) else x, y = LAC_X1, Lerp(u, LAC_Y0, LAC_Y1) end
      if (Vector(x, y, 0) - Vector(o.x, o.y, 0)):Length() > 5000 then x = nil end
    else
      local a, r = math.Rand(0, 6.283), math.Rand(250, 3400)
      x, y = o.x + math.cos(a) * r, o.y + math.sin(a) * r
      if not dans_lac(x, y, 80) or (math.abs(x) < 700 and math.abs(y) < 560) then x = nil end
    end
    if x then
      local p = emetteur():Add(FUMEE[math.random(#FUMEE)], W(x, y, MZ + (bord and math.Rand(10, 60) or math.Rand(3, 12))))
      if p then
        p:SetVelocity(Vector(math.Rand(-8, 8), math.Rand(-8, 8), 0)); p:SetDieTime(math.Rand(9, 13))
        p:SetStartAlpha(0); p:SetEndAlpha(0)
        local g = bord and 1.8 or 1
        p:SetStartSize(math.Rand(240, 340) * g); p:SetEndSize(math.Rand(380, 520) * g)
        -- passe 4 : brume teintée, rouge près de l'île et de la tornade, froide et bleutée au large
        local s = tor_niveau()
        local rouge = math.Clamp(1 - (math.sqrt(x * x + y * y) - 700) / 1900, 0, 1) * (0.35 + 0.65 * s)
        p:SetRoll(math.Rand(0, 360)); p:SetRollDelta(math.Rand(-0.03, 0.03))
        p:SetColor(Lerp(rouge, 112, 165), Lerp(rouge, 126, 82), Lerp(rouge, 168, 86))
        local A = bord and 55 or 28
        p:SetNextThink(CurTime()); p:SetThinkFunction(function(pa)
          local u = pa:GetLifeTime() / pa:GetDieTime(); pa:SetStartAlpha(A * math.sin(u * math.pi)); pa:SetNextThink(CurTime() + 0.1) end)
        lbrumes[#lbrumes + 1] = p; brumes[#brumes + 1] = p    -- la brume du lac est chassée et figée avec celle de l'île
      end
    end
  end
end
local vapeur_t, clapotis = 0, nil
local function vapeur(now)                                 -- passe 4 : filets de vapeur qui montent des veines brûlantes
  if #FUMEE == 0 or now < vapeur_t then return end
  local fort = (phase == "eveil" and instant > 1.2) and 1 or phase == "plein" and 0.8 or 0
  if fort == 0 then return end
  vapeur_t = now + 0.05 / fort
  local o = EyePos() - off
  for _ = 1, 3 do
    local v = LVEINES[math.random(#LVEINES)]; local a = v[math.random(#v)]
    local l = lac_lumiere(a, now)
    if l > 0.6 and (Vector(a[1], a[2], 0) - Vector(o.x, o.y, 0)):Length() < 3200 then
      local p = emetteur():Add(FUMEE[math.random(#FUMEE)], W(a[1] + math.Rand(-6, 6), a[2] + math.Rand(-6, 6), MZ + 2))
      if p then
        p:SetVelocity(Vector(math.Rand(-6, 6), math.Rand(-6, 6), math.Rand(28, 60))); p:SetGravity(Vector(0, 0, 8))
        p:SetDieTime(math.Rand(2.8, 4.5)); p:SetStartAlpha(0); p:SetEndAlpha(0)
        p:SetStartSize(math.Rand(10, 18)); p:SetEndSize(math.Rand(70, 120))
        p:SetRoll(math.Rand(0, 360)); p:SetRollDelta(math.Rand(-0.4, 0.4)); p:SetColor(150, 112, 112)
        local A = 34 * math.min(1, l)
        p:SetNextThink(CurTime()); p:SetThinkFunction(function(pa)
          local u = pa:GetLifeTime() / pa:GetDieTime(); pa:SetStartAlpha(A * math.sin(u * math.pi) ^ 0.7); pa:SetNextThink(CurTime() + 0.08) end)
        brumes[#brumes + 1] = p
      end
    end
  end
end
local function lac_vie(now, dt)
  if not clapotis then clapotis = CreateSound(LocalPlayer(), "ambient/ambience/waterlap_loop.wav") end
  if clapotis and not clapotis:IsPlaying() then clapotis:PlayEx(0.45, 100) end      -- le stopsound du siège le coupe : il repart
  vapeur(now)
  if not fige() then
    if now > prochaineLBrume then prochaineLBrume = now + 0.04; lac_brume(1, false); if math.random() < 0.4 then lac_brume(1, true) end end
    if now > prochaineRide then
      prochaineRide = now + math.Rand(0.15, 0.35)
      local o = EyePos() - off; local a, r = math.Rand(0, 6.283), math.Rand(100, 2400)
      local x, y = o.x + math.cos(a) * r, o.y + math.sin(a) * r
      if dans_lac(x, y, 50) then ride(W(x, y, MZ + 1.4), 8, math.Rand(18, 32), math.Rand(4, 6.5), 34, 1.0) end
    end
  end
  if #brumes > 700 then for i = #brumes, 1, -1 do local p = brumes[i]; if not p or p:GetLifeTime() >= p:GetDieTime() then table.remove(brumes, i) end end end
  fps_n = fps_n + 1; fps_s = fps_s + dt
end
-- ---------- la nappe de brume (passe 4, Adrien 3 h 09 : « parfois il y en a et parfois non ») ----------
-- Avant : des particules semées autour de l'œil, mortes en 9 à 13 s, très pâles (alpha 28) : la nappe suivait la caméra et
-- disparaissait à chaque changement de plan. Maintenant : une nappe fixe sur tout le lac, dessinée en script (quads horizontaux
-- à 3 hauteurs, sans écriture en profondeur), toujours là. L'onde de choc y ouvre un trou quelques secondes, puis la nappe
-- revient en roulant vers l'île ; au siège vide elle se fige.
local NAPPE, nappe_t, nappe_der = {}, 0, nil
do
  local pas = 430
  for x = LAC_X0 + pas / 2, LAC_X1 - pas / 2, pas do
    for y = LAC_Y0 + pas / 2, LAC_Y1 - pas / 2, pas do
      for c = 1, 3 do
        local px, py = x + math.Rand(-pas, pas) * 0.45, y + math.Rand(-pas, pas) * 0.45
        if not (math.abs(px) < 560 and math.abs(py) < 450) then
          NAPPE[#NAPPE + 1] = { x = px, y = py, z = ({ 6, 16, 30 })[c], s = math.Rand(820, 1150), r = math.Rand(0, 360),
            dr = math.Rand(-1.5, 1.5), m = math.random(#FUMEE > 0 and #FUMEE or 1), ph = math.Rand(0, 6.28), a = ({ 72, 56, 38 })[c] }
        end
      end
    end
  end
end
local NAPPE_MAT = {}
for i, n in ipairs(FUMEE) do NAPPE_MAT[i] = Material(n) end
local function nappe_trou()                                  -- rayon dégagé par l'onde de choc, puis la nappe revient
  if phase == "calme" or (phase == "eveil" and instant < CHOC[1].t) then return 0 end   -- v73 : chassée, elle ne revient pas
  local s = phase == "eveil" and instant - CHOC[1].t or 3
  return CHOC_R0 + CHOC_V * math.min(s, 3)                   -- revient en roulant vers l'île (environ 4 s)
end
local function nappe_dessin(t)
  if #NAPPE_MAT == 0 then return end
  if not fige() then nappe_t = nappe_t + (nappe_der and math.min(0.1, t - nappe_der) or 0) end
  nappe_der = t
  local e = EyePos(); local ox, oy, oz = e.x - off.x, e.y - off.y, e.z - off.z   -- optimisation : aucun Vector ni Color par nappe
  local H = nappe_trou()
  local feu = tor_niveau()
  local h = oz - MZ
  local kh = math.Clamp(1.6 - h / 700, 0.55, 1.6)             -- passe 5 : nappe plus dense au ras de l'eau
  local kb = math.Clamp(1.3 - h / 1400, 0.45, 1)              -- bancs debout : visibles partout, pleins au ras de l'eau
  render.OverrideDepthEnable(true, false)
  for _, n in ipairs(NAPPE) do
    local x = n.x + math.sin(nappe_t * 0.05 + n.ph) * 120 + nappe_t * 6
    local y = n.y + math.cos(nappe_t * 0.04 + n.ph) * 90
    if H > 0 then                                    -- v73 : repoussée par l'onde, entassée en anneau sur les côtés
      local ex, ey = x - EPEE.x, y - EPEE.y; local de = math.sqrt(ex * ex + ey * ey) + 0.01
      if de < H + 500 then local nd = H + 500 * de / (H + 500); x, y = EPEE.x + ex / de * nd, EPEE.y + ey / de * nd end
    end
    local dx, dy = x - ox, y - oy
    local d2 = dx * dx + dy * dy
    if d2 < 42250000 and dans_lac(x, y) then
      local ex, ey = x - EPEE.x, y - EPEE.y
      local de = math.sqrt(ex * ex + ey * ey)
      local k = H > 0 and math.Clamp((de - H) / 350, 0, 1) or 1
      if k > 0.02 then
        local rouge = math.Clamp(1 - (de - 600) / 1900, 0, 1) * (0.3 + 0.7 * feu)
        local a = n.a * k * (0.75 + 0.25 * math.sin(nappe_t * 0.3 + n.ph))
        render.SetMaterial(NAPPE_MAT[n.m])
        local v, c = Q.v, Q.c3
        v:SetUnpacked(x + off.x, y + off.y, MZ + n.z + off.z)
        c.r, c.g, c.b, c.a = 64 + 56 * rouge, 70 - 24 * rouge, 86 - 36 * rouge, a * kh
        render.DrawQuadEasy(v, Q.haut, n.s, n.s, c, n.r + nappe_t * n.dr)
        if n.z == 16 and d2 > 144400 then                    -- passe 5 : banc debout (sprite), plus dense au large
          local large = math.Clamp((de - 500) / 2500, 0.35, 1)
          v:SetUnpacked(x + off.x, y + off.y, MZ + 70 + n.s * 0.12 + off.z)
          c.r, c.g, c.b, c.a = 92 + 48 * rouge, 100 - 40 * rouge, 118 - 56 * rouge, 120 * k * large * kb
          render.DrawSprite(v, n.s * 1.25, n.s * 0.55, c)
        end
      end
    end
  end
  for i = 1, #SC.BORD do                          -- v71 : bancs debout au bord de la boîte (cachent la coupure du carré)
    local b, v, c = SC.BORD[i], Q.v, Q.c3
    v:SetUnpacked(b[1] + math.sin(nappe_t * 0.05 + i) * 60 + off.x, b[2] + math.cos(nappe_t * 0.04 + i) * 60 + off.y, MZ + 200 + off.z)
    c.r, c.g, c.b, c.a = 70, 76, 92, 125
    render.DrawSprite(v, 1500, 720, c)
  end
  render.OverrideDepthEnable(false, false)
end
hook.Add("PostDrawTranslucentRenderables", "lac_eau_nappe", function(prof, ciel)
  if prof or ciel or not t0 or not off then return end
  if CATH then CATH.translucide() end                -- la cathédrale (loin) avant la nappe du lac (près)
  nappe_dessin(CurTime())
end)
local function lac_dessin(t) rides_dessin(t); rive(t); coeur_onde(); lac_reflets(t); lac_veines(t) end
local function lac_bilan()
  if fps_n > 30 then print(string.format("[lac_eau_demo] boucle : %.0f images/s en moyenne, miroir %.2f ms par image", fps_n / math.max(0.001, fps_s), miroir_ms)) end
  fps_n, fps_s = 0, 0
end
local function matiere(n)
  refraction = math.Clamp(n, 1, 3)
  for _, e in ipairs(ents.FindByModel("models/hunter/plates/plate32x32.mdl")) do
    if e:GetMaterial():find("shadertest") then e:SetMaterial(REFRACTIONS[refraction]) end
  end
  print("[lac_eau_demo] réfraction : " .. REFRACTIONS[refraction])
end
concommand.Add("lac_eau_matiere", function(_, _, args) matiere(tonumber(args[1] or "1") or 1) end)   -- lac_eau_matiere 1, 2 ou 3
