  rive_sud = { { 150, LAC_Y0 + 160, MZ + 64 }, { 0, 0, ZI + 150 } },        -- depuis la rive sud, vers l'île
}
local PHOTOS = { { 3.5, "calme" }, { 5.5, "plongee_so", nil, "plongee_so" },
  { 9.6, "onde" }, { 10.8, "joueur_ile_onde", nil, "joueur_ile" }, { 11.0, "rive_sud_onde", nil, "rive_sud" },
  { 11.5, "veines" }, { 16.5, "veine_large" }, { 24, "plein_feu" }, { 24.6, "joueur_ile_plein", nil, "joueur_ile" },
  { 24.8, "rive_sud_plein", nil, "rive_sud" }, { 31, "extinction" }, { 36.1, "rive_sud_coeur", nil, "rive_sud" }, { 37, "siege_vide" },
  { 6.5, "cath_brume" }, { 9.5, "cath_boum" }, { 26.5, "cath_tornade" }, { 38.2, "cath_contrechamp" },
