local photos_faites = {}
local photo_rt
local function photos(hors)
  if not t0 or not off then return end
  local TR = CurTime() - t0
  local T = SC.TL(TR)
  if TR < 1 then photos_faites = {} end
  for i, ph in ipairs(PHOTOS) do
    local avant = ph[3] and ph[2] and 0.35 or 0                 -- la matière change un peu avant la photo
    local TT = ph.brut and TR or T
    if not photos_faites[i] and TT >= ph[1] - avant and TT < ph[1] + 0.5 and (ph.brut or TR < 8 or TR >= 8 + SC.DECALE) then
      if ph[3] and not photos_faites[-i] then photos_faites[-i] = true; matiere(ph[3]) end
      if TT >= ph[1] then
        photos_faites[i] = true
        if ph[2] then
          local v = ph[4] and VUES[ph[4]]
          if hors then
            photo_rt = photo_rt or GetRenderTargetEx("lac_photo_rt", ScrW(), ScrH(), RT_SIZE_LITERAL, MATERIAL_RT_DEPTH_SEPARATE, 0, 0, IMAGE_FORMAT_RGB888)
            render.PushRenderTarget(photo_rt)
          end
          if v then
            local o, c = W(v[1][1], v[1][2], v[1][3]), W(v[2][1], v[2][2], v[2][3])
            render.RenderView({ origin = o, angles = (c - o):Angle(), fov = 75, x = 0, y = 0, w = ScrW(), h = ScrH(),
              drawviewmodel = false, drawhud = false, dopostprocess = true })
          elseif hors then
            local cp, ca, cf = SC.camera(TR)
            render.RenderView({ origin = cp or EyePos(), angles = ca or EyeAngles(), fov = cf or 75, x = 0, y = 0, w = ScrW(), h = ScrH(),
              drawviewmodel = false, drawhud = false, dopostprocess = true })
          end
          if hors then cam.Start2D(); hook.Run("RenderScreenspaceEffects"); cam.End2D() end
          local d = render.Capture({ format = "jpeg", quality = 85, x = 0, y = 0, w = ScrW(), h = ScrH() })
          if hors then render.PopRenderTarget() end
          print("[lac_photo] " .. ph[2] .. (d and (" " .. #d .. " octets") or " : capture vide"))
          if d then file.CreateDir("lac_eau"); file.Write("lac_eau/" .. string.format("%02d", i) .. "_" .. ph[2] .. ".jpg", d) end
        end
      end
    end
  end
end
