SC.boucles = {}                                   -- v78 : sons en boucle en cours
function SC.onde(p, T)                            -- v81 : 0 avant le passage de l'onde du boum, 1 après ; instant du passage
  if not SC.EW or not T then return 0, 1e9 end
  local dx, dy = p.x - SC.EW.x, p.y - SC.EW.y
  local ta = 9 + math.max(0, math.sqrt(dx * dx + dy * dy) - 230) / 900
  return math.Clamp((T - ta) / 0.5, 0, 1), ta
end
function SC.couper() for _, p in ipairs(SC.boucles) do p:Stop() end; SC.boucles = {} end
-- ---------- boucle ----------
local function demarrer(depart)
  reperer()
  if not off then print("[lac_eau_demo] l'île n'est pas collée") return end
  t0 = depart or CurTime(); SC.Hacc, SC.H = 0, 0; joues = {}; anneaux = {}; braises = {}; brumes = {}; lant_avant = {}; tor_arreter()
  SC.couper(); RunConsoleCommand("stopsound")
  local TR0 = math.min(CurTime() - t0, SC.fin or BOUCLE)   -- reprise en cours de route : les sons passés ne se rejouent pas
  if TR0 > 1 then for i, s in ipairs(SONS) do
    if (s.brut and TR0 or SC.TL(TR0)) > s.t + 0.5 and not string.find(s.s, "loop", 1, true) then joues[i] = true end
  end end
  brume(120)
  lac_bilan(); miroir_creer(); for _ = 1, 220 do lac_brume(1, false) end
  print("[lac_eau_demo] scène lancée ; lac_eau_stop pour la couper chez soi")
end
local function arreter()
  t0 = nil; SC.couper(); RunConsoleCommand("stopsound"); tor_arreter(); for i = 1, #rides do rides[i] = nil end
  print("[lac_eau_demo] arrêtée")
end
concommand.Add("lac_eau_demo", function() SC.manuel = false; demarrer() end)
concommand.Add("lac_eau_stop", function() SC.manuel = true; arreter() end)

local dernier, ancienne, figee, lac_eau_lance, chasse = CurTime(), nil, false, false, false
-- séquences du scénario (temps brut de début) : chacune joue jusqu'au début de la suivante puis tient son image
SC.SEQ = { { 0, "Le lac dort" }, { 2.9, "Cloche 1" }, { 6.4, "Cloche 2" }, { 9.9, "Cloche 3" },
  { 13.4, "Cloche 4, éclipse totale" }, { 15.5, "Le boum, l'éveil" }, { 27.5, "Plein feu" },
  { 35.5, "Le siège, l'extinction" }, { 44.0, "La flamme bleue" } }
-- (dans SC, pas en locales : le fichier est à la limite de 200 locales de Lua 5.1)
function SC.en_cours() return SC.k ~= nil end
function SC.t0() return SC.s - SC.SEQ[SC.k][1] end
net.Receive("lac_noir_seq", function()
  local k, s = net.ReadUInt(8), net.ReadDouble()
  SC.OS = net.ReadBool() and net.ReadVector() or nil      -- v87 : repère du build trouvé par le serveur
  if SC.OS then print("[lac_repere] repère reçu du serveur : " .. tostring(SC.OS)) end
  if k == 0 or not SC.SEQ[k] then SC.k, SC.s, SC.fin = nil, nil, nil; if t0 then arreter() end return end   -- arrêt pour tous
  local suivant = t0 ~= nil and SC.k == k - 1     -- v73 : seule la séquence suivante enchaîne ; un retour ou un saut repart propre (sons compris)
  SC.k, SC.s, SC.manuel = k, s, false
  SC.fin = SC.SEQ[k + 1] and SC.SEQ[k + 1][1] or BOUCLE - 0.05
  print("[lac_eau_demo] séquence " .. k .. " : " .. SC.SEQ[k][2])
  reperer()
  if suivant then SC.Hacc = SC.H or 0; t0 = SC.t0()                        -- déjà en route : on enchaîne sans rien remettre à zéro
  elseif off and SC.dans() then demarrer(SC.t0()) end
end)
hook.Add("Think", "lac_eau_demo", function()
  local now = CurTime(); local dt = math.min(0.1, now - dernier); dernier = now
  if now > prochain then prochain = now + 1; reperer() end
  if CATH and not (t0 and off) then CATH.T, CATH.TR = nil, nil end
  if not (t0 and off) then for _, m in pairs(PIECES) do m.T, m.TR = nil, nil end end
  if off and t0 and not SC.dans() then arreter() end      -- joueur sorti de la boîte : rien ne se voit ni ne s'entend
  if off and not t0 and SC.en_cours() and not SC.manuel and SC.dans() then demarrer(SC.t0()) end
  SC.actif = (t0 and off and SC.dans()) and true or false   -- v76 : la scène est vue par ce joueur
  if CATH then CATH.actif = SC.actif end
  if not t0 or not off then return end
  local T = math.min(now - t0, SC.fin or BOUCLE - 0.05)   -- la séquence tient sa dernière image
  SC.H = (SC.Hacc or 0) + math.max(0, now - t0 - T)        -- temps tenu cumulé : l'horloge des animations
  local TR = T; T = SC.TL(T)                          -- scène complète : TR temps brut (cloches), T temps du lac
  if CATH then CATH.T, CATH.TR = T, TR end
  SC.EW = SC.EW or Vector(); SC.EW:SetUnpacked(EPEE.x + off.x, EPEE.y + off.y, ZI + off.z)   -- v81 : centre de l'onde
  for _, m in pairs(PIECES) do m.T, m.TR, m.H = T, TR, SC.H end
  if T < 8 then phase, instant = "calme", T elseif T < 20 then phase, instant = "eveil", T - 8
  elseif T < 28 then phase, instant = "plein", T - 20 else phase, instant = "siege", T - 28 end
  if phase ~= ancienne then
    if phase == "eveil" then secousse() end         -- la secousse de caméra est dans camera() (Q.tremble)
    if phase == "siege" then for _, p in ipairs(SC.boucles) do p:FadeOut(3) end; SC.boucles = {} end   -- v78 : fondu
    ancienne = phase
  end
  Q.secousse_pas(now)
  for i, s in ipairs(SONS) do
    if not joues[i] and (s.brut and TR or T) >= s.t and (s.brut or TR < 8 or TR >= 8 + SC.DECALE) then joues[i] = true
      if s.onde then ride(W(0, 4450, MZ + 1.4), 60, 200 + 60 * s.onde, 5.5, 40 + 16 * s.onde, 1.4 + 0.4 * s.onde) end   -- onde légère partie du pied de la cathédrale
      if SC.dans() then
        if s.boucle then                            -- v78 : boucle gardée pour l'éteindre en fondu
          local p = CreateSound(LocalPlayer(), s.s); p:PlayEx(s.v, s.p or 100); SC.boucles[#SC.boucles + 1] = p
        else LocalPlayer():EmitSound(s.s, 75, s.p or 100, s.v) end
      end end
  end
  if fige() then
    if not figee then figee = true; figer_brume() end
  else
    figee = false
    if math.random() < dt * 16 then brume(1) end
  end
  if phase ~= "siege" and now > prochaineOnde then
    prochaineOnde = now + math.Rand(0.12, 0.3)
    local c = CONTOUR[math.random(#CONTOUR)]
    local d = Vector(c[1] - EPEE.x, c[2], 0); d:Normalize()
    anneaux[#anneaux + 1] = { c = W(c[1], c[2], EAU + 1.3) + d * math.Rand(10, 70), t0 = now, vie = math.Rand(1.8, 2.8), r = math.Rand(50, 110) }
  end
  local ts, tf = tor_niveau()
  if ts > 0.01 then tor_emettre(W(EPEE.x, EPEE.y, ZI), ts, tf, now) elseif tor_der then tor_arreter() end
  gerbes(emetteur_feu(), now)
  lac_vie(now, dt)
  lanternes_vie(now, emetteur_feu())
  if phase == "eveil" and instant >= 1 and not chasse then chasse = true; chasser_brume() end
  if phase ~= "eveil" then chasse = false end
  if (phase == "eveil" and instant > 1.5 or phase == "plein") and now > prochaineBraise then prochaineBraise = now + 0.035; braise_neuve() end
  for i = #braises, 1, -1 do
    local b = braises[i]
    if b.sol then
      if now - b.sol > 2.4 then table.remove(braises, i) end
    else
      b.p = b.p + b.v * dt
      if b.p.z <= ZI + off.z + 0.8 and sur_ile(b.p) then b.p.z = ZI + off.z + 0.8; b.sol = now
      elseif b.p.z < EAU + off.z then lac_plouf(b.p); table.remove(braises, i) end
    end
  end
  local c = niveau_froid()
  if c > 0.05 and math.random() < dt * 8 then poussiere_rai(c) end
  -- lumières : lune froide sur l'île, rouge le long des veines, fente du trône, rai froid
  local ox, oy, oz = off.x, off.y, off.z
  if (Q.qualite and Q.qualite:GetInt() or 1) >= 1 then
    Q.lum(7800, 4, -300 + ox, -100 + oy, ZI + 700 + oz, 120, 140, 190, 0.7, 1400); Q.lum(7801, 4, 300 + ox, 250 + oy, ZI + 700 + oz, 120, 140, 190, 0.7, 1400)
  else                                            -- qualité 0 : les deux lunes fondues en une seule, plus large
    Q.lum(7800, 4, ox, 75 + oy, ZI + 760 + oz, 120, 140, 190, 0.95, 1700)
  end
  for k, iv in ipairs(Q.VL) do
    local v = VEINES[iv]
    if v then
      local p = v[math.floor(#v / 2) + 1]; local l = math.min(1.2, lumiere(p[3]))
      if l > 0.05 then Q.lum(7810 + k, 1, p[1] + ox, p[2] + oy, ZI + 14 + oz, 255, 35, 30, 1.6 * l, 260) end
    end
  end
  local lr = math.min(1.3, lumiere(30))           -- v74 : le reflet rouge de la lave au pied de l'épée
  if lr > 0.05 then Q.lum(7835, 4, EPEE.x + ox, EPEE.y - 110 + oy, ZI + 70 + oz, 255, 38, 24, 2.4 * lr, 1100) end
  if fente then
    local f = niveau_fente()
    if f > 0.05 then Q.lum(7820, 3, fente.x, fente.y - 6, (fente.z0 + fente.z1) / 2, 255, 30, 40, 3 * f, 140) end
    if c > 0.05 then Q.lum(7821, 3, fente.x, fente.y - 70, fente.z0 + 120, 150, 195, 255, 2.4 * c, 300) end
  end
  Q.lum_emettre(now)
end)

SC.PLANS = {   -- temps brut : les cloches, entre le calme (8 s) et le boum ; plans longs, l'attente
  { 8, 11.8, { 700, -2200, 30 }, { 560, -1900, 36 }, { 0, 4800, 600 }, 30 },             -- au ras de l'eau, longue focale : la cathédrale dans la brume
  { 11.8, 8 + SC.DECALE, { 1100, -700, 55 }, { 1000, -560, 62 }, { 0, 4800, 620 }, 30 },   -- v6 : de biais au ras de l'eau (le dossier du trône bouchait l'axe) : l'île de profil, la cathédrale derrière, le dernier coup, le temps mort
}
function SC.camera(TR)
  if TR >= 8 and TR < 8 + SC.DECALE then
    for _, p in ipairs(SC.PLANS) do
      if TR >= p[1] and TR < p[2] then
        local u = lisse((TR - p[1]) / (p[2] - p[1]))
        local a, b, c = p[3], p[4], p[5]
        local pos = W(Lerp(u, a[1], b[1]), Lerp(u, a[2], b[2]), Lerp(u, a[3], b[3]))
        return pos, (W(c[1], c[2], c[3]) - pos):Angle(), p[6]
      end
    end
  end
  return camera(SC.TL(TR))
end
