-- v71 : brouillard du monde pendant la scène (joueur dans la boîte) : le loin se fond, on ne voit plus le bord du carré
local function lac_brouillard(k)
  if not (t0 and off and SC.dans()) then return end
  render.FogMode(MATERIAL_FOG_LINEAR); render.FogStart(2200 * k); render.FogEnd(8500 * k)
  render.FogMaxDensity(0.88); render.FogColor(18, 20, 28)
  return true
end
