hook.Add("PostDrawOpaqueRenderables", "lac_noir_rideau", function(prof, ciel)
  if ciel or not (t0 and off and SC.dans()) then return end
  local x0, x1, y0, y1 = SC.X0 + off.x - 10, SC.X1 + off.x + 10, SC.Y0 + off.y - 10, SC.Y1 + off.y + 10
  local z0, z1 = SC.Z0 + off.z - 40, SC.Z1 + off.z + 20000
  render.SetStencilEnable(true); render.ClearStencil()   -- v76 : les pixels du rideau, pour y redessiner la couche C
  render.SetStencilWriteMask(255); render.SetStencilTestMask(255); render.SetStencilReferenceValue(1)
  render.SetStencilCompareFunction(STENCIL_ALWAYS); render.SetStencilPassOperation(STENCIL_REPLACE)
  render.SetStencilFailOperation(STENCIL_KEEP); render.SetStencilZFailOperation(STENCIL_KEEP)
  render.SetColorMaterial(); render.CullMode(MATERIAL_CULLMODE_NONE)
  render.OverrideDepthEnable(true, false)          -- sans écrire la profondeur : l'éclipse et la brume passent devant
  local c = SC.RIDEAU
  render.DrawQuad(Vector(x0, y0, z0), Vector(x1, y0, z0), Vector(x1, y0, z1), Vector(x0, y0, z1), c)
  render.DrawQuad(Vector(x0, y1, z0), Vector(x1, y1, z0), Vector(x1, y1, z1), Vector(x0, y1, z1), c)
  render.DrawQuad(Vector(x0, y0, z0), Vector(x0, y1, z0), Vector(x0, y1, z1), Vector(x0, y0, z1), c)
  render.DrawQuad(Vector(x1, y0, z0), Vector(x1, y1, z0), Vector(x1, y1, z1), Vector(x1, y0, z1), c)
  render.OverrideDepthEnable(false, false); render.CullMode(MATERIAL_CULLMODE_CCW)
  if CATH and CATH.couche_c then                   -- les silhouettes lointaines, devant le rideau, seulement sur lui
    render.SetStencilCompareFunction(STENCIL_EQUAL); render.SetStencilPassOperation(STENCIL_KEEP)
    render.ClearBuffersObeyStencil(c.r, c.g, c.b, 255, true)   -- v82 : profondeur remise au loin sur le rideau
    cam.IgnoreZ(true); CATH.couche_c(); cam.IgnoreZ(false)
    if CATH.opaque then CATH.opaque() end            -- v82 : la cathédrale lointaine (couche B) devant le rideau
    cam.IgnoreZ(true)
    local zb, zm, zh = z0, SC.Z0 + off.z + 450, SC.Z0 + off.z + 1300   -- v77 : brume au pied du rideau
    local c = SC.RIDEAU
    render.SetColorMaterial(); render.CullMode(MATERIAL_CULLMODE_NONE)
    mesh.Begin(MATERIAL_QUADS, 8)
    for _, f in ipairs({ { x0, y0, x1, y0 }, { x0, y1, x1, y1 }, { x0, y0, x0, y1 }, { x1, y0, x1, y1 } }) do
      for _, b in ipairs({ { zb, zm, 255, 255 }, { zm, zh, 255, 0 } }) do
        mesh.Position(Vector(f[1], f[2], b[1])); mesh.Color(c.r, c.g, c.b, b[3]); mesh.AdvanceVertex()
        mesh.Position(Vector(f[3], f[4], b[1])); mesh.Color(c.r, c.g, c.b, b[3]); mesh.AdvanceVertex()
        mesh.Position(Vector(f[3], f[4], b[2])); mesh.Color(c.r, c.g, c.b, b[4]); mesh.AdvanceVertex()
        mesh.Position(Vector(f[1], f[2], b[2])); mesh.Color(c.r, c.g, c.b, b[4]); mesh.AdvanceVertex()
      end
    end
    mesh.End()
    render.CullMode(MATERIAL_CULLMODE_CCW); cam.IgnoreZ(false)
  end
  render.SetStencilEnable(false)
end)
