}
local actif = CreateClientConVar("lac_cath", "1", false, false, "Lac noir : la cathédrale dans la scène complète (0 : coupée)", 0, 1)
local MAT = CreateMaterial("lac_cath_v6b_opaque", "UnlitGeneric", { ["$basetexture"] = "color/white", ["$vertexcolor"] = "1" })
local MATT = CreateMaterial("lac_cath_v6b_voile", "UnlitGeneric", { ["$basetexture"] = "color/white", ["$vertexcolor"] = "1",
  ["$vertexalpha"] = "1", ["$translucent"] = "1" })
local LUEUR = CreateMaterial("lac_cath_v6b_lueur", "UnlitGeneric", { ["$basetexture"] = "color/white", ["$vertexcolor"] = "1",
  ["$vertexalpha"] = "1", ["$additive"] = "1" })
local HALO = Material("sprites/light_glow02_add")
local FUMEE = Material("particle/particle_smokegrenade")
local PIED, BRUME = { 34, 32, 40 }, { 206, 218, 232 }          -- v8 : pied à la teinte mesurée des props (72, 68, 78 éclairés)
local FACE = { 1.0, 0.8, 0.6, 0.72 }  -- sud (vers le lac), est, nord, ouest
local FADE, SOMMET = 3900, 6900
local FX, SX = FADE, SOMMET                           -- v10 : fondu en cours (la façade haute fond plus tard : pignon lisible)
local qualite = GetConVar("lac_qualite") or CreateClientConVar("lac_qualite", "1", true, false)
local MTX = Matrix()
local off, plaque, IMO, IMT, IML, cle = nil, nil, nil, nil, nil, nil
local ICO, BORNES_B, BORNES_C, BORNES_S
local SOMMETS = {}                                    -- v11 : sommets des aiguilles hautes {x, y, z}, d'où partent les éclats

local PALE, TON = 0, 1                               -- v9 : aiguilles plus pâles que la façade ; arcs-boutants plus sombres
local function couleur(z, y, face, a)
  local t = math.Clamp((z - 1700) / 6500, 0, 1) ^ 1.1 * 0.9 + math.Clamp((y - 900) / 5000, 0, 1) * 0.3 + math.Clamp((y - 6000) / 22000, 0, 1) * 0.5   -- v7 : lointains plus pâles
  t = math.min(t + PALE, 0.97)
  local f = 1 - (1 - t) * (1 - face)
  return Color(Lerp(t, PIED[1], BRUME[1]) * f, Lerp(t, PIED[2], BRUME[2]) * f, Lerp(t, PIED[3], BRUME[3]) * f, a or 255)
end
local function alpha(z) return z <= FX and 255 or 255 * math.max(0, 1 - (z - FX) / (SX - FX)) ^ 1.5 end   -- v8 : plus de NaN au-dessus de SOMMET

local function maillages(Lst)                          -- v8 : lots de 24 000 sommets au plus (4 000 quads)
  local res, i = {}, 1
  while i <= #Lst do
    local part = {}
    for j = i, math.min(i + 23999, #Lst) do part[#part + 1] = Lst[j] end
    local m = Mesh(); m:BuildFromTriangles(part); res[#res + 1] = m
    i = i + 24000
  end
  return res
end
local compte = 0                                       -- appels de dessin (compté seulement pendant la mesure)
local function dessiner(ms) for i = 1, #ms do ms[i]:Draw() end; compte = compte + #ms end
local IMOF, IMTF

local function construire()
  local O, T, L = {}, {}, {}
  local function liste(z) return z <= FX and O or T end
  local function v(Lst, p, f) Lst[#Lst + 1] = { pos = p, color = couleur(p.z, p.y, f * TON * (p.z < 500 and (0.62 + 0.38 * p.z / 500) or 1), alpha(p.z)) } end
  local function tri(a, b, c, f) local Lst = liste(math.max(a.z, b.z, c.z)); v(Lst, a, f); v(Lst, b, f); v(Lst, c, f) end
  local function quad(a, b, c, d, f) tri(a, b, c, f); tri(a, c, d, f) end
  local function boite(x0, x1, y0, y1, z0, z1, dessus)
    local z = z0
    while z < z1 do                                   -- tranches de 400 u : le fondu suit la hauteur
      local zb = math.min(z + 400, z1)
      quad(Vector(x0, y0, z), Vector(x1, y0, z), Vector(x1, y0, zb), Vector(x0, y0, zb), FACE[1])
      quad(Vector(x1, y0, z), Vector(x1, y1, z), Vector(x1, y1, zb), Vector(x1, y0, zb), FACE[2])
      quad(Vector(x1, y1, z), Vector(x0, y1, z), Vector(x0, y1, zb), Vector(x1, y1, zb), FACE[3])
      quad(Vector(x0, y1, z), Vector(x0, y0, z), Vector(x0, y0, zb), Vector(x0, y1, zb), FACE[4])
      z = zb
    end
    if dessus then quad(Vector(x0, y0, z1), Vector(x1, y0, z1), Vector(x1, y1, z1), Vector(x0, y1, z1), 1) end
  end
  local function fleche(x, y, w, z0, z1)              -- pinacle : pyramide effilée
    local s = Vector(x, y, z1)
    local c = { Vector(x - w, y - w, z0), Vector(x + w, y - w, z0), Vector(x + w, y + w, z0), Vector(x - w, y + w, z0) }
    for i = 1, 4 do tri(c[i], c[i % 4 + 1], s, FACE[i]) end
  end
  local function ogive(x, z, w, h, y, f)              -- fenêtre en arc brisé : rectangle + pointe (plaquée sur un mur)
    local zr = z + h - w * 1.1
    quad(Vector(x - w, y, z), Vector(x + w, y, z), Vector(x + w, y, zr), Vector(x - w, y, zr), f)
    tri(Vector(x - w, y, zr), Vector(x + w, y, zr), Vector(x, y, z + h), f)
  end
  -- mur percé : grille de cases de 95 u, cases retirées pour les ouvertures (on voit le vide au travers) et la ruine
  local function mur(x0, x1, z0, z1, y0, y1, trou)
    local nx, nz = math.floor((x1 - x0) / 95 + 0.5), math.floor((z1 - z0) / 95 + 0.5)
    local dx, dz = (x1 - x0) / nx, (z1 - z0) / nz
    local function plein(i, k) return i >= 0 and i < nx and k >= 0 and k < nz and not trou(x0 + (i + 0.5) * dx, z0 + (k + 0.5) * dz) end
    for i = 0, nx - 1 do
      for k = 0, nz - 1 do
        local xa, xb, za, zb = x0 + i * dx, x0 + (i + 1) * dx, z0 + k * dz, z0 + (k + 1) * dz
        if plein(i, k) then
          quad(Vector(xa, y0, za), Vector(xb, y0, za), Vector(xb, y0, zb), Vector(xa, y0, zb), FACE[1])
          quad(Vector(xb, y1, za), Vector(xa, y1, za), Vector(xa, y1, zb), Vector(xb, y1, zb), FACE[3])
          if not plein(i, k + 1) then quad(Vector(xa, y0, zb), Vector(xb, y0, zb), Vector(xb, y1, zb), Vector(xa, y1, zb), 1) end
          if not plein(i - 1, k) then quad(Vector(xa, y1, za), Vector(xa, y0, za), Vector(xa, y0, zb), Vector(xa, y1, zb), FACE[4]) end
          if not plein(i + 1, k) then quad(Vector(xb, y0, za), Vector(xb, y1, za), Vector(xb, y1, zb), Vector(xb, y0, zb), FACE[2]) end
          if not plein(i, k - 1) and k > 0 then quad(Vector(xa, y1, za), Vector(xb, y1, za), Vector(xb, y0, za), Vector(xa, y0, za), 0.5) end
        end
      end
    end
  end
  local g = 1402
  local function r() g = (g * 16807) % 2147483647 return g / 2147483647 end

  -- ---------- 1. façade au-dessus de la zone : 3 retraits, grande ogive ouverte, angle écroulé, pignon pointu ----------
  FX, SX = 5900, 7700                                  -- v10 : la façade reste opaque jusqu'au-dessus du pignon
  local function dans_ogive(x, z, cx, z0, w, h)
    if math.abs(x - cx) > w or z < z0 or z > z0 + h then return false end
    local zr = z0 + h - w * 1.1
    return z <= zr or math.abs(x - cx) <= w * (z0 + h - z) / (z0 + h - zr)
  end
  mur(-570, 570, 1880, 3020, 0, 95, function(x, z) return dans_ogive(x, z, 0, 2060, 190, 860) end)
  mur(-445, 445, 3020, 4160, 45, 140, function(x, z)
    return dans_ogive(x, z, 0, 3200, 110, 700) or (x < -150 and z > 3600 + (x + 445) * 1.6)      -- angle gauche écroulé
  end)
  mur(-300, 300, 4160, 5120, 90, 185, function(x, z) return dans_ogive(x, z, 0, 4300, 70, 520) end)
  for k = 0, 9 do                                      -- pignon pointu, en bandes (le fondu suit la hauteur)
    local za, zb = 5120 + k * 175, 5120 + (k + 1) * 175
    local wa, wb = 300 * (1 - k / 10), 300 * (1 - (k + 1) / 10)
    quad(Vector(-wa, 90, za), Vector(wa, 90, za), Vector(wb, 90, zb), Vector(-wb, 90, zb), FACE[1])
    quad(Vector(wa, 185, za), Vector(-wa, 185, za), Vector(-wb, 185, zb), Vector(wb, 185, zb), FACE[3])
    quad(Vector(wa, 90, za), Vector(wa, 185, za), Vector(wb, 185, zb), Vector(wb, 90, zb), FACE[2])
    quad(Vector(-wa, 185, za), Vector(-wa, 90, za), Vector(-wb, 90, zb), Vector(-wb, 185, zb), FACE[4])
  end
  for k = 0, 8 do                                      -- v9 : crochets sur les deux rampants du pignon
    local z = 5120 + (k + 0.6) * 175
    local w = 300 * (1 - (k + 0.6) / 10)
    for _, sx in ipairs({ -1, 1 }) do
      tri(Vector(sx * w, 88, z), Vector(sx * (w + 46), 88, z + 30), Vector(sx * (w - 10), 88, z + 70), 0.85)
    end
  end
  for k = 0, 15 do                                     -- oculus noir du pignon (r 85) cerclé d'un tore clair
    local a, b = k / 16 * math.pi * 2, (k + 1) / 16 * math.pi * 2
    tri(Vector(0, 88, 5470), Vector(math.cos(a) * 85, 88, 5470 + math.sin(a) * 85), Vector(math.cos(b) * 85, 88, 5470 + math.sin(b) * 85), 0.03)
    quad(Vector(math.cos(a) * 85, 87, 5470 + math.sin(a) * 85), Vector(math.cos(b) * 85, 87, 5470 + math.sin(b) * 85),
      Vector(math.cos(b) * 108, 87, 5470 + math.sin(b) * 108), Vector(math.cos(a) * 108, 87, 5470 + math.sin(a) * 108), 1)
  end
  ogive(-95, 5160, 32, 230, 88, 0.03); ogive(95, 5160, 32, 230, 88, 0.03)        -- deux lancettes sous l'oculus
  fleche(0, 137, 26, 6870, 7300)                       -- fleuron au sommet du pignon
  -- contreforts qui montent par ressauts et finissent en pinacles effilés de hauteurs différentes
  for _, c in ipairs({ { -570, 3020, 4300 }, { 570, 3020, 4500 }, { -190, 4160, 5600 }, { 190, 4160, 5450 } }) do
    boite(c[1] - 30, c[1] + 30, -56, 0, 990, c[2], true)
    fleche(c[1], -28, 34, c[2], c[3])
  end
  for _, c in ipairs({ { -445, 4160, 4900 }, { 445, 4160, 5000 }, { -300, 5120, 5800 }, { 300, 5120, 5750 } }) do
    fleche(c[1], 70, 28, c[2], c[3])
  end
  -- ogives et niches variées sur les retraits (sombres, plaquées)
  for _, o in ipairs({ { -380, 2100, 60, 520 }, { 380, 2150, 50, 460 }, { -470, 2700, 30, 220 }, { 470, 2650, 30, 260 },
      { -300, 3250, 45, 420 }, { 300, 3200, 40, 380 }, { 250, 3720, 26, 200 }, { -190, 4350, 30, 300 }, { 190, 4380, 26, 260 } }) do
    ogive(o[1], o[2], o[3], o[4], (o[2] < 3020 and -1) or (o[2] < 4160 and 44) or 89, 0.3)
  end

  FX, SX = FADE, SOMMET
  -- ---------- 2. nef au toit pointu, arcs-boutants volants (3 par côté) ----------
  local function ogive_x(x, y, z, w, h, f, prof)      -- ogive sur un mur de nef (plan y-z) ; v9 : ébrasements de prof u
    local zr = z + h - w * 1.1
    quad(Vector(x, y - w, z), Vector(x, y + w, z), Vector(x, y + w, zr), Vector(x, y - w, zr), f)
    tri(Vector(x, y - w, zr), Vector(x, y + w, zr), Vector(x, y, z + h), f)
    if prof then                                       -- joues de la baie, du nu du mur vers le fond : ombre lisible de biais
      local xi = x - prof
      quad(Vector(x, y - w, z), Vector(xi, y - w, z), Vector(xi, y - w, zr), Vector(x, y - w, zr), 0.35)
      quad(Vector(x, y + w, z), Vector(xi, y + w, z), Vector(xi, y + w, zr), Vector(x, y + w, zr), 0.55)
      quad(Vector(x, y - w, z), Vector(x, y + w, z), Vector(xi, y + w, z), Vector(xi, y - w, z), 0.7)
    end
  end
  local RUINE = { [-1] = { [3] = 2150, [4] = 1980 }, [1] = { [6] = 2380 } }              -- travées écroulées : pas de toit
  for s = -1, 1, 2 do
    -- v8 : mur bas jusqu'à la corniche, mur haut en retrait de 30 u, pilastres, ogives sombres, travées écroulées
    local function bx(a, b) return math.min(s * a, s * b), math.max(s * a, s * b) end
    local x0, x1 = bx(430, 480); boite(x0, x1, 95, 1500, 0, 1860, false)
    x0, x1 = bx(480, 520); boite(x0, x1, 95, 1500, 1860, 1900, true)                       -- corniche
    quad(Vector(s * 480, 95, 1860), Vector(s * 520, 95, 1860), Vector(s * 520, 1500, 1860), Vector(s * 480, 1500, 1860), 0.3)
    for k = 0, 7 do
      local ya, yb, yc = 95 + k * 175, 95 + (k + 1) * 175, 95 + (k + 0.5) * 175
      local zt = RUINE[s][k] or 2800
      x0, x1 = bx(430, 450); boite(x0, x1, ya, yb, 1900, zt, zt < 2800)
      if zt < 2800 then                                                                   -- arête cassée en dents
        tri(Vector(s * 450, ya, zt), Vector(s * 450, ya + 70, zt), Vector(s * 450, ya + 30, zt + 160), 0.8)
        tri(Vector(s * 450, yb - 60, zt), Vector(s * 450, yb, zt), Vector(s * 450, yb, zt + 260), 0.8)
      end
      ogive_x(s * 481, yc, 360, 58, 900, 0.04, s * 40)                                    -- rang bas (v9 : creusé, noir)
      if zt >= 2800 then ogive_x(s * 451, yc, 1980, 50, 700, 0.04, s * 25) end             -- rang haut
    end
    for k = 0, 8 do                                                                        -- pilastres
      local y = 95 + k * 175
      x0, x1 = bx(480, 516); boite(x0, x1, y - 18, y + 18, 0, 1860, false)
      x0, x1 = bx(450, 470); boite(x0, x1, y - 12, y + 12, 1900, (RUINE[s][k] or RUINE[s][k - 1]) and 2200 or 2700, true)
    end
    for _, y in ipairs({ 400, 800, 1200 }) do
      local px = s * 1020                                                        -- v7 : piles plus loin, plus grosses
      TON = 0.55                                                                 -- v9 : piles et arcs sombres, détachés du mur pâle
      boite(px - 70, px + 70, y - 70, y + 70, 0, 1500, true)                     -- pile
      boite(px - 48, px + 48, y - 48, y + 48, 1500, 1900, true)                  -- ressaut
      fleche(px, y, 46, 1900, 2900)
      local A, B, C = { s * 960, 1850 }, { s * 480, 2650 }, { s * 480, 2150 }    -- dessus droit, dessous en arc
      for k = 0, 7 do
        local t0, t1 = k / 8, (k + 1) / 8
        local function haut(t) return Lerp(t, A[1], B[1]), Lerp(t, A[2], B[2]) end
        local function bas(t)
          local u = 1 - t
          return u * u * (s * 950) + 2 * u * t * (s * 600) + t * t * C[1], u * u * 1450 + 2 * u * t * 1600 + t * t * C[2]
        end
        local xa, za = haut(t0); local xb, zb = haut(t1); local xc, zc = bas(t1); local xd, zd = bas(t0)
        for _, yy in ipairs({ y - 60, y + 60 }) do
          quad(Vector(xa, yy, za), Vector(xb, yy, zb), Vector(xc, yy, zc), Vector(xd, yy, zd), yy < y and FACE[1] or FACE[3])
        end
        quad(Vector(xa, y - 60, za), Vector(xb, y - 60, zb), Vector(xb, y + 60, zb), Vector(xa, y + 60, za), 1)
        quad(Vector(xd, y + 60, zd), Vector(xc, y + 60, zc), Vector(xc, y - 60, zc), Vector(xd, y - 60, zd), 0.45)
      end
    end
  end
  TON = 1
  for k = 0, 7 do                                      -- toit de la nef : deux pans jusqu'à 4 300 u
    local ya, yb = 95 + k * 175, 95 + (k + 1) * 175
    for s = -1, 1, 2 do
      if not RUINE[s][k] then                          -- v8 : toit ouvert sur le vide au-dessus des travées écroulées
        quad(Vector(s * 450, ya, 2800), Vector(s * 450, yb, 2800), Vector(0, yb, 3900), Vector(0, ya, 3900), s > 0 and FACE[2] or FACE[4])
      end
    end
  end

  -- ---------- 3. aiguilles irrégulières en groupes ----------
  PALE = 0.16                                          -- v9 : la façade se détache des aiguilles en plongée
  local GROUPES = { { -1300, 3500, 5 }, { 1200, 4300, 6 },   -- v10 : les deux paquets qui cachaient la nef de profil reculés derrière
    { -250, 2300, 6 }, { -1900, 2800, 4 }, { 1700, 3000, 5 }, { 300, 3800, 4 } }
  for _, gr in ipairs(GROUPES) do
    for n = 1, gr[3] do
      local x, y = gr[1] + (r() * 2 - 1) * 380, gr[2] + (r() * 2 - 1) * 320
      local h = math.Clamp(4000 + r() * 4000 - (n == 1 and 0 or r() * 900), 4000, 8000)
      local w = (n == 1 and 150 or 60) + r() * 90
      local ox, oy = x - gr[1], y - gr[2]                                      -- v7 : penché en éventail depuis le centre du paquet
      local lx, ly = (ox / 380 * 0.1 + (gr[1] > 0 and 0.05 or -0.05) + (r() * 2 - 1) * 0.04) * h, (oy / 320 * 0.06 + (r() * 2 - 1) * 0.03) * h
      local casse = r() < 0.4 and (0.5 + r() * 0.3) or 0
      local ng = 3 + math.floor(r() * 4)
      local niv, zr, wr = {}, 0, 1
      for k = 1, ng do niv[k] = { zr, wr }; zr = zr + (0.6 / ng) * (0.7 + r() * 0.6); wr = wr * (0.62 + r() * 0.25) end
      local top = (casse > 0 and casse or 0.9) * h
      local function P(px, py, z) return Vector(px + lx * z / h, py + ly * z / h, z) end
      local z0, w0 = 0, w
      for k = 1, ng do
        local zk = math.min((niv[k + 1] and niv[k + 1][1] or 0.9) * h, top)
        if zk <= z0 then break end
        local wk = w * niv[k][2]
        local wt = wk * (0.9 + r() * 0.1)
        local c0 = { { -wk, -wk }, { wk, -wk }, { wk, wk }, { -wk, wk } }
        local c1 = { { -wt, -wt }, { wt, -wt }, { wt, wt }, { -wt, wt } }
        local z = z0
        while z < zk do                                -- tranches : le haut s'efface dans la brume
          local zb = math.min(z + 600, zk)
          local ta, tb = (z - z0) / (zk - z0), (zb - z0) / (zk - z0)
          for i = 1, 4 do
            local j = i % 4 + 1
            quad(P(x + Lerp(ta, c0[i][1], c1[i][1]), y + Lerp(ta, c0[i][2], c1[i][2]), z), P(x + Lerp(ta, c0[j][1], c1[j][1]), y + Lerp(ta, c0[j][2], c1[j][2]), z),
              P(x + Lerp(tb, c0[j][1], c1[j][1]), y + Lerp(tb, c0[j][2], c1[j][2]), zb), P(x + Lerp(tb, c0[i][1], c1[i][1]), y + Lerp(tb, c0[i][2], c1[i][2]), zb), FACE[i])
          end
          z = zb
        end
        if k > 1 then quad(P(x - w0, y - w0, z0), P(x + w0, y - w0, z0), P(x + wk, y - wk, z0), P(x - wk, y - wk, z0), 1) end
        z0, w0 = zk, wt
      end
      local c = { P(x - w0, y - w0, z0), P(x + w0, y - w0, z0), P(x + w0, y + w0, z0), P(x - w0, y + w0, z0) }
      if z0 > 3200 then local ps = P(x, y, z0); SOMMETS[#SOMMETS + 1] = { ps.x, ps.y, ps.z } end
      if casse > 0 then
        local s = {}
        for i = 1, 4 do s[i] = c[i] + Vector(0, 0, (r() * 2 - 1) * 0.07 * h) end
        for i = 1, 4 do local j = i % 4 + 1; quad(c[i], c[j], s[j], s[i], FACE[i]) end
        quad(s[1], s[2], s[3], s[4], 1)
      else
        local s = P(x, y, h)
        for i = 1, 4 do tri(c[i], c[i % 4 + 1], s, FACE[i]) end
      end
    end
  end

  PALE = 0
  -- ---------- 4. ogives et niches variées sur la façade en props (z < 1 900), plaquées à 1,5 u devant ----------
  for _, o in ipairs({ { -380, 60, 70, 700 }, { 380, 60, 70, 700 }, { -470, 900, 30, 300 }, { -290, 900, 30, 300 },
      { 290, 860, 40, 380 }, { 470, 880, 26, 280 }, { -380, 1300, 90, 520 }, { 380, 1340, 80, 480 }, { 0, 1150, 120, 650 },
      { -100, 60, 26, 120 }, { 100, 60, 26, 120 }, { -470, 1650, 20, 160 }, { 470, 1620, 22, 180 } }) do
    ogive(o[1], o[2], o[3], o[4], -1.5, 0.25)
  end

  -- ---------- 5. voiles de brume en profondeur (translucides) ----------
  local function voile(y, z0, z1, x0, x1, amax)
    for k = 0, 5 do
      local za, zb = z0 + (z1 - z0) * k / 6, z0 + (z1 - z0) * (k + 1) / 6
      local aa, ab = amax * math.sin(math.pi * k / 6) ^ 0.7, amax * math.sin(math.pi * (k + 1) / 6) ^ 0.7
      local ca, cb = Color(BRUME[1], BRUME[2], BRUME[3], aa), Color(BRUME[1], BRUME[2], BRUME[3], ab)
      T[#T + 1] = { pos = Vector(x0, y, za), color = ca }; T[#T + 1] = { pos = Vector(x1, y, za), color = ca }
      T[#T + 1] = { pos = Vector(x1, y, zb), color = cb }; T[#T + 1] = { pos = Vector(x0, y, za), color = ca }
      T[#T + 1] = { pos = Vector(x1, y, zb), color = cb }; T[#T + 1] = { pos = Vector(x0, y, zb), color = cb }
    end
  end

  -- ---------- 6. lueur carmin (additive) : derrière la rosace, dans le portail ----------
  local function disque(cx, cy, cz, rr, c0, c1)
    for k = 0, 23 do
      local a, b = k / 24 * math.pi * 2, (k + 1) / 24 * math.pi * 2
      L[#L + 1] = { pos = Vector(cx, cy, cz), color = c0 }
      L[#L + 1] = { pos = Vector(cx + math.cos(a) * rr, cy, cz + math.sin(a) * rr), color = c1 }
      L[#L + 1] = { pos = Vector(cx + math.cos(b) * rr, cy, cz + math.sin(b) * rr), color = c1 }
    end
  end
  for k = 0, 15 do                                     -- v7 : vitrail (secteurs carmin et meneaux sombres), lueur / 3
    local a, b = k / 16 * math.pi * 2, (k + 1) / 16 * math.pi * 2
    local c = (k % 2 == 0) and Color(66, 6, 10, 255) or Color(14, 2, 3, 255)
    local ci = Color(40, 4, 7, 255)
    for _, rr in ipairs({ { 0, 60 }, { 66, 150 } }) do
      local r0, r1 = rr[1], rr[2]
      local cc = r0 == 0 and ci or c
      L[#L + 1] = { pos = Vector(math.cos(a) * r0, 100, 573 + math.sin(a) * r0), color = cc }
      L[#L + 1] = { pos = Vector(math.cos(a) * r1, 100, 573 + math.sin(a) * r1), color = cc }
      L[#L + 1] = { pos = Vector(math.cos(b) * r1, 100, 573 + math.sin(b) * r1), color = cc }
      L[#L + 1] = { pos = Vector(math.cos(a) * r0, 100, 573 + math.sin(a) * r0), color = cc }
      L[#L + 1] = { pos = Vector(math.cos(b) * r1, 100, 573 + math.sin(b) * r1), color = cc }
      L[#L + 1] = { pos = Vector(math.cos(b) * r0, 100, 573 + math.sin(b) * r0), color = cc }
    end
  end
  local p0, p1 = Color(60, 6, 9, 255), Color(10, 1, 2, 255)
  L[#L + 1] = { pos = Vector(-48, -3, 4), color = p0 }; L[#L + 1] = { pos = Vector(48, -3, 4), color = p0 }
  L[#L + 1] = { pos = Vector(48, -3, 200), color = p1 }; L[#L + 1] = { pos = Vector(-48, -3, 4), color = p0 }
  L[#L + 1] = { pos = Vector(48, -3, 200), color = p1 }; L[#L + 1] = { pos = Vector(-48, -3, 200), color = p1 }

  local On, Tn = O, T; O, T = {}, {}                  -- v8 : la section 7 va dans des listes à part (brume lointaine)
  -- ---------- 7. v7 « infini » : perspective forcée, lignes de fuite, bande de brume sur l'horizon ----------
  local function cath_loin(x, y, k)                    -- cathédrale lointaine simplifiée : façade, pignon, deux tours, flèche
    boite(x - 550 * k, x + 550 * k, y, y + 300 * k, 0, 3000 * k, false)
    for j = 0, 5 do
      local za, zb = 3000 * k + j * 250 * k, 3000 * k + (j + 1) * 250 * k
      local wa, wb = 550 * k * (1 - j / 6), 550 * k * (1 - (j + 1) / 6)
      quad(Vector(x - wa, y, za), Vector(x + wa, y, za), Vector(x + wb, y, zb), Vector(x - wb, y, zb), FACE[1])
      quad(Vector(x + wa, y + 300 * k, za), Vector(x - wa, y + 300 * k, za), Vector(x - wb, y + 300 * k, zb), Vector(x + wb, y + 300 * k, zb), FACE[3])
    end
    for _, s in ipairs({ -1, 1 }) do
      boite(x + s * 700 * k - 160 * k, x + s * 700 * k + 160 * k, y, y + 320 * k, 0, 3900 * k, false)
      fleche(x + s * 700 * k, y + 160 * k, 160 * k, 3900 * k, 6200 * k)
    end
    fleche(x, y + 150 * k, 90 * k, 4400 * k, 7600 * k)
  end
  for _, c in ipairs({ { -3200, 9000, 0.85 }, { 3600, 12500, 0.72 }, { -2400, 17000, 0.6 }, { 2000, 21000, 0.5 }, { -900, 25500, 0.42 } }) do
    cath_loin(c[1], c[2], c[3])
  end
  for k = 0, 9 do                                      -- deux alignements de paquets d'aiguilles qui convergent vers (0, 30 000)
    local y = 6000 + k * 2200
    local f = 1 - (y - 6000) / 26000
    for _, s in ipairs({ -1, 1 }) do
      local x, h, w = s * 3000 * f, 7000 * (1 - k * 0.055), 120 * (1 - k * 0.06)
      for j = 0, 2 do
        local px, hh = x + (j - 1) * 260 * f, h * (0.75 + 0.25 * ((j + k) % 3) / 2)
        boite(px - w, px + w, y - w, y + w, 0, hh * 0.7, false)
        fleche(px, y, w * 0.8, hh * 0.7, hh)
      end
    end
  end
  for k = 0, 47 do                                     -- bande de brume sur l'horizon (cylindre r 14 000), sans bord
    local a, b = k / 48 * math.pi * 2, (k + 1) / 48 * math.pi * 2
    local xa, ya, xb, yb = math.cos(a) * 14000, 1500 + math.sin(a) * 14000, math.cos(b) * 14000, 1500 + math.sin(b) * 14000
    local Z = { { -2500, 235, 1 }, { 250, 235, 1 }, { 1300, 200, 0 }, { 2600, 150, 0 }, { 5500, 0, 0 } }
    for j = 1, 4 do
      local e0, e1 = Z[j], Z[j + 1]
      local c0 = Color(Lerp(e0[3], BRUME[1], 14), Lerp(e0[3], BRUME[2], 16), Lerp(e0[3], BRUME[3], 22), e0[2])
      local c1 = Color(Lerp(e1[3], BRUME[1], 14), Lerp(e1[3], BRUME[2], 16), Lerp(e1[3], BRUME[3], 22), e1[2])
      T[#T + 1] = { pos = Vector(xa, ya, Z[j][1]), color = c0 }; T[#T + 1] = { pos = Vector(xb, yb, Z[j][1]), color = c0 }
      T[#T + 1] = { pos = Vector(xb, yb, Z[j + 1][1]), color = c1 }; T[#T + 1] = { pos = Vector(xa, ya, Z[j][1]), color = c0 }
      T[#T + 1] = { pos = Vector(xb, yb, Z[j + 1][1]), color = c1 }; T[#T + 1] = { pos = Vector(xa, ya, Z[j + 1][1]), color = c1 }
    end
  end

  local Of, Tf = O, T; O, T = On, Tn
  IMO, IMT, IML, IMOF, IMTF = maillages(O), maillages(T), maillages(L), maillages(Of), maillages(Tf)
  -- bornes réelles du ciel 3D (pour le contrôle de la boîte)
  local mn, mx = Vector(1e9, 1e9, 1e9), Vector(-1e9, -1e9, -1e9)
  for _, Lst in ipairs({ O, T, L, Of, Tf }) do
    for i = 1, #Lst do local p = Lst[i].pos
      mn.x = math.min(mn.x, p.x); mn.y = math.min(mn.y, p.y); mn.z = math.min(mn.z, p.z)
      mx.x = math.max(mx.x, p.x); mx.y = math.max(mx.y, p.y); mx.z = math.max(mx.z, p.z)
    end
  end
  BORNES_B = { mn, mx }
  print("[lac_cathedrale_aiguilles] triangles : opaques " .. #O / 3 .. " + loin " .. #Of / 3 .. ", translucides " .. #T / 3 .. " + loin " .. #Tf / 3 .. ", lueur " .. #L / 3)
end

-- ---------- couche C : silhouettes plates très loin (anneaux de flèches, 40 000 à 70 000 u), échelle 1/64 ----------
local function construire_c()
  local C, g = {}, 911
  local function r() g = (g * 16807) % 2147483647 return g / 2147483647 end
  local mn, mx = Vector(1e9, 1e9, 1e9), Vector(-1e9, -1e9, -1e9)
  local CIEL = { 168, 204, 236 }
  local col, hmax, R
  local function v(x, y, z)                              -- plus haut = plus pâle et plus transparent (bords fondus)
    local t = math.Clamp((z + 1500) / (hmax * 1.7), 0, 1)
    C[#C + 1] = { pos = Vector(x, y, z), color = Color(Lerp(t, col[1], CIEL[1]), Lerp(t, col[2], CIEL[2]), Lerp(t, col[3], CIEL[3]), 255 * (1 - t ^ 2.2)) }
    mn.x = math.min(mn.x, x); mn.y = math.min(mn.y, y); mn.z = math.min(mn.z, z)
    mx.x = math.max(mx.x, x); mx.y = math.max(mx.y, y); mx.z = math.max(mx.z, z)
  end
  local function pt(a, d) return math.cos(a) * R - math.sin(a) * d, 1500 + math.sin(a) * R + math.cos(a) * d end
  local function aiguille(a, base, w, hz, lean)          -- penchée (lean le long de l'anneau), cassée une fois sur quatre
    local xa, ya = pt(a, -w); local xb, yb = pt(a, w)
    if r() < 0.25 then
      local c = 0.45 + r() * 0.3
      local zc, wc = base + (hz - base) * c, w * (1 - c * 0.8)
      local xc, yc = pt(a, lean * c + wc); local xd, yd = pt(a, lean * c - wc)
      v(xa, ya, base); v(xb, yb, base); v(xc, yc, zc + (r() - 0.5) * w * 3)
      v(xa, ya, base); v(xc, yc, zc + (r() - 0.5) * w * 3); v(xd, yd, zc + (r() - 0.5) * w * 3)
    else
      local xt, yt = pt(a, lean)
      v(xa, ya, base); v(xb, yb, base); v(xt, yt, hz)
    end
  end
  for _, an in ipairs({ { 70000, { 196, 207, 224 }, 9000 }, { 55000, { 178, 191, 212 }, 11000 }, { 40000, { 158, 172, 197 }, 13000 } }) do
    R, col, hmax = an[1], an[2], an[3]
    local a, n = 0, r()
    while a < math.pi * 2 do                           -- du plus loin au plus près : pas de profondeur dans cette couche
      local da = math.pi * 2 / 144 * (0.35 + r() * 1.5)
      local b = math.min(a + da, math.pi * 2)
      n = math.Clamp(n + (r() - 0.5) * 0.45, 0, 1)
      local ha = hmax * (0.08 + 0.32 * n)
      local hb = hmax * (0.08 + 0.32 * math.Clamp(n + (r() - 0.5) * 0.3, 0, 1))
      local xa, ya = pt(a, 0); local xb, yb = pt(b, 0)
      v(xa, ya, -6000); v(xb, yb, -6000); v(xb, yb, hb)
      v(xa, ya, -6000); v(xb, yb, hb); v(xa, ya, ha)
      local haut = math.max(ha, hb)
      if r() < 0.07 then                                -- une cathédrale lointaine : façade, pignon, deux tours inégales
        local m, l = (a + b) / 2, R * da * 0.35
        local hf = hmax * (0.45 + r() * 0.35)
        local x1, y1 = pt(m, -l); local x2, y2 = pt(m, l)
        v(x1, y1, haut); v(x2, y2, haut); v(x2, y2, hf); v(x1, y1, haut); v(x2, y2, hf); v(x1, y1, hf)
        local xg, yg = pt(m, (r() - 0.5) * l * 0.3)
        v(x1, y1, hf); v(x2, y2, hf); v(xg, yg, hf + l * (0.5 + r() * 0.6))
        aiguille(m - da * 0.32, haut, l * 0.22, hf + hmax * (0.5 + r() * 0.5), (r() - 0.5) * l * 0.4)
        aiguille(m + da * 0.32, haut, l * 0.18, hf + hmax * (0.3 + r() * 0.4), (r() - 0.5) * l * 0.4)
      end
      local na = r() < 0.4 and 0 or (1 + math.floor(r() * 3))
      for j = 1, na do                                  -- paquet d'aiguilles : largeurs, hauteurs et pentes variées
        local w = R * (0.0012 + r() * 0.005)
        local hz = math.min(haut + hmax * (0.15 + r() * 1.0) ^ 1.4, hmax * 1.5)
        aiguille(a + (b - a) * r(), haut * 0.8, w, hz, (r() - 0.5) * w * 6)
      end
      a = b
    end
  end
  ICO = Mesh(); ICO:BuildFromTriangles(C)
  BORNES_C = { mn, mx }
  print("[lac_cathedrale_aiguilles] couche C : " .. #C / 3 .. " triangles")
end

-- ---------- ciel 3D : centres des miniatures dans la boîte (repère de la cathédrale : pied de façade en 0) ----------
-- La boîte (zone de build) dans ce repère : x -4 047..4 047, y -7 447..847, z 0..1 945 (scène du lac centrée dans la zone,
-- cathédrale en y +4 800 de la scène). Couche B (cathédrale au-dessus de la zone, aiguilles, lointains, brume) à 1/16
-- autour de CB ; couche C (silhouettes) à 1/64 autour de CC. Rien n'est dessiné à sa taille réelle hors de la boîte.
local SB, SC = 16, 64
local CB, CCC = Vector(0, -4000, 300), Vector(0, -5600, 400)
local ZX0, ZX1, ZY0, ZY1, ZZ0, ZZ1 = -4047, 4047, -7447, 847, 0, 1945
local function ecrire_bornes()
  local function m(cn, s, b) return string.format("%.0f %.0f %.0f", cn.x + b.x / s, cn.y + b.y / s, cn.z + b.z / s) end
  file.Write("cath_bornes.txt", "boite " .. ZX0 .. " " .. ZY0 .. " " .. ZZ0 .. " " .. ZX1 .. " " .. ZY1 .. " " .. ZZ1 .. "\n" ..
    "B_min " .. m(CB, SB, BORNES_B[1]) .. "\nB_max " .. m(CB, SB, BORNES_B[2]) .. "\n" ..
    "C_min " .. m(CCC, SC, BORNES_C[1]) .. "\nC_max " .. m(CCC, SC, BORNES_C[2]) .. "\n" ..
    "sprites_reels_min " .. m(CB, SB, BORNES_S[1]) .. "\nsprites_reels_max " .. m(CB, SB, BORNES_S[2]) .. "\n")
end

-- ---------- effets (v9, optimisation) : cendres et braises en maillages fixes, que seule une matrice fait bouger ----------
-- Nappes et nuages restent des sprites tournés vers l'œil (96 au plus) : en plans fixes, ils ne rendaient pas pareil
-- (bords nets, voile devant la caméra au pied de la façade ; comparaison du 25/11 6 h 15).
-- Avant (v8) : jusqu'à 816 render.DrawSprite par image, chacun calculé en Lua. Maintenant : 2 à 3 lots par groupe et par
-- palier de lac_qualite, et le Lua ne fait plus que quelques matrices par image. Cendres et braises tombent en boucle :
-- deux copies décalées de 7 000 u, coupées par deux plans (sol et haut de la chute). Nappes et nuages dérivent lentement.
local NC, NN, NU = 720, 72, 24
local PALIER_C, PALIER_N, PALIER_U = { 160, 360, 720 }, { 28, 48, 72 }, { 8, 16, 24 }   -- lac_qualite 0, 1, 2
local CHUTE = 7000
local VIT = { 50, 80 }                                   -- vitesses de chute des deux groupes de cendres (u/s)
local CEN, BRA                                          -- CEN[groupe][palier], BRA[palier]
-- v11 : brume qui coule (FLOT[palier]), reflet tournant du vitrail, éclats d'aiguilles
local NF, HF, PALIER_F = 20, 6000, { 6, 12, 20 }
local FLOT, REFLET, ECLAT
local NE, PALIER_E, GE = 6, { 2, 4, 6 }, 520             -- éclats, paliers, pesanteur ralentie (u/s²)
local e_dep, e_src, e_vx, e_vy, e_sp, e_sc = {}, {}, {}, {}, {}, {}
local nx, ny, nz, nt, ns = {}, {}, {}, {}, {}             -- nappes (sprites)
local ux, uy, uz, us = {}, {}, {}, {}                     -- nuages (sprites)

-- une bouffée = trois plans croisés (face au sud, face à l'est, à plat) : se lit de tous les côtés sans être tournée vers l'œil
local function bouffee(L, x, y, z, w, h, c)
  local hw, hh = w / 2, h / 2
  local function q(a1, a2, a3, a4)
    L[#L + 1] = { pos = a1, u = 0, v = 1, color = c }; L[#L + 1] = { pos = a2, u = 1, v = 1, color = c }; L[#L + 1] = { pos = a3, u = 1, v = 0, color = c }
    L[#L + 1] = { pos = a1, u = 0, v = 1, color = c }; L[#L + 1] = { pos = a3, u = 1, v = 0, color = c }; L[#L + 1] = { pos = a4, u = 0, v = 0, color = c }
  end
  q(Vector(x - hw, y, z - hh), Vector(x + hw, y, z - hh), Vector(x + hw, y, z + hh), Vector(x - hw, y, z + hh))
  q(Vector(x, y - hw, z - hh), Vector(x, y + hw, z - hh), Vector(x, y + hw, z + hh), Vector(x, y - hw, z + hh))
  q(Vector(x - hw, y - hh * 2, z), Vector(x + hw, y - hh * 2, z), Vector(x + hw, y + hh * 2, z), Vector(x - hw, y + hh * 2, z))
end

local function braise(L, x, y, z, w, c)                -- disque en dégradé (additif : le bord noir ne dessine rien)
  local N = Color(0, 0, 0, 255)
  for _, pl in ipairs({ 1, 2 }) do
    for k = 0, 7 do
      local a, b = k / 8 * math.pi * 2, (k + 1) / 8 * math.pi * 2
      local ca, sa, cb, sb = math.cos(a) * w, math.sin(a) * w, math.cos(b) * w, math.sin(b) * w
      L[#L + 1] = { pos = Vector(x, y, z), color = c }
      if pl == 1 then
        L[#L + 1] = { pos = Vector(x + ca, y, z + sa), color = N }; L[#L + 1] = { pos = Vector(x + cb, y, z + sb), color = N }
      else
        L[#L + 1] = { pos = Vector(x, y + ca, z + sa), color = N }; L[#L + 1] = { pos = Vector(x, y + cb, z + sb), color = N }
      end
    end
  end
end

local function construire_effets()
  local g = 77
  local function r() g = (g * 16807) % 2147483647 return g / 2147483647 end
  local mn, mx = Vector(1e9, 1e9, 1e9), Vector(-1e9, -1e9, -1e9)
  local function borne(Lst, dx, dz)                      -- bornes réelles, dérive comprise
    for i = 1, #Lst do local p = Lst[i].pos
      mn.x = math.min(mn.x, p.x - dx); mn.y = math.min(mn.y, p.y); mn.z = math.min(mn.z, p.z - dz)
      mx.x = math.max(mx.x, p.x + dx); mx.y = math.max(mx.y, p.y); mx.z = math.max(mx.z, p.z + dz)
    end
  end
  local function lots(listes, dx, dz)                    -- listes[palier] -> maillages cumulés par palier
    local res = {}
    for k = 1, 3 do borne(listes[k], dx, dz); res[k] = Mesh(); res[k]:BuildFromTriangles(listes[k]) end
    return res
  end
  local function palier(i, P) return (i <= P[1] and 1) or (i <= P[2] and 2) or 3 end
  local CC, CB2 = Color(40, 38, 44, 160), Color(230, 50, 30, 255)
  local LC, LB = { { {}, {}, {} }, { {}, {}, {} } }, { {}, {}, {} }
  for i = 1, NC do
    local x, y, z = (r() * 2 - 1) * 1800, -900 + r() * 2600, r() * CHUTE
    r(); r()                                             -- (vitesse et phase d'avant : même tirage, mêmes positions)
    if i % 12 == 0 then braise(LB[palier(i, PALIER_C)], x, y, z, 13, CB2)
    else bouffee(LC[i % 2 + 1][palier(i, PALIER_C)], x, y, z, 13, 13, CC) end
  end
  for i = 1, NN do
    local bande = ({ 250, 700, 1400, 2300, 3400, 4500, 5800 })[(i % 7) + 1]
    nx[i] = (r() * 2 - 1) * (1200 + bande * 0.25); ny[i] = (bande < 1000) and (-420 + r() * 380) or (-300 + r() * 3600)
    nz[i] = bande + r() * 250; nt[i] = r() * 6.28; ns[i] = 700 + r() * 900 + bande * 0.2
    local dx, dz = 260 + ns[i] * 0.8, 40 + ns[i] * 0.275   -- bornes : dérive + demi-sprite
    mn.x = math.min(mn.x, nx[i] - dx); mx.x = math.max(mx.x, nx[i] + dx); mn.y = math.min(mn.y, ny[i]); mx.y = math.max(mx.y, ny[i])
    mn.z = math.min(mn.z, nz[i] - dz); mx.z = math.max(mx.z, nz[i] + dz)
  end
  for i = 1, NU do
    ux[i] = (r() * 2 - 1) * 3000; uy[i] = r() * 4500; uz[i] = 6500 + r() * 3000; us[i] = 3000 + r() * 3000
    mn.x = math.min(mn.x, -3000 - us[i] * 0.9); mx.x = math.max(mx.x, 3000 + us[i] * 0.9); mn.y = math.min(mn.y, uy[i]); mx.y = math.max(mx.y, uy[i])
    mx.z = math.max(mx.z, uz[i] + us[i] * 0.3)
  end
  -- v11 : brume qui coule le long de la façade : traînées verticales en dégradé (0 en haut et en bas), juste devant le mur
  local LF = { {}, {}, {} }
  for i = 1, NF do
    local sx = (i % 2 == 0) and 1 or -1
    local x, y, z = sx * (260 + r() * 340), -24 - r() * 50, r() * HF   -- v12 : dégagée du portail et de la rosace
    local w, h = 120 + r() * 220, 900 + r() * 1100
    local a = 30 + r() * 15
    local c0, c1 = Color(BRUME[1], BRUME[2], BRUME[3], 0), Color(BRUME[1], BRUME[2], BRUME[3], a)
    local L = LF[palier(i, PALIER_F)]
    local zs = { z, z + h * 0.25, z + h * 0.7, z + h }
    local cs = { c0, c1, c1, c0 }
    for j = 1, 3 do                                    -- deux demi-bandes : bords latéraux à 0, milieu plein (aucun bord net)
      local hw = w / 2 * (1 - j * 0.12)
      for _, cote in ipairs({ -1, 1 }) do
        local xe = x + cote * hw
        L[#L + 1] = { pos = Vector(x, y, zs[j]), color = cs[j] }; L[#L + 1] = { pos = Vector(xe, y, zs[j]), color = c0 }; L[#L + 1] = { pos = Vector(xe, y, zs[j + 1]), color = c0 }
        L[#L + 1] = { pos = Vector(x, y, zs[j]), color = cs[j] }; L[#L + 1] = { pos = Vector(xe, y, zs[j + 1]), color = c0 }; L[#L + 1] = { pos = Vector(x, y, zs[j + 1]), color = cs[j + 1] }
      end
    end
  end
  FLOT = lots(LF, 0, 0)
  -- v11 : reflet qui tourne dans le vitrail (3 secteurs clairs sur 16, centrés en 0 : la matrice les pose sur la rosace)
  local LE = {}
  for _, kk in ipairs({ 0, 5, 11 }) do
    local a, b = kk / 16 * math.pi * 2, (kk + 1) / 16 * math.pi * 2
    local c0, c1 = Color(110, 14, 20, 255), Color(0, 0, 0, 255)
    for _, rr in ipairs({ { 66, 150 } }) do
      LE[#LE + 1] = { pos = Vector(math.cos(a) * rr[1], 0, math.sin(a) * rr[1]), color = c1 }
      LE[#LE + 1] = { pos = Vector(math.cos(a) * rr[2], 0, math.sin(a) * rr[2]), color = c0 }
      LE[#LE + 1] = { pos = Vector(math.cos(b) * rr[2], 0, math.sin(b) * rr[2]), color = c0 }
      LE[#LE + 1] = { pos = Vector(math.cos(a) * rr[1], 0, math.sin(a) * rr[1]), color = c1 }
      LE[#LE + 1] = { pos = Vector(math.cos(b) * rr[2], 0, math.sin(b) * rr[2]), color = c0 }
      LE[#LE + 1] = { pos = Vector(math.cos(b) * rr[1], 0, math.sin(b) * rr[1]), color = c1 }
    end
  end
  for kk = 0, 23 do                                    -- v12 : anneau doux au bord de la rosace (carmin vers noir : additif)
    local a, b = kk / 24 * math.pi * 2, (kk + 1) / 24 * math.pi * 2
    local ci, ce = Color(120, 12, 20, 255), Color(0, 0, 0, 255)
    local r1, r2 = 150, 250
    LE[#LE + 1] = { pos = Vector(math.cos(a) * r1, 0, math.sin(a) * r1), color = ci }
    LE[#LE + 1] = { pos = Vector(math.cos(a) * r2, 0, math.sin(a) * r2), color = ce }
    LE[#LE + 1] = { pos = Vector(math.cos(b) * r2, 0, math.sin(b) * r2), color = ce }
    LE[#LE + 1] = { pos = Vector(math.cos(a) * r1, 0, math.sin(a) * r1), color = ci }
    LE[#LE + 1] = { pos = Vector(math.cos(b) * r2, 0, math.sin(b) * r2), color = ce }
    LE[#LE + 1] = { pos = Vector(math.cos(b) * r1, 0, math.sin(b) * r1), color = ci }
  end
  REFLET = Mesh(); REFLET:BuildFromTriangles(LE)
  -- v11 : éclat d'aiguille (tétraèdre allongé, taille 1, sombre ; la matrice le pose, le tourne et l'agrandit)
  local A, B, C, D = Vector(0, 0, 1), Vector(-0.5, -0.4, -0.6), Vector(0.55, -0.35, -0.5), Vector(0, 0.6, -0.55)
  local LT = {}
  for _, f in ipairs({ { A, B, C, 1 }, { A, C, D, 0.7 }, { A, D, B, 0.55 }, { B, D, C, 0.4 } }) do
    local cc = Color(30 * f[4] + 8, 28 * f[4] + 7, 36 * f[4] + 9, 255)
    LT[#LT + 1] = { pos = f[1], color = cc }; LT[#LT + 1] = { pos = f[2], color = cc }; LT[#LT + 1] = { pos = f[3], color = cc }
  end
  ECLAT = Mesh(); ECLAT:BuildFromTriangles(LT)
  table.sort(SOMMETS, function(a, b) return a[3] > b[3] end)   -- v12 : les plus hautes d'abord
  for i = 1, NE do                                       -- départs décalés ; sources tirées parmi les sommets
    e_dep[i] = i * 1.7; e_src[i] = 1 + (i * 3) % math.min(#SOMMETS, 8)
    e_vx[i], e_vy[i] = (r() * 2 - 1) * 110, (r() * 2 - 1) * 80; e_sp[i] = 40 + r() * 120; e_sc[i] = 320 + r() * 260
  end
  for i = 1, #SOMMETS do                                 -- bornes : chute jusqu'au sol avec la dérive (6 s au plus)
    local so = SOMMETS[i]
    mn.x = math.min(mn.x, so[1] - 700); mx.x = math.max(mx.x, so[1] + 700)
    mn.y = math.min(mn.y, so[2] - 500); mx.y = math.max(mx.y, so[2] + 500); mx.z = math.max(mx.z, so[3] + 200)
  end
  mn.x = math.min(mn.x, -700); mx.x = math.max(mx.x, 700); mn.y = math.min(mn.y, -80)
  CEN = { lots(LC[1], 0, 0), lots(LC[2], 0, 0) }
  BRA = lots(LB, 0, 0)
  mn.z = math.max(mn.z, 0)                               -- cendres et braises coupées au sol (plan de coupe)
  BORNES_S = { mn, mx }
end

local MB, MC = Matrix(), Matrix()                       -- matrices des miniatures (posées par preparer)
local BX, BY, BZ = 0, 0, 0
local VP, CH = Vector(), Color(200, 20, 30, 150)
local CN, CU = Color(BRUME[1], BRUME[2], BRUME[3], 45), Color(BRUME[1], BRUME[2], BRUME[3], 55)
local MT, VT, NBAS, NHAUT = Matrix(), Vector(), Vector(0, 0, 1), Vector(0, 0, -1)
local function pt(x, y, z) VP:SetUnpacked(BX + x / SB, BY + y / SB, BZ + z / SB) return VP end   -- repère réel -> miniature
local function poser(ms, n, x, z)                        -- n premiers lots, décalés de (x, 0, z) unités réelles
  MT:Set(MB); VT:SetUnpacked(x, 0, z); MT:Translate(VT)
  cam.PushModelMatrix(MT)
  for i = 1, n do ms[i]:Draw() end
  cam.PopModelMatrix()
  return n
end
local DrawSprite, sin = render.DrawSprite, math.sin   -- appelés jusqu'à 100 fois par image : cache local (norme du lac)
local VCOL, AR, VS = Vector(1, 1, 1), Angle(), Vector(1, 1, 1)
local function battement(t)                              -- v11 : pouls carmin (lent, avec un second coup), 0 à 1
  local a = sin(t * 1.3)
  local b = math.max(0, a) ^ 2 * 0.75 + math.max(0, sin(t * 1.3 - 0.55)) ^ 6 * 0.25 + 0.12
  local T = M.T
  if T then                                              -- scène complète : le vitrail bat en carmin au boum et au cœur
    if T < 9 then b = b * 0.15 end
    local TR = M.TR or 0
    for k, tb in ipairs({ 3.0, 6.5, 10.0, 13.5 }) do   -- un battement carmin par coup de cloche, de plus en plus fort
      if TR >= tb and TR < tb + 5 then b = b + (0.35 + 0.3 * k) * math.exp(-(TR - tb) / (k == 4 and 1.6 or 0.9)) end
    end
    if T >= 9 and T < 14 then b = b + 1.6 * math.exp(-(T - 9) / 1.1) end
    if T >= 36 and T < 39 then b = b + 1.1 * math.exp(-(T - 36) / 0.7) end
  end
  return b
end
local CPOUS = Color(BRUME[1], BRUME[2], BRUME[3], 0)
local declenche = false
local function eclats(t, ne)                             -- v11 : éclats qui se détachent des sommets et tombent en tournoyant
  if #SOMMETS == 0 then return 0 end
  local T = M.T
  if T then                                              -- scène complète : rien avant le boum ; tous partent à 9 s
    if T < 8.5 then
      if declenche then declenche = false end
      for i = 1, ne do e_dep[i] = 1e9 end
    elseif T >= 9.05 and not declenche then
      declenche = true
      for i = 1, ne do e_dep[i] = t + (i - 1) * 0.22 end
    end
  end
  local m = 0
  for i = 1, ne do
    local tau = t - e_dep[i]
    if tau > 0 then
      local so = SOMMETS[e_src[i]]
      local z = so[3] - 0.5 * GE * tau * tau
      if z < -300 then                                   -- arrivé sous le sol : repart d'un autre sommet un peu plus tard
        e_dep[i] = (M.T and M.T > 26) and 1e9 or (t + 2 + (i * 1.3) % 4); e_src[i] = e_src[i] % math.min(#SOMMETS, 8) + 1
      else
        render.SetMaterial(MAT)
        MT:Set(MB); VT:SetUnpacked(so[1] + e_vx[i] * tau, so[2] + e_vy[i] * tau, z); MT:Translate(VT)
        AR:SetUnpacked(tau * e_sp[i], tau * e_sp[i] * 0.6, tau * e_sp[i] * 0.3); MT:Rotate(AR)
        VS:SetUnpacked(e_sc[i], e_sc[i], e_sc[i] * 1.7); MT:Scale(VS)
        cam.PushModelMatrix(MT); ECLAT:Draw(); cam.PopModelMatrix()
        m = m + 1
        if tau < 1.6 then                                -- poussière à la cassure, qui se dissipe
          render.SetMaterial(FUMEE)
          CPOUS.a = 110 * (1 - tau / 1.6)
          DrawSprite(pt(so[1], so[2], so[3]), (400 + tau * 500) / SB, (400 + tau * 500) / SB, CPOUS)
          m = m + 1
        end
      end
    end
  end
  return m
end
local function effets()
  local q = qualite:GetInt()
  local k = (q <= 0 and 1) or (q == 1 and 2) or 3
  local t = CurTime()
  local n = 0
  local nn, nu = PALIER_N[k], PALIER_U[k]
  render.CullMode(MATERIAL_CULLMODE_NONE)                 -- v11 : traînées et éclats vus des deux côtés
  render.SetMaterial(FUMEE)
  for i = 1, nu do                                        -- nuages qui dérivent lentement au loin (sprites)
    local x = (ux[i] + t * 25 + 3000) % 6000 - 3000
    DrawSprite(pt(x, uy[i], uz[i]), us[i] * 1.8 / SB, us[i] * 0.6 / SB, CU)
  end
  for i = 1, nn do                                        -- nappes de brume qui lèchent la façade (sprites)
    DrawSprite(pt(nx[i] + sin(t * 0.05 + nt[i]) * 260, ny[i], nz[i] + sin(t * 0.08 + nt[i]) * 40), ns[i] * 1.6 / SB, ns[i] * 0.55 / SB, CN)
  end
  n = n + nu + nn
  render.SetMaterial(MATT)                                -- cendres : petits plans croisés, couleur pleine
  local ancien = render.EnableClipping(true)              -- chute en boucle : coupée au sol et en haut de la chute
  render.PushCustomClipPlane(NBAS, BZ)
  render.PushCustomClipPlane(NHAUT, -(BZ + CHUTE / SB))
  for j = 1, 2 do                                         -- cendres : chute et balancement lent par groupe
    local o, bx = -((t * VIT[j]) % CHUTE), sin(t * 0.45 + j * 2.1) * 34
    n = n + poser(CEN[j], k, bx, o) + poser(CEN[j], k, bx, o + CHUTE)
  end
  render.SetMaterial(LUEUR)                               -- braises : scintillement
  local f = 0.8 + 0.2 * sin(t * 9.3)
  VCOL:SetUnpacked(f, f * 0.9, f * 0.9); LUEUR:SetVector("$color", VCOL)
  local o = -((t * 60) % CHUTE)
  n = n + poser(BRA, k, sin(t * 0.7) * 22, o) + poser(BRA, k, sin(t * 0.7) * 22, o + CHUTE)
  VCOL:SetUnpacked(1, 1, 1); LUEUR:SetVector("$color", VCOL)
  render.PopCustomClipPlane(); render.PopCustomClipPlane()
  render.SetMaterial(MATT)                                -- brume qui coule le long de la façade (boucle de 6 000 u)
  render.PushCustomClipPlane(NBAS, BZ)
  render.PushCustomClipPlane(NHAUT, -(BZ + HF / SB))
  local of = -((t * 140) % HF)
  n = n + poser(FLOT, k, 0, of) + poser(FLOT, k, 0, of + HF)
  render.PopCustomClipPlane(); render.PopCustomClipPlane()
  n = n + eclats(t, PALIER_E[k])
  render.EnableClipping(ancien)
  render.CullMode(MATERIAL_CULLMODE_CCW)               -- v12 : plus de halos en sprite (boule rouge)
  return n
end

-- dessin seulement pour un joueur dans la zone (test toutes les 0,5 s, une lecture de position) ; lac_cath_partout 1 : planches
local coupe = false                                     -- vrai pendant la mesure « sans la cathédrale »
local partout = CreateClientConVar("lac_cath_partout", "0", false, false)
local dans, zone_t = false, 0
local function zone()
  if coupe or M.coupee or not actif:GetBool() or not off then return false end   -- v85 : sans build, rien
  if M.T then return off ~= nil end                     -- scène complète : dessinée pendant la démo du lac
  if zone_t > CurTime() then return dans end
  zone_t = CurTime() + 0.5
  if partout:GetBool() then dans = true return dans end
  local ply = LocalPlayer()
  if not IsValid(ply) or not off then dans = false return dans end
  local p = ply:GetPos()
  local x, y, z = p.x - off.x, p.y - off.y, p.z - off.z
  dans = x >= ZX0 and x <= ZX1 and y >= ZY0 and y <= ZY1 and z >= ZZ0 - 64 and z <= ZZ1
  return dans
end

-- ---------- mesure (lac_cath_mesure 1) : 300 images sans la cathédrale puis 300 avec ; temps Lua par hook, appels de dessin ----------
local mes = CreateClientConVar("lac_cath_mesure", "0", false, false)
local mesure_actif, MZ = false, nil
local function mesure_image()                          -- appelé une fois par image (RenderScene) seulement pendant la mesure
  if not MZ then MZ = { n = 0, off = 0, on = 0, c = 0, o = 0, t = 0, appels = 0 }; coupe = true end
  MZ.n = MZ.n + 1
  if MZ.n <= 300 then MZ.off = MZ.off + FrameTime() else MZ.on = MZ.on + FrameTime() end
  if MZ.n == 300 then coupe = false end
  if MZ.n >= 600 then
    file.Write("cath_mesure.txt", string.format(
      "images_ms_sans %.3f\nimages_ms_avec %.3f\nlua_ms_couche_c %.4f\nlua_ms_opaque %.4f\nlua_ms_translucide %.4f\nappels_par_image %.1f\nqualite %d\n",
      MZ.off / 300 * 1000, MZ.on / 300 * 1000, MZ.c / 300 * 1000, MZ.o / 300 * 1000, MZ.t / 300 * 1000, MZ.appels / 300, qualite:GetInt()))
    print("[lac_cathedrale_aiguilles] mesure écrite dans data/cath_mesure.txt")
    MZ, mesure_actif = nil, false
    RunConsoleCommand("lac_cath_mesure", "0")
  end
end

local verif = 0
local brume_props                                         -- définie plus bas, avec la brume
function M.oublier() off = nil; M.T, M.TR, M.actif = nil, nil, false end   -- v85 : build retiré
function M.reperer(o)                                     -- appelé par le repérage du lac (une fois par seconde)
  M.coupee = file.Exists("lac_mesure/cath_off.txt", "DATA")   -- mesure « lac seul » sans console ni focus
  if mes:GetBool() and not mesure_actif then mesure_actif = true; RunConsoleCommand("lac_cath_partout", "1") end
  local neuf = not off or (o + DECAL) ~= off
  off = o + DECAL
  if not neuf and verif > CurTime() then return end
  verif = CurTime() + 5
  for _, e in ipairs(ents.FindInBox(off + Vector(-1400, -1500, -60), off + Vector(1400, 700, 2100))) do
    if CATM[e:GetModel() or ""] and e.RenderOverride ~= brume_props then e.RenderOverride = brume_props end
  end
end

-- caméras mises à l'échelle (aucune allocation : vecteurs et matrices réutilisés). L'œil vient de RenderScene.
local OEIL, AEIL = Vector(), Angle()
local OB, OC = Vector(), Vector()
local ZN, ZF, zt = 7, 30000, 0
local ECH_B, ECH_C = Vector(1 / SB, 1 / SB, 1 / SB), Vector(1 / SC, 1 / SC, 1 / SC)
local cle2
hook.Add("RenderScene", "lac_cath", function(o, a) OEIL:Set(o); AEIL:Set(a); if mesure_actif then mesure_image() end end)
local function preparer()
  if not IMO then construire(); construire_c(); construire_effets(); ecrire_bornes() end
  if cle2 ~= off then
    BX, BY, BZ = off.x + CB.x, off.y + CB.y, off.z + CB.z
    MB:Identity(); MB:SetTranslation(Vector(BX, BY, BZ)); MB:SetScale(ECH_B)
    MC:Identity(); MC:SetTranslation(Vector(off.x + CCC.x, off.y + CCC.y, off.z + CCC.z)); MC:SetScale(ECH_C)
    cle2 = Vector(off.x, off.y, off.z)
  end
  OB:SetUnpacked(BX + (OEIL.x - off.x) / SB, BY + (OEIL.y - off.y) / SB, BZ + (OEIL.z - off.z) / SB)
  OC:SetUnpacked(off.x + CCC.x + (OEIL.x - off.x) / SC, off.y + CCC.y + (OEIL.y - off.y) / SC, off.z + CCC.z + (OEIL.z - off.z) / SC)
  if CurTime() > zt then zt = CurTime() + 1; local vs = render.GetViewSetup(); ZN, ZF = vs.znear or 7, vs.zfar or 30000 end
end
local FS, FE, FM, FL = 1500, 11000, 0.9, 1             -- brume de la cathédrale (taille réelle), réglée par presence()
local FC = { 206, 218, 232 }                         -- couleur de la brume : pâle vue d'en bas (le ciel), sombre vue d'en haut (le sol)
local function brume_b()                               -- v8 : la miniature a exactement la brume des props réels (raccord)
  render.FogMode(MATERIAL_FOG_LINEAR); render.FogStart(FS / SB); render.FogEnd(FE / SB); render.FogMaxDensity(FM)
  render.FogColor(FC[1], FC[2], FC[3])
end
local function brume_loin()                            -- lointains (section 7) : perspective aérienne plus longue
  render.FogMode(MATERIAL_FOG_LINEAR); render.FogStart(FS * 1.2 / SB); render.FogEnd(FE * FL / SB); render.FogMaxDensity(FM * 0.94)
  render.FogColor(FC[1], FC[2], FC[3])
end
local F0 = { m = 0, s = 0, e = 0, r = 0, g = 0, b = 0 }   -- état de la brume du moteur, remis après chaque dessin
local function sauver() F0.m = render.GetFogMode(); F0.s, F0.e = render.GetFogDistances(); F0.r, F0.g, F0.b = render.GetFogColor() end
local function brume_monde() render.FogMode(F0.m); render.FogStart(F0.s); render.FogEnd(F0.e); render.FogColor(F0.r, F0.g, F0.b) end
local function lisse(u) u = math.min(1, math.max(0, u)) return u * u * (3 - 2 * u) end
local function presence()                              -- cachée dans la brume au début, révélée après le boum (9 s -> 17 s)
  local T = M.T
  local k = 1
  if T then k = 0.1 + 0.9 * lisse((T - 9) / 8)
    if T < 9 then k = 0.1 end                         -- v8 : pendant les cloches la cathédrale reste dans la brume (sinon un carton gris) ; seul le vitrail la perce
  end
  FS, FE, FM, FL = 1500 * k, 3500 + 7500 * k, 0.985 - 0.085 * k, 1.4 + 0.78 * k
  -- v18 : brume sombre (nuit) quelle que soit la vue : la cathédrale se dresse en silhouette noire sur le ciel pâle, le
  -- vitrail bat en carmin dedans, et vue d'en haut elle se fond dans le sol au lieu d'un carton gris (v16 : la couleur suivait
  -- le regard, rendu différent selon la caméra). Le boum la révèle en dégageant la brume (k de 0,1 à 1).
  FC[1], FC[2], FC[3] = 36, 40, 52
end
brume_props = function(e)                              -- props réels de la cathédrale : la même brume que la miniature
  sauver()
  render.FogMode(MATERIAL_FOG_LINEAR); render.FogStart(FS); render.FogEnd(FE); render.FogMaxDensity(FM)
  render.FogColor(FC[1], FC[2], FC[3])
  e:DrawModel()
  brume_monde()
end
-- couche C : après le ciel 2D, avant le monde, sans profondeur (le monde et la couche B passent devant)
M.couche_c = function()                                   -- v76 : appelée aussi par le rideau
  if not off or not zone() then return end
  sauver(); presence()
  local t0 = mesure_actif and SysTime()
  preparer()
  cam.Start3D(OC, AEIL, nil, nil, nil, nil, nil, 1, 4000)
  render.OverrideDepthEnable(true, false)
  render.FogMode(MATERIAL_FOG_NONE)
  render.SetMaterial(MATT); render.CullMode(MATERIAL_CULLMODE_NONE)              -- v8 : translucide, sommets fondus
  cam.PushModelMatrix(MC); ICO:Draw(); cam.PopModelMatrix()
  render.CullMode(MATERIAL_CULLMODE_CCW)
  render.OverrideDepthEnable(false, false)
  cam.End3D()
  if t0 and MZ then MZ.c = MZ.c + SysTime() - t0; MZ.appels = MZ.appels + 1 end
end
hook.Add("PostDraw2DSkyBox", "lac_cath", function()
  if M.actif then render.Clear(8, 9, 14, 255, false, false) end   -- v76 : ciel de nuit pendant la scène
  M.couche_c()
end)
-- couche B : caméra à 1/16 avec znear et zfar divisés par 16 : la profondeur écrite est celle de la taille réelle,
-- donc le monde et les props se mélangent correctement avec la miniature.
function M.opaque()                                       -- appelé par le hook opaque du lac
  if not off or not zone() then return end
  OEIL:Set(EyePos()); AEIL:Set(EyeAngles()); sauver(); presence()
  local t0 = mesure_actif and SysTime()
  compte = 0
  preparer()
  cam.Start3D(OB, AEIL, nil, nil, nil, nil, nil, ZN / SB, ZF / SB)
  render.SetMaterial(MAT); render.CullMode(MATERIAL_CULLMODE_NONE)
  cam.PushModelMatrix(MB)
  brume_loin(); dessiner(IMOF)
  brume_b(); dessiner(IMO)
  cam.PopModelMatrix()
  render.CullMode(MATERIAL_CULLMODE_CCW)
  cam.End3D()
  brume_monde()
  if t0 and MZ then MZ.o = MZ.o + SysTime() - t0; MZ.appels = MZ.appels + compte end
end
function M.translucide()                                  -- appelé par le hook translucide du lac
  if not off or not zone() then return end
  OEIL:Set(EyePos()); AEIL:Set(EyeAngles()); sauver()
  local t0 = mesure_actif and SysTime()
  compte = 0
  preparer()
  cam.Start3D(OB, AEIL, nil, nil, nil, nil, nil, ZN / SB, ZF / SB)
  render.CullMode(MATERIAL_CULLMODE_NONE)
  cam.PushModelMatrix(MB)
  brume_loin(); render.SetMaterial(MATT); dessiner(IMTF)
  brume_b(); dessiner(IMT)
  local tb = CurTime()                                    -- v11 : vitrail et portail battent ; un reflet tourne dans la rosace
  local pb = 0.55 + 0.75 * battement(tb)
  VCOL:SetUnpacked(pb, pb, pb); LUEUR:SetVector("$color", VCOL)
  render.FogMaxDensity(FM * 0.3); render.SetMaterial(LUEUR); dessiner(IML); render.FogMaxDensity(FM)
  MT:Set(MB); VT:SetUnpacked(0, 99, 573); MT:Translate(VT); AR:SetUnpacked(tb * 14, 0, 0); MT:Rotate(AR)
  cam.PushModelMatrix(MT); REFLET:Draw(); cam.PopModelMatrix()
  VCOL:SetUnpacked(1, 1, 1); LUEUR:SetVector("$color", VCOL)
  compte = compte + 1
  cam.PopModelMatrix()
  render.CullMode(MATERIAL_CULLMODE_CCW)
  compte = compte + effets()
  cam.End3D()
  brume_monde()
  if t0 and MZ then MZ.t = MZ.t + SysTime() - t0; MZ.appels = MZ.appels + compte end
end
print("[lac_scene_complete] cathédrale v12 accrochée au lac (façade en y 4800 du repère de l'île)")
local HALO_MAT, HC, HV = Material("sprites/light_glow02_add"), Color(230, 24, 34, 255), Vector()
function M.halo()                                         -- v16 : halo du vitrail, dessiné après l'assombrissement
  if not off or not zone() or not M.T then return end
  local a = math.min(1, math.max(0, (battement(CurTime()) - 0.2) / 1.2))
  if a <= 0.02 then return end
  HV:SetUnpacked(off.x, off.y - 90, off.z + 573)           -- devant la rosace
  render.SetMaterial(HALO_MAT)
  HC.a = 255 * a; render.DrawSprite(HV, 420 + 380 * a, 420 + 380 * a, HC)
  HC.a = 80 * a; render.DrawSprite(HV, 1500 + 900 * a, 1500 + 900 * a, HC)
end

return M

end)()

-- ======================================================================================================================
-- LES MONOLITHES FISSURÉS (module)
PIECES.MONO = (function()
-- Lac noir de Nobleza, pièce 6 : les monolithes fissurés, effets en script (25/11/2026, v1). 0 posé, rien dans le dupe.
-- Adrien 7 h 20 : « Le défi va être de rendre ça vivant avec effet, sous-effet ». Donc, sur les dalles posées en props
-- (huecomundosetails197_18, build lac_noir_monolithes) :
--  fissures carmin qui respirent (coeur fin + halo large), chacune à sa phase ;
--  la lave suinte des fissures : gouttes qui tombent jusqu'à l'eau, anneau à l'impact, flaque rouge au pied ;
--  braises qui montent des fissures, brume sombre au pied ;
--  cloches : chaque coup allume un monolithe de plus, du plus proche au plus lointain, et l'allée reste allumée ;
--  boum : les fissures éclatent (éclats incandescents qui retombent, poussière, vapeur au pied) ;
--  trône vide (scène complète) : tout s'éteint sauf un fil rouge, par MONO.eteindre(x).
-- Coût : géométrie calculée une fois par collage (points des fissures en coordonnées du monde) ; par image, aucune
-- allocation (vecteurs et couleur de travail réutilisés). Sprites bornés par lac_qualite.
-- Géométrie : la dalle est vue comme une ellipse (demi-axes = boîte du modèle, échelle du prop), les fissures suivent sa
-- surface décollées de 2 u. Banc : T_FIGE fige le temps (photos), NUIT assombrit comme la scène (colormod puis effets).
if not string.find(game.GetMap(), "hueco", 1, true) then return end
local MODELE = "models/propper/hueco_mundo_v1/huecomundosetails197_18.mdl"
local T_FIGE = -1                       -- banc : temps figé en secondes (-1 : boucle de BOUCLE s)
local NUIT = true                       -- banc seul : assombrir comme la scène ; la scène complète passe NUIT = false
local BOUCLE = 30
local CLOCHES = { 3.0, 6.5, 10.0, 13.5 }
local BOUM = 9.0                       -- scène complète : 9 (temps du lac)
local EXT = { 31, 36 }                         -- scène complète : { début, fin } de l'extinction (temps du lac)
local LUEUR = Material("effects/laser1")
local HALO = Material("sprites/light_glow02_add")
local FUMEE = Material("particle/particle_smokegrenade")
local qualite = GetConVar("lac_qualite") or CreateClientConVar("lac_qualite", "1", true, false)
local MONO = {}
local TA = 0                                     -- v70 : horloge des animations
local MN, MX = Vector(-130, -258.4, -611), Vector(130, 258.4, 611)   -- bornes_modele (atelier/moteur/geo.py)
local L = {}                            -- monolithes : { e, rang, debout, f = { {P...}, ... }, pied, ph, r }
local zsol, t0, nb = nil, nil, -1
local VP, VN = Vector(), Vector()
local COL = Color(0, 0, 0, 0)
local HAUT = Vector(0, 0, 1)
local PLAFOND = 1800                    -- boîte de la scène : 1 843 u au-dessus de l'eau ; rien ne monte plus haut
local etaint = 0                        -- 0 : vivant ; 1 : éteint sauf un fil rouge (trône vide)

local function graine(n) local s = n return function() s = (s * 1103515245 + 12345) % 2147483648; return s / 2147483648 end end

-- point de la surface (ellipse) au niveau z local, angle th, décollé de 2 u ; rend un Vector du monde
local TRI, TRI_ZMIN, TRI_DZ, NB_SEAU, rayon_mdl          -- v4 : triangles du .mdl rangés par tranche de hauteur
local function charger_tri()
  TRI = {}
  local ms = util.GetModelMeshes(MODELE)
  NB_SEAU, TRI_ZMIN = 48, MN.z
  TRI_DZ = (MX.z - MN.z) / NB_SEAU
  for i = 1, NB_SEAU do TRI[i] = {} end
  for _, m in ipairs(ms or {}) do
    local t = m.triangles
    for i = 1, #t - 2, 3 do
      local a, b, c = t[i].pos, t[i + 1].pos, t[i + 2].pos
      local z1, z2 = math.min(a.z, b.z, c.z), math.max(a.z, b.z, c.z)
      local s1 = math.max(1, math.floor((z1 - TRI_ZMIN) / TRI_DZ) + 1)
      local s2 = math.min(NB_SEAU, math.floor((z2 - TRI_ZMIN) / TRI_DZ) + 1)
      local tri = { a, b, c }
      for sx = s1, s2 do local T = TRI[sx]; T[#T + 1] = tri end
    end
  end
end

-- rayon O + t D (repère du modèle) contre les triangles : point le plus proche et normale tournée vers l'origine du rayon
rayon_mdl = function(O, D)
  if not TRI then charger_tri() end
  local sx = math.floor((O.z - TRI_ZMIN) / TRI_DZ) + 1
  if sx < 1 or sx > NB_SEAU then return end
  local best, bn = math.huge, nil
  for _, tri in ipairs(TRI[sx]) do
    local a, b, c = tri[1], tri[2], tri[3]
    local e1, e2 = b - a, c - a
    local pv = D:Cross(e2)
    local det = e1:Dot(pv)
    if math.abs(det) > 1e-6 then
      local tv = O - a
      local u = tv:Dot(pv) / det
      if u >= 0 and u <= 1 then
        local qv = tv:Cross(e1)
        local v = D:Dot(qv) / det
        if v >= 0 and u + v <= 1 then
          local t = e2:Dot(qv) / det
          if t > 0 and t < best then best, bn = t, e1:Cross(e2) end
        end
      end
    end
  end
  if not bn then return end
  bn:Normalize()
  if bn:Dot(D) > 0 then bn:Mul(-1) end
  return O + D * best, bn
end

local function surface(e, g, th, z)
  local fu = 1 - 0.38 * math.max(0, math.min(1, (z - g.z0) / g.h))  -- v2 : la dalle s'affine vers le haut
  local x = g.cx + (g.a * fu + 2) * math.cos(th)
  local y = g.cy + (g.b * fu + 2) * math.sin(th)
  -- v4 (retour d'Adrien) : la fissure colle à la vraie face du modèle, même penchée ou à moins de 90° : rayon tiré de
  -- l'extérieur vers l'axe de la dalle contre les triangles du .mdl (le prop n'a pas de collision : une trace ne le
  -- touche pas) ; l'ellipse ne sert plus que de secours
  local k = g.k
  local hp, hn = rayon_mdl(Vector((g.cx + (g.a + 120) * math.cos(th)) / k, (g.cy + (g.b + 120) * math.sin(th)) / k, z / k),
                           Vector(-(g.a + 120) * math.cos(th) / k, -(g.b + 120) * math.sin(th) / k, 0))
  if hp then MONO.touche = (MONO.touche or 0) + 1 hp:Mul(k); hn:Mul(2); hp:Add(hn) return e:LocalToWorld(hp) end
  MONO.rate = (MONO.rate or 0) + 1
  return e:LocalToWorld(Vector(x, y, z))
end

local function fissure(e, g, r, th, z0, z1, n)
  local P, z, c0 = {}, z0, th
  for i = 0, n do
    P[#P + 1] = surface(e, g, th, z)
    th = c0 + math.max(-0.55, math.min(0.55, th - c0 + (r() - 0.5) * 0.36))   -- reste sur la grande face
    z = z + (z1 - z0) / n * (0.7 + r() * 0.6)
    if z > z1 then break end
  end
  return P, th
end

local function construire(ents_)
  L = {}
  local r = graine(1405)
  local bas = {}
  for _, e in ipairs(ents_) do
    local mn, mx = MN, MX                                        -- bornes du .mdl (GetModelBounds rend autre chose)
    local k = e:GetModelScale() or 1
    local g = { cx = (mn.x + mx.x) / 2 * k, cy = (mn.y + mx.y) / 2 * k, a = (mx.x - mn.x) / 2 * k, b = (mx.y - mn.y) / 2 * k,
      z0 = mn.z * k, h = (mx.z - mn.z) * k, k = k }
    local debout = e:GetUp().z > 0.7
    local principal = e:GetUp().z > 0.98                         -- les dalles soeurs penchent de plus de 11 degrés
    local m = { e = e, g = g, debout = debout, principal = principal, f = {}, ph = r() * 6.28, k = k }
    m.pied = e:LocalToWorld(Vector(g.cx, g.cy, g.z0))
    m.centre, m.rayon = e:LocalToWorld(Vector(g.cx, g.cy, g.z0 + g.h * 0.5)), g.h * 0.6   -- v3 : tri hors champ
    if debout then bas[#bas + 1] = m.pied.z end
    L[#L + 1] = m
  end
  table.sort(bas); zsol = (bas[math.ceil(#bas / 2)] or 0) + 40   -- le pied est enfoncé de 40 u (build)
  for _, m in ipairs(L) do
    local g, e = m.g, m.e
    if m.debout then
      local z0 = g.z0 + (zsol - m.pied.z) + 6                    -- naît au ras de l'eau
      local nf = g.h > 900 and 4 or 2
      for i = 1, nf do
        local th = (i % 2 == 0 and 0 or math.pi) + (r() - 0.5) * 0.9 -- sur les deux grandes faces
        local P, thf = fissure(e, g, r, th, z0, g.z0 + g.h * (0.62 + r() * 0.22), 9)
        m.f[#m.f + 1] = P
        local j = 3 + math.floor(r() * 3)                        -- une branche par fissure
        if P[j] then
          local zj = g.z0 + (g.h * 0.08) * j
          local B = fissure(e, g, r, thf + (r() - 0.5) * 1.4, zj, zj + g.h * 0.22, 4)
          table.insert(B, 1, P[j]); m.f[#m.f + 1] = B
        end
      end
    else                                                         -- haut cassé couché : deux fissures et la cassure
      local zm, thh = g.z0 + g.h * 0.5, 0                        -- v2 : sur le dessus seulement (angle le plus haut)
      for i = 0, 11 do if surface(e, g, i * 0.5236, zm).z > surface(e, g, thh, zm).z then thh = i * 0.5236 end end
      for i = 1, 2 do m.f[#m.f + 1] = (fissure(e, g, r, thh + (i - 1.5) * 0.5, g.z0 + g.h * 0.1, g.z0 + g.h * 0.9, 7)) end
      m.cassure = e:LocalToWorld(Vector(g.cx, g.cy, g.z0))
    end
  end
  -- rang : du plus proche de l'île au plus lointain (y du monde), les dalles soeurs suivent leur voisine
  local principaux = {}
  for _, m in ipairs(L) do if m.principal then principaux[#principaux + 1] = m end end
  table.sort(principaux, function(p, q) return p.pied.y < q.pied.y end)
  for i, p in ipairs(principaux) do p.rang = i end
  for _, m in ipairs(L) do
    if not m.rang then
      local best, d = nil, 1e9
      for _, p in ipairs(principaux) do local dd = p.pied:DistToSqr(m.e:GetPos()) if dd < d then best, d = p, dd end end
      m.rang = best and best.rang or 1
    end
  end
  MONO.n = #principaux
  print(string.format("[lac_mono] rayons %d touchés, %d ratés ; %d dalles, %d monolithes debout, sol z %.0f, échelle du premier %.3f", MONO.touche or 0, MONO.rate or 0, #L, #principaux, zsol, L[1] and L[1].k or 0))
end

-- intensité d'un monolithe : respiration + coups de cloche (un de plus par coup, du proche au lointain) + boum
local function intensite(m, TR, T)
  local i = 0.5 + 0.35 * math.sin(TA * 0.8 + m.ph) + 0.15 * math.sin(TA * 2.3 + m.ph * 2)
  local coup = math.ceil(m.rang * #CLOCHES / math.max(MONO.n, 1))
  local tc = CLOCHES[math.min(coup, #CLOCHES)]
  if TR >= tc then i = i + 0.35 + 1.4 * math.exp(-(TR - tc) * 1.3) else i = 0 end   -- cloches : temps brut ; v80 : éteint avant sa cloche
  local o, ta = SC.onde(m.centre, T)               -- v81 : allumé au passage de l'onde, éclat à son arrivée
  if o <= 0 then return 0 end
  i = i + 2.2 * math.exp(-(T - ta) * 0.9)
  return i * o * (1 - etaint)
end

local function couleur(r, g, b, a) COL.r, COL.g, COL.b, COL.a = r, g, b, math.max(0, math.min(255, a)) return COL end

local function fissures(m, I, d, loin)
  local c = math.min(I, 1.6)
  local wd = d * 0.003                                           -- v2 : jamais moins d'un pixel et demi, même au fond
  if not loin then                                               -- v3 : halo large, un segment sur deux, un seul changement de matériau
    render.SetMaterial(HALO)
    local col = couleur(180, 8, 14, 105 * c)
    local w = math.max(90 + 60 * c, wd * 14)
    for _, P in ipairs(m.f) do
      for j = 3, #P, 2 do render.DrawBeam(P[j - 2], P[j], w, 0, 1, col) end
      local mi = P[math.ceil(#P / 2)]                            -- lumière qui sort de la pierre, autour de la fissure
      render.DrawSprite(mi, 260 * m.k, 420 * m.k, couleur(150, 6, 12, 28 * c))
      col = couleur(180, 8, 14, 105 * c)
    end
  end
  render.SetMaterial(LUEUR)                                      -- coeur, plus chaud quand ça monte
  local col = couleur(255, 40 + 70 * math.max(c - 1, 0), 24, 255 * c)
  local w = math.max(12 + 8 * c, wd)
  for _, P in ipairs(m.f) do
    for j = 2, #P do render.DrawBeam(P[j - 1], P[j], w, 0, 1, col) end
  end
end

local function lave(m, I, T, nq)
  if not m.debout then
    render.SetMaterial(HALO)                                     -- la cassure du haut tombé : braise dans l'eau
    render.DrawSprite(m.cassure, 220 + 120 * I, 220 + 120 * I, couleur(190, 18, 12, 120 * math.min(I, 1.5)))
    return
  end
  render.SetMaterial(HALO)                                       -- flaque rouge au pied, à plat sur l'eau
  VP:Set(m.pied); VP.z = zsol + 2
  render.DrawQuadEasy(VP, HAUT, 700 + 200 * I, 700 + 200 * I, couleur(170, 10, 14, 110 * math.min(I, 1.5)), 0)
  for fi, P in ipairs(m.f) do                                    -- gouttes : de mi-fissure jusqu'à l'eau, puis anneau
    if fi > nq then break end
    local src = P[math.min(#P, 3 + fi % 3)]
    local per = 3.2 + fi * 0.7
    local a = ((TA + m.ph * 3 + fi * 1.3) % per) / per
    local zc = src.z - (src.z - zsol) * a * a                    -- chute qui accélère
    if a < 0.92 then
      VP:Set(src); VP.z = zc
      render.DrawSprite(VP, 24, 38, couleur(255, 80, 24, 255 * math.min(I, 1)))
    else
      local b = (a - 0.92) / 0.08
      VP:Set(src); VP.z = zsol + 3
      render.DrawQuadEasy(VP, HAUT, 30 + 140 * b, 30 + 140 * b, couleur(255, 60, 20, 200 * (1 - b)), 0)
    end
  end
end

local function braises(m, I, T, n)
  render.SetMaterial(HALO)
  for i = 1, n do
    local P = m.f[1 + i % #m.f]
    local src = P[1 + (i * 7) % #P]
    local vie = 4 + (i % 5) * 0.7
    local a = ((TA + i * 0.37 + m.ph) % vie) / vie
    VP:Set(src)
    VP.x = VP.x + math.sin(TA * 0.7 + i) * 30 * a
    VP.y = VP.y + math.cos(TA * 0.6 + i * 1.7) * 30 * a
    VP.z = VP.z + a * (260 + (i % 4) * 60)
    if VP.z > zsol + PLAFOND then VP.z = zsol + PLAFOND end
    local s = 5 + (i % 3) * 2
    render.DrawSprite(VP, s, s, couleur(255, 110, 40, 255 * math.sin(a * math.pi) * math.min(I, 1.2)))
  end
end

local function brume(m, T, n, vapeur)
  render.SetMaterial(FUMEE)
  for i = 1, n do
    local th = i / n * 6.28 + TA * 0.04 + m.ph
    VP:Set(m.pied)
    VP.x = VP.x + math.cos(th) * (m.g.b + 160)
    VP.y = VP.y + math.sin(th) * (m.g.b + 160)
    VP.z = zsol + 40 + vapeur * 160 * ((i % 3) / 3)
    local s = 380 + vapeur * 300
    if vapeur > 0 then render.DrawSprite(VP, s, s, couleur(120, 112, 118, 70 * vapeur))
    else render.DrawSprite(VP, s, s, couleur(26, 22, 28, 90)) end
  end
end

local function eclats(m, T, n)                                    -- boum : éclats incandescents projetés, qui retombent
  local u = T - BOUM
  if u < 0 or u > 4 then return end
  render.SetMaterial(HALO)
  local r = graine(m.rang * 97 + 13)
  for i = 1, n do
    local P = m.f[1 + i % #m.f]
    local src = P[1 + math.floor(r() * #P)]
    VN:Set(src); VN:Sub(m.pied); VN.z = 0; VN:Normalize()
    local v, w = 250 + r() * 420, 120 + r() * 380
    VP:Set(src)
    VP.x = VP.x + VN.x * v * u; VP.y = VP.y + VN.y * v * u
    VP.z = src.z + w * u - 300 * u * u
    if VP.z > zsol and VP.z < zsol + PLAFOND then
      local chaud = math.max(0, 1 - u / 2.5)
      local s = math.max(22 + r() * 22, EyePos():Distance(VP) * 0.006)   -- v2 : visibles de loin
      render.DrawSprite(VP, s, s, couleur(255, 60 + 160 * chaud, 20 + 120 * chaud, 255 * (1 - u / 4)))
    end
  end
  if u < 1.2 then                                                -- v2 : éclair rouge de l'éclatement, autour de la dalle
    VP:Set(m.pied); VP.z = VP.z + m.g.h * 0.45
    local s = math.min((1400 + 900 * u) * m.k, 2 * (zsol + PLAFOND - VP.z))   -- l'éclair reste dans la boîte
    render.DrawSprite(VP, s * 0.7, s, couleur(220, 20, 16, 200 * (1 - u / 1.2)))
  end
  if u < 2.5 then                                                -- poussière qui jaillit des fissures
    render.SetMaterial(FUMEE)
    for i = 1, 6 do
      local P = m.f[1 + i % #m.f]
      local src = P[1 + (i * 3) % #P]
      VN:Set(src); VN:Sub(m.pied); VN.z = 0; VN:Normalize()
      VP:Set(src); VP.x = VP.x + VN.x * (60 + 160 * u); VP.y = VP.y + VN.y * (60 + 160 * u)
      local s = 120 + 380 * u
      render.DrawSprite(VP, s, s, couleur(70, 58, 60, 120 * (1 - u / 2.5)))
    end
  end
end

local function temps()
  if T_FIGE >= 0 then return T_FIGE end
  if not t0 then t0 = CurTime() end
  return (CurTime() - t0) % BOUCLE
end

function MONO.dessin(TR, T)
  TA = T + (MONO.H or 0)
  if #L == 0 or not zsol or MONO.coupee then return end
  if EXT then etaint = math.max(0, math.min(1, (T - EXT[1]) / (EXT[2] - EXT[1]))) end
  local q = qualite:GetInt()
  local oeil, dir = EyePos(), EyeVector()
  local nb_b, nb_e, nb_q = ({ 8, 14, 22 })[q + 1] or 14, ({ 40, 64, 96 })[q + 1] or 64, ({ 2, 4, 6 })[q + 1] or 4
  for _, m in ipairs(L) do
    VN:Set(m.centre); VN:Sub(oeil)
    local d = VN:Length()
    local vu = d < m.rayon or VN:Dot(dir) / d > 0.35 - m.rayon / d   -- v3 : hors champ, rien
    if vu and IsValid(m.e) then
      local I = intensite(m, TR, T)
      local loin = d > 5200                                      -- v3 : au loin, les fissures seules (coeur)
      if not loin then
        local vap = T >= BOUM and math.max(0, 1 - (T - BOUM) / 6) or 0
        brume(m, T, m.debout and 5 or 2, vap)
      end
      fissures(m, I, d, loin)
      if not loin then lave(m, I, T, nb_q) end
      if m.debout then
        if not loin then braises(m, I, T, nb_b) end
        eclats(m, T, nb_e)
      end
    end
  end
  if etaint > 0 and L[1] then                                    -- trône vide : un seul fil rouge reste
    local m = L[1]
    render.SetMaterial(LUEUR)
    local P = m.f[1]
    for j = 2, #P do render.DrawBeam(P[j - 1], P[j], 5, 0, 1, couleur(220, 10, 16, 200 * etaint)) end
  end
end
function MONO.eteindre(x) etaint = math.max(0, math.min(1, x)) end

local prochain = 0
hook.Add("Think", "LacNoir_monolithes_scene", function()          -- repérage des dalles collées, une fois par seconde
  if CurTime() < prochain then return end
  prochain = CurTime() + 1
  MONO.coupee = file.Exists("lac_mesure/mono_off.txt", "DATA")   -- mesure « sans monolithes » sans console ni focus
  local t = {}                                                 -- v86 : seulement ceux du build repéré
  for _, e in ipairs(ents.FindByModel(MODELE)) do if SC.dans_boite(e:GetPos()) then t[#t + 1] = e end end
  if #t ~= nb then nb = #t; if nb > 0 then construire(t) else L = {} end end
end)
print("[lac_scene_complete] monolithes accrochés au lac")
return MONO

end)()

-- ======================================================================================================================
-- LES AQUEDUCS BRISÉS (module)
PIECES.AQ = (function()
-- Lac noir de Nobleza, pièce 7 : les aqueducs brisés, effets en script (25/11/2026, v1). 0 posé, rien dans le dupe.
-- Sur les arcades posées en props (huecomundosetails208_1, build lac_noir_aqueducs) :
--  le canal charrie du sang : au bout brisé de l'étage bas, une cascade carmin tombe dans le lac (filets en arc qui
--  défilent, halo), brume rouge sombre, anneaux et flaque lumineuse au pied ;
--  l'étage haut, affaissé, suinte sur le gradin (filet mince) ;
--  des gouttes tombent de la clé de chaque arche jusqu'à l'eau ;
--  cloches : la cascade gonfle à chaque coup ; boum : elle jaillit (gerbe d'éclaboussures) ; extinction : un seul filet.
-- Coût : formes des filets calculées une fois par collage ; par image, aucune allocation ; tri hors champ ; détail selon
-- lac_qualite. Banc : T_FIGE fige le temps (photos), NUIT assombrit comme la scène (colormod puis effets).
if not string.find(game.GetMap(), "hueco", 1, true) then return end
local MODELE = "models/propper/hueco_mundo_v1/huecomundosetails208_1.mdl"
local AN, AX = Vector(-138, -1273.5, -194), Vector(138, 1273.5, 194)   -- bornes_modele (atelier/moteur/geo.py)
local T_FIGE = -1                       -- banc : temps figé en secondes (-1 : boucle de BOUCLE s)
local NUIT = true                       -- banc seul : assombrir comme la scène
local BOUCLE = 30
local CLOCHES = { 3.0, 6.5, 10.0, 13.5 }
local BOUM = 9.0                       -- scène complète : 9 (temps du lac)
local EXT = { 31, 36 }                         -- scène complète : { début, fin } de l'extinction (temps du lac)
local G = 620                           -- pesanteur des filets (u/s²)
local function mat(n) local m = Material(n) if m and not m:IsError() then return m end end
local FILET = mat("effects/bloodstream") or Material("effects/laser1")
local LUEUR = Material("effects/laser1")
local HALO = Material("sprites/light_glow02_add")
local FUMEE = Material("particle/particle_smokegrenade")
local qualite = GetConVar("lac_qualite") or CreateClientConVar("lac_qualite", "1", true, false)
local AQ = {}
local TA = 0                                     -- v70 : horloge des animations
local L = {}                            -- arcades : { e, bas, chutes = { {P...} }, pied, centre, rayon, cles = { V } }
local zsol, t0, nb = nil, nil, -1
local VP, VN, VA = Vector(), Vector(), Vector()
local COL = Color(0, 0, 0, 0)
local HAUT = Vector(0, 0, 1)
local etaint = 0

local function couleur(r, g, b, a) COL.r, COL.g, COL.b, COL.a = r, g, b, math.max(0, math.min(255, a)) return COL end

-- un filet : part du bout du canal (A), vers dir à la vitesse v, tombe jusqu'à zb ; 8 points
local function filet(A, dir, v, zb)
  local P, H = {}, A.z - zb
  local tf = math.sqrt(2 * math.max(H, 1) / G)
  for i = 0, 7 do
    local t = tf * i / 7
    P[#P + 1] = Vector(A.x + dir.x * v * t, A.y + dir.y * v * t, A.z - 0.5 * G * t * t)
  end
  return P
end

local function construire(liste)
  L = {}
  local bas = {}
  for _, e in ipairs(liste) do
    local k = e:GetModelScale() or 1
    if e:GetUp().z > 0.985 then                                 -- v4 : < 10°, les arches tombées (13°) ne coulent pas
      local m = { e = e, k = k, bas = k > 1.2, chutes = {}, cles = {} }
      local y1, y2 = e:LocalToWorld(Vector(0, AN.y * k, AX.z * k)), e:LocalToWorld(Vector(0, AX.y * k, AX.z * k))
      m.bout, m.loin, m.yb, m.sy = y1, y2, AN.y, 1
      if y2.y < y1.y then m.bout, m.loin, m.yb, m.sy = y2, y1, AX.y, -1 end   -- le bout brisé : côté lac (y le plus petit)
      m.pied = e:LocalToWorld(Vector(0, 0, AN.z * k))
      m.centre, m.rayon = e:GetPos(), (AX.y - AN.y) * k * 0.6
      if m.bas then bas[#bas + 1] = m.pied.z end
      L[#L + 1] = m
    end
  end
  table.sort(bas); zsol = (bas[1] or 0) + 20                        -- l'étage bas est enfoncé de 20 u (build)
  local hautbas = nil
  for _, m in ipairs(L) do if m.bas then hautbas = m.bout.z end end
  for _, m in ipairs(L) do
    local dir = Vector(m.bout.x - m.loin.x, m.bout.y - m.loin.y, 0); dir:Normalize()
    local lat = Vector(-dir.y, dir.x, 0)
    local zb = m.bas and zsol or (hautbas or zsol)                 -- l'étage haut coule sur le gradin
    local n = m.bas and 10 or 3                                     -- v2 : nappe plus large
    for i = 1, n do
      local u = (i - (n + 1) / 2) / n
      local A = m.bout + lat * (u * 230 * m.k) - HAUT * (22 * m.k) + dir * 4
      m.chutes[i] = filet(A, dir, (m.bas and 70 or 25) + (i * 37) % 60, zb)
    end
    if m.bas then                                                   -- v3 : coulures sur les flancs, près de la cassure
      m.coul = {}
      for i = 1, 8 do
        local cx = (i % 2 == 1 and 1 or -1) * (AX.x * m.k + 2)
        local ly = m.yb * m.k + m.sy * (50 + 110 * math.floor((i - 1) / 2) + 30 * (i % 3))
        local A = m.e:LocalToWorld(Vector(cx, ly, AX.z * m.k - 10))
        local B = m.e:LocalToWorld(Vector(cx, ly + m.sy * (20 + 15 * i), AN.z * m.k + 25))
        m.coul[i] = { A, B }
      end
      m.lum = Vector()                                              -- lumière rouge de la cascade, au pied
    end
    if m.bas then                                                   -- clés des 4 arches
      for i = 1, 4 do
        local y = AN.y + (i - 0.5) * (AX.y - AN.y) / 4
        m.cles[i] = m.e:LocalToWorld(Vector(0, y * m.k, (AN.z + 0.66 * (AX.z - AN.z)) * m.k))
      end
    end
  end
  print(string.format("[lac_aq] %d arcades, sol z %.0f, filet %s", #L, zsol or 0, FILET == LUEUR and "laser" or "bloodstream"))
end

local function debit(TR, T)
  local d = 1
  for k, tc in ipairs(CLOCHES) do if TR >= tc and TR < tc + 6 then d = d + (0.3 + 0.12 * k) * math.exp(-(TR - tc) * 1.1) end end
  if T >= BOUM then d = d + 1.6 * math.exp(-(T - BOUM) * 0.7) end
  return d
end

local function cascade(m, d, T, oeil, loin)
  local wd = oeil:Distance(m.bout) * 0.0025
  local n = #m.chutes
  if etaint > 0 then n = math.max(1, math.floor(n * (1 - etaint) + 0.5)) end
  if not loin then                                                  -- halo autour des filets
    render.SetMaterial(HALO)
    local col = couleur(170, 8, 12, 105 * math.min(d, 2) * (1 - 0.7 * etaint))
    for i = 1, n do
      local P = m.chutes[i]
      for j = 3, #P, 2 do render.DrawBeam(P[j - 2], P[j], math.max(70 * m.k * d, wd * 10), 0, 1, col) end
    end
  end
  render.SetMaterial(FILET)
  if m.bas and not loin then                                        -- v2 : la nappe, un voile qui défile entre les filets
    local P = m.chutes[math.ceil(#m.chutes / 2)]
    local s = -TA * 1.2
    local cv = couleur(170, 10, 14, 165 * (1 - 0.8 * etaint))
    for j = 2, #P do render.DrawBeam(P[j - 1], P[j], 300 * m.k, s + j * 0.25, s + j * 0.25 + 0.25, cv) end
  end
  local col = couleur(220, 16, 20, 245)                             -- les filets, texture qui défile vers le bas
  local w = math.max((m.bas and 46 or 20) * m.k * (0.8 + 0.25 * d), wd)
  for i = 1, n do
    local P = m.chutes[i]
    local s = -TA * (1.6 + i * 0.13)
    for j = 2, #P do render.DrawBeam(P[j - 1], P[j], w, s + j * 0.3, s + j * 0.3 + 0.3, col) end
  end
end

local function canal(m, d, T)                                       -- v2 : le canal plein de sang, une ligne rouge le long du faîte
  render.SetMaterial(LUEUR)
  local a = (0.55 + 0.2 * math.sin(TA * 0.9 + m.k * 3)) * math.min(d, 1.8) * (1 - 0.85 * etaint)
  render.DrawBeam(m.bout, m.loin, math.max(26 * m.k, EyePos():Distance(m.centre) * 0.002), -TA * 0.05, 1 - TA * 0.05, couleur(200, 10, 16, 200 * a))
  render.SetMaterial(HALO)
  render.DrawBeam(m.bout, m.loin, 150 * m.k, 0, 1, couleur(150, 6, 10, 70 * a))
end

local function pied(m, d, T, nr, nf)
  local P = m.chutes[math.ceil(#m.chutes / 2)]
  local B = P[#P]
  render.SetMaterial(HALO)                                          -- flaque lumineuse et anneaux sur l'eau
  VP:Set(B); VP.z = zsol + 2
  render.DrawQuadEasy(VP, HAUT, 900 * m.k * (0.8 + 0.2 * d), 900 * m.k * (0.8 + 0.2 * d), couleur(190, 10, 14, 170 * (1 - 0.8 * etaint)), 0)
  for i = 1, nr do
    local a = ((TA * 0.6 + i / nr) % 1)
    render.DrawQuadEasy(VP, HAUT, 60 + 360 * a * m.k, 60 + 360 * a * m.k, couleur(230, 40, 30, 150 * (1 - a) * (1 - etaint)), 0)
  end
  render.SetMaterial(FUMEE)                                         -- brume rouge sombre qui monte du choc
  for i = 1, nf do
    local a = ((TA * 0.25 + i / nf) % 1)
    VP:Set(B)
    VP.x = VP.x + math.sin(i * 2.4) * 90 * m.k
    VP.y = VP.y + math.cos(i * 1.7) * 90 * m.k
    VP.z = zsol + 30 + a * 260 * m.k
    local s = (160 + 260 * a) * m.k
    render.DrawSprite(VP, s, s, couleur(70, 20, 24, 110 * math.sin(a * math.pi) * math.min(d, 1.5) * (1 - etaint)))
  end
end

local function gouttes(m, T)
  render.SetMaterial(HALO)
  for i, C in ipairs(m.cles) do
    VP:Set(C); VP.z = zsol + 2
    local a = (0.6 + 0.4 * math.sin(TA * 0.8 + i * 1.3)) * (1 - etaint)
    render.DrawQuadEasy(VP, HAUT, 520 * m.k, 520 * m.k, couleur(160, 8, 12, 110 * a), 0)
    VN:Set(C); VN.z = zsol + 4
    render.DrawBeam(C, VN, 40, 0, 1, couleur(170, 10, 14, 60 * a))
  end
  for i, C in ipairs(m.cles) do
    local per = 2.6 + i * 0.55
    local a = ((TA + i * 1.7) % per) / per
    if a < 0.9 then
      VP:Set(C); VP.z = C.z - (C.z - zsol) * (a / 0.9) ^ 2
      render.DrawSprite(VP, 26, 46, couleur(255, 60, 30, 255 * (1 - etaint)))
    else
      local b = (a - 0.9) / 0.1
      VP:Set(C); VP.z = zsol + 3
      render.DrawQuadEasy(VP, HAUT, 30 + 160 * b, 30 + 160 * b, couleur(255, 50, 30, 200 * (1 - b) * (1 - etaint)), 0)
    end
  end
end

local function coulures(m, T)                                       -- v3 : le sang suinte et coule sur les flancs
  render.SetMaterial(FILET)
  for i, c in ipairs(m.coul) do
    local s = -TA * (0.7 + 0.15 * i)
    render.DrawBeam(c[1], c[2], 20 + 8 * (i % 3), s, s + 2.5, couleur(210, 14, 18, 255 * (1 - etaint)))
  end
  render.SetMaterial(HALO)
  for _, c in ipairs(m.coul) do render.DrawBeam(c[1], c[2], 90, 0, 1, couleur(150, 6, 10, 70 * (1 - etaint))) end
end

local function eclabous(m, T, n, d)                                 -- v3 : éclaboussures continues au pied de la cascade
  local P = m.chutes[math.ceil(#m.chutes / 2)]
  local B = P[#P]
  render.SetMaterial(HALO)
  for i = 1, n do
    local L = 0.7 + (i % 4) * 0.15
    local u = ((TA + i * 0.29) % L)
    local th = i * 2.399
    local v, w = 60 + (i * 37) % 120, 140 + (i * 71) % 160
    VP:Set(B)
    VP.x = VP.x + math.cos(th) * v * u
    VP.y = VP.y + math.sin(th) * v * u
    VP.z = zsol + w * u * math.min(d, 1.6) - 0.5 * G * u * u
    if VP.z > zsol then render.DrawSprite(VP, 9, 9, couleur(255, 50, 30, 230 * (1 - etaint))) end
  end
  for i = 1, 3 do                                                   -- têtes brillantes qui descendent les filets
    local Pi = m.chutes[1 + (i * 3) % #m.chutes]
    local u = ((TA * 0.9 + i * 0.33) % 1) * (#Pi - 1)
    local j = math.floor(u) + 1
    local f = u - (j - 1)
    VP:Set(Pi[j]); VP:Mul(1 - f); VA:Set(Pi[math.min(j + 1, #Pi)]); VA:Mul(f); VP:Add(VA)
    render.DrawSprite(VP, 30, 30, couleur(255, 90, 60, 200 * (1 - etaint)))
  end
  local dl = DynamicLight(4410 + (m.sy > 0 and 1 or 0) + (m.bout.x > 0 and 2 or 0))   -- la cascade éclaire la pierre
  if dl then
    m.lum:Set(B); m.lum:Add(m.bout); m.lum:Mul(0.5); dl.pos = m.lum; dl.nomodel = false
    dl.r, dl.g, dl.b = 255, 30, 20
    dl.brightness, dl.decay, dl.size, dl.dietime = 4 * math.min(d, 1.6) * (1 - etaint), 1000, 1400, CurTime() + 0.1
  end
end

local function gerbe(m, T, n)                                       -- boum : la cascade jaillit en éclaboussures
  local u = T - BOUM
  if u < 0 or u > 2.5 then return end
  render.SetMaterial(HALO)
  local P = m.chutes[math.ceil(#m.chutes / 2)]
  local B = P[#P]
  for i = 1, n do
    local th = i * 2.399
    local v, w = 150 + (i * 53) % 260, 260 + (i * 97) % 420
    VP:Set(B)
    VP.x = VP.x + math.cos(th) * v * u
    VP.y = VP.y + math.sin(th) * v * u
    VP.z = zsol + w * u - 0.5 * G * u * u
    if VP.z > zsol then
      local s = math.max(14 + (i % 4) * 6, EyePos():Distance(VP) * 0.005)
      render.DrawSprite(VP, s, s, couleur(255, 40 + 60 * math.max(0, 1 - u), 30, 255 * (1 - u / 2.5)))
    end
  end
end

function AQ.dessin(TR, T)
  TA = T + (AQ.H or 0)
  if #L == 0 or not zsol or AQ.coupee or T < BOUM then return end   -- v79 : les aqueducs s'enclenchent au boum
  if EXT then etaint = math.max(0, math.min(1, (T - EXT[1]) / (EXT[2] - EXT[1]))) end
  local q = qualite:GetInt()
  local nr, nf, ng = ({ 2, 3, 4 })[q + 1] or 3, ({ 3, 5, 8 })[q + 1] or 5, ({ 24, 40, 64 })[q + 1] or 40
  local oeil, dir = EyePos(), EyeVector()
  local d = debit(TR, T)
  for _, m in ipairs(L) do
    VN:Set(m.centre); VN:Sub(oeil)
    local dist = VN:Length()
    local vu = dist < m.rayon or VN:Dot(dir) / dist > 0.35 - m.rayon / dist   -- hors champ : rien
    local o, ta = SC.onde(m.centre, T)             -- v81 : l'arcade s'enclenche au passage de l'onde
    if vu and IsValid(m.e) and o > 0 then
      local loin = dist > 6000
      cascade(m, d, T, oeil, loin)
      canal(m, d, T)
      if m.bas then
        if not loin then pied(m, d, T, nr, nf); gouttes(m, T); coulures(m, T); eclabous(m, T, nr * 5, d) end
        gerbe(m, T - (ta - BOUM), ng)
      end
    end
  end
end

local prochain = 0
hook.Add("Think", "LacNoir_aqueducs_scene", function()                    -- repérage des arcades collées, une fois par seconde
  if CurTime() < prochain then return end
  prochain = CurTime() + 1
  AQ.coupee = file.Exists("lac_mesure/aq_off.txt", "DATA")          -- mesure « sans aqueducs » sans console ni focus
  local t = {}                                                 -- v86 : seulement ceux du build repéré
  for _, e in ipairs(ents.FindByModel(MODELE)) do if SC.dans_boite(e:GetPos()) then t[#t + 1] = e end end
  if #t ~= nb then nb = #t; if nb > 0 then construire(t) else L = {} end end
end)
print("[lac_scene_complete] aqueducs accrochés au lac")
return AQ

end)()

-- ======================================================================================================================
-- LA FLAMME BLEUE (module)
PIECES.FL = (function()
-- Lac noir de Nobleza, la flamme bleue (25/11/2026, v1). 0 posé : module de la scène complète, dessiné par le lac.
-- Texte de l'étape 6 : « Au fond, au pied de la cathédrale, une flamme bleue s'allume. Elle n'avance pas vers lui : elle
-- attend. Une ligne de feu bleu court sur la garde de la lame. Le carmin et le bleu brûlent ensemble. »
-- Donc, après l'extinction (31 à 36 s) et le cœur (36 s) : la flamme s'allume à 36,6 s au pied de la cathédrale, dans
-- l'axe (y 4 330 du repère de l'île), grandit jusqu'à 39 s et brûle sur place ; son reflet tremble dans l'eau ; une
-- lueur bleue sur l'eau et une lumière dynamique qui éclaire le pied de la façade. À 37,8 s, une ligne de feu bleu fait
-- le tour de la garde de la lame (tsuba : cercle de r 37 en (0, -65, 574)) puis y reste, à côté des braises carmin.
-- Coût : pas d'allocation par image ; langues de feu bornées par lac_qualite ; rien hors champ.
local FL = {}
local TA = 0                                     -- v70 : horloge des animations
local function mat(n) local m = Material(n) if m and not m:IsError() then return m end end
local FEU = mat("effects/fire_cloud1") or mat("particle/fire") or Material("sprites/light_glow02_add")
local HALO = Material("sprites/light_glow02_add")
local LUEUR = Material("effects/laser1")
local qualite = GetConVar("lac_qualite") or CreateClientConVar("lac_qualite", "1", true, false)
local F = Vector(0, 4330, 11)                 -- pied de la flamme, sur l'eau (EAU = 11), repère de l'île
local GARDE, RG = Vector(-0.3, -65, 574), 37.5   -- v4 : collée au bord de la garde (r 37)  -- la garde de la lame et le rayon de la ligne de feu
local ALLUME, GARDE_T = 36.6, 37.8
local VB, VP, VA, VB2, VL = Vector(), Vector(), Vector(), Vector(), Vector()
local COL = Color(0, 0, 0, 0)
local HAUT = Vector(0, 0, 1)
local function couleur(r, g, b, a) COL.r, COL.g, COL.b, COL.a = r, g, b, math.max(0, math.min(255, a)) return COL end
local function lisse(x) x = math.max(0, math.min(1, x)) return x * x * (3 - 2 * x) end

local NL, NS = 7, 12                                               -- v3 : 7 langues de 12 segments
local function langues(T, a, zw, C, sc)                           -- v8 : centre et échelle (petites flammes de la garde)
  C, sc = C or VB, sc or 1
  for pass = 1, 2 do
    render.SetMaterial(pass == 1 and FEU or HALO)
    for k = 1, (pass == 1 and NL or 3) do
      local b = k * 0.8976                                          -- 2*pi/7
      local h = (230 + 260 * ((k * 5) % 7) / 6) * a * (0.85 + 0.15 * math.sin(T * 9 + k * 1.7))
      if pass == 2 then h = h * 0.55 end
      h = h * sc
      local R = (pass == 1 and 48 or 20) * sc
      local s0 = -T * (2.2 + 0.2 * k)
      for j = 0, NS do
        local t = j / NS
        local ond = math.sin(T * 6.5 + k * 1.3 + t * 5) * 34 * t * sc
        local x = math.cos(b) * R * (1 - t) ^ 0.8 + ond
        local y = math.sin(b) * R * (1 - t) ^ 0.8 + math.cos(T * 5.1 + k) * 14 * t * sc
        VA:Set(C); VA.x = VA.x + x; VA.y = VA.y + y; VA.z = zw + 6 * sc + t * h
        if j > 0 then
          local w = ((1 - t) ^ 0.9 * (pass == 1 and 95 or 55) + 3) * a * sc
          local c = pass == 1 and couleur(30, 70 + 50 * (1 - t), 255, 220 * (1 - 0.4 * t))
                               or couleur(150, 215, 255, 200 * (1 - t))
          render.DrawBeam(VB2, VA, w, s0 + t - 1 / NS, s0 + t, c)        -- texture continue d'un segment à l'autre
        end
        VB2:Set(VA)
      end
    end
  end
end

local PCF_GARDE = "[1]aura_bleu"                                  -- v6 : la garde seule passe en effet (Adrien : la flamme de la cathédrale reste dessinée)
for _, f in ipairs({ "particles/watcher_stuff.pcf" }) do if file.Exists(f, "GAME") then game.AddParticles(f) end end
PrecacheParticleSystem(PCF_GARDE)
local FOYERS = {}                                                 -- v6 : pas d'effet au pied de la cathédrale (le dessin v3 est validé)
for _, f in ipairs(FOYERS) do PrecacheParticleSystem(f[3]) end
local NG = 0                                                      -- flammes posées sur le tour de la garde
FL.ps = {}
local function arreter()
  for k, p in pairs(FL.ps) do if p:IsValid() then p:StopEmission(false, true) end FL.ps[k] = nil end
  FL.pcf_ok = nil
end
local function poser(cle, nom, pos)
  local p = FL.ps[cle]
  if not (p and p:IsValid()) and CreateParticleSystemNoEntity then
    p = CreateParticleSystemNoEntity(nom, pos); FL.ps[cle] = p
    if p and p:IsValid() then p:SetShouldDraw(false) end          -- v6 : rendu par nous, après l'assombrissement (sinon terne)
  end
  if p and p:IsValid() then p:SetControlPoint(0, pos) return true end
  return false
end
local VE, VG = Vector(), Vector()
local function effets(T, off)                                     -- foyer au pied de la cathédrale, puis le tour de la garde
  local ok = true
  for i, f in ipairs(FOYERS) do
    if T >= ALLUME + 0.4 * (i - 1) then
      VE:Set(F); VE.x = VE.x + f[1]; VE.y = VE.y + f[2]; VE:Add(off)
      ok = poser("f" .. i, f[3], VE) and ok
    end
  end
  local g = lisse((T - GARDE_T) / 0.8)
  for j = 1, math.floor(NG * g + 0.5) do                          -- elles s'allument une à une, en faisant le tour
    local an = j / NG * 6.2832
    VE:SetUnpacked(GARDE.x + RG * math.cos(an), GARDE.y + RG * math.sin(an), GARDE.z + 1); VE:Add(off)
    ok = poser("g" .. j, PCF_GARDE, VE) and ok
  end
  FL.pcf_ok = ok
  for _, q in pairs(FL.ps) do if q:IsValid() then q:Render() end end
end

local function flamme(T, a, n, oeil)
  local zw = VB.z
  render.SetMaterial(HALO)                                          -- lueur sur l'eau, l'aura
  local fl = 0.85 + 0.15 * math.sin(TA * 17) * math.sin(TA * 7.3)
  render.DrawQuadEasy(VB, HAUT, (500 + 700 * a) * fl, (500 + 700 * a) * fl, couleur(40, 90, 255, 150 * a), 0)
  VP:Set(VB); VP.z = zw + 220 * a
  render.DrawSprite(VP, 900 * a, 1100 * a, couleur(30, 70, 255, 32 * a * fl))
  langues(TA, a, zw)
  render.SetMaterial(FEU)                                           -- les nuages : ils montent, se resserrent, bleuissent
  for i = 1, math.floor(n * 0.6) do
    local L = 0.9 + (i % 5) * 0.14
    local u = ((TA + i * 0.618) % L) / L
    local r = (1 - u) * 55 * math.cos(i * 2.4)
    VP:Set(VB)
    VP.x = VP.x + r + math.sin(TA * 3.1 + i) * 26 * u
    VP.y = VP.y + (1 - u) * 55 * math.sin(i * 2.4)
    VP.z = zw + 10 + u * (300 + 260 * a) * (0.7 + 0.3 * ((i * 7) % 10) / 10)
    local s = (40 + 170 * (1 - u)) * a
    local g = 45 + 80 * (1 - u)                                    -- v2 : bleu saturé (la texture de feu tirait au rose)
    local al = 255 * math.sin(u * math.pi) * a
    render.DrawSprite(VP, s, s * 1.3, couleur(15 + 45 * (1 - u), g, 255, al * 0.85))
    VA:Set(VP); VA.z = 2 * zw - VP.z                                -- reflet dans l'eau, plus faible
    render.DrawSprite(VA, s, s * 1.3, couleur(40, g * 0.6, 220, al * 0.28))
  end
  render.SetMaterial(HALO)                                          -- cœur blanc bleuté, étincelles
  VP:Set(VB); VP.z = zw + 50
  render.DrawSprite(VP, 170 * a * fl, 220 * a * fl, couleur(120, 190, 255, 200 * a))
  for i = 1, math.floor(n / 2) do
    local L = 2.2 + (i % 4) * 0.5
    local u = ((TA * 0.8 + i * 0.37) % L) / L
    VP:Set(VB)
    VP.x = VP.x + math.sin(i * 1.9 + TA) * 70 * u
    VP.y = VP.y + math.cos(i * 2.3) * 50 * u
    VP.z = zw + 120 + u * 800 * a
    local s = 5 + (i % 3) * 3
    if i % 5 == 0 then render.DrawSprite(VP, s, s, couleur(255, 60, 30, 220 * (1 - u) * a))   -- le carmin brûle avec
    else render.DrawSprite(VP, s, s, couleur(150, 200, 255, 255 * (1 - u) * a)) end
  end
  local dl = DynamicLight(4405)                                     -- elle éclaire le pied de la façade
  if dl then
    VL:Set(VB); VL.z = zw + 160; dl.pos = VL
    dl.r, dl.g, dl.b = 60, 120, 255
    dl.brightness, dl.decay, dl.size, dl.dietime = 3 * a, 1000, 1400 * a, CurTime() + 0.1
  end
end

local function garde(T, off)
  local f = lisse((T - GARDE_T) / 0.8)                              -- la ligne fait le tour en 0,8 s
  if f <= 0 then return end
  local nseg = 48                                                   -- v4 : cercle lisse, plus de polygone visible
  local fin = math.floor(nseg * f + 0.5)
  local p = 0.8 + 0.2 * math.sin(TA * 11)
  for pass = 1, 2 do
    render.SetMaterial(pass == 1 and HALO or LUEUR)
    local w = (pass == 1 and 20 or 3) * (FL.pcf_ok and 0.5 or 1)   -- v6 : avec l'effet, une ligne fine sous les flammes
    local c = pass == 1 and couleur(40, 100, 255, 150 * p) or couleur(170, 215, 255, 255)
    for j = 1, fin do
      local a1, a2 = (j - 1) / nseg * 6.2832, j / nseg * 6.2832
      VA:SetUnpacked(GARDE.x + RG * math.cos(a1), GARDE.y + RG * math.sin(a1), GARDE.z); VA:Add(off)
      VB2:SetUnpacked(GARDE.x + RG * math.cos(a2), GARDE.y + RG * math.sin(a2), GARDE.z); VB2:Add(off)
      render.DrawBeam(VA, VB2, w, 0, 1, c)
    end
  end
  if FL.pcf_ok then return end                                      -- v6 : les flammes de la garde sont l'effet d'EVO
  render.SetMaterial(HALO)                                          -- v5 : un corps de flamme bleu le long du cercle
  for j = 1, fin, 4 do
    local an = j / nseg * 6.2832
    VA:SetUnpacked(GARDE.x + RG * math.cos(an), GARDE.y + RG * math.sin(an), GARDE.z + 6); VA:Add(off)
    render.DrawSprite(VA, 26, 22, couleur(40, 110, 255, 120 * p))
  end
  render.SetMaterial(LUEUR)                                         -- petites flammes bleues sur le cercle (v4 : laser, net)
  for j = 1, fin, 2 do                                              -- v4 : petites langues en faisceaux (plus de brûleur à gaz)
    local an = j / nseg * 6.2832 + math.sin(j * 7.1) * 0.05
    local hh = (10 + ((j * 53) % 9) * 2) * (0.75 + 0.25 * math.sin(TA * 8 + j * 1.9))   -- v5 : plus courtes
    local w0 = 12 + (j % 3) * 3                                       -- v5 : plus pleines à la base
    local s0 = -TA * 2.5 + j * 0.37
    VB2:SetUnpacked(GARDE.x + RG * math.cos(an), GARDE.y + RG * math.sin(an), GARDE.z); VB2:Add(off)
    for q = 1, 4 do
      local t = q / 4
      VA:SetUnpacked(GARDE.x + RG * math.cos(an) + math.sin(TA * 7 + j + t * 4) * 3 * t, GARDE.y + RG * math.sin(an), GARDE.z + t * hh); VA:Add(off)
      render.DrawBeam(VB2, VA, w0 * (1 - t) ^ 1.4 + 1.5, 0, 1, couleur(30 + 70 * (1 - t), 90 + 80 * (1 - t), 255, 255 * (1 - 0.6 * t)))
      VB2:Set(VA)
    end
  end
end

function FL.dessin(TR, T, off)
  TA = T + (FL.H or 0)
  if not off or not T or FL.coupee or T < ALLUME then if next(FL.ps) then arreter() end return end
  effets(T, off)
  local a = lisse((T - ALLUME) / 2.4)
  local q = qualite:GetInt()
  local n = ({ 10, 16, 24 })[q + 1] or 16
  local oeil, dir = EyePos(), EyeVector()
  VB:Set(F); VB:Add(off)
  VP:Set(VB); VP:Sub(oeil)
  local d = VP:Length()
  if d < 1500 or VP:Dot(dir) / d > 0.3 then flamme(T, a, n, oeil) end
  -- v7 (Adrien, 25/11 : « un cerceau autour de la garde, c'est bizarre ») : plus de cerceau
  -- v8 (Adrien : « garde de petites flammes bleues ») : deux petites flammes, les langues de la cathédrale en réduit
  local g = lisse((T - GARDE_T) / 0.8)
  if g > 0 then
    for j = 0, 1 do
      VG:SetUnpacked(GARDE.x + (j == 0 and -RG or RG) * 0.85, GARDE.y, 0); VG:Add(off)
      langues(TA + j * 1.7, g, GARDE.z + off.z, VG, 0.07)
    end
  end
end

local prochain = 0
hook.Add("Think", "LacNoir_flamme_scene", function()
  if CurTime() < prochain then return end
  prochain = CurTime() + 1
  FL.coupee = file.Exists("lac_mesure/flamme_off.txt", "DATA")      -- mesure « sans flamme » sans console ni focus
end)
print("[lac_scene_complete] flamme bleue accrochée au lac")
return FL

end)()

-- ======================================================================================================================
-- L'ÉCLIPSE (module)
PIECES.EC = (function()
-- Lac noir de Nobleza, l'éclipse au-dessus de la cathédrale (25/11/2026, v1). 0 posé, rien dans la zone : dessinée dans
-- le ciel (PostDraw2DSkyBox, caméra du ciel à l'origine, objet à l'infini), donc aucune géométrie hors de la boîte.
-- Déroulé (temps brut des cloches, puis temps du lac) : avant les cloches, un soleil pâle au-dessus de la cathédrale ;
-- chaque coup de cloche fait avancer le disque noir d'un quart ; au 4e coup l'éclipse est totale, la couronne s'ouvre ;
-- au boum elle flambe ; un liseré carmin borde le disque noir et vire au bleu quand la flamme bleue s'allume (36,6 s).
-- Coût : un disque en 32 triangles, deux sprites, 32 segments de liseré, une fois par image ; pas d'allocation.
local EC = {}
local TA = 0                                     -- v70 : horloge des animations
local HALO = Material("sprites/light_glow02_add")
local LUEUR = Material("effects/laser1")
local DIR = Angle(-33, 90, 0):Forward()              -- au-dessus de la cathédrale (+y), 33° : 27° la cachait derrière les flèches
local DR = DIR:Cross(Vector(0, 0, 1)); DR:Normalize()
local DU = DR:Cross(DIR); DU:Normalize()
local R, NS = 14000, 32                              -- v5 : distance (au-delà de la cathédrale, en deçà du zfar), segments
local RAYON = 62 * 14                               -- ~3,5° de rayon apparent
local CLOCHES = { 3.0, 6.5, 10.0, 13.5 }
local BOUM, FLAMME = 9.0, 36.6
local VC, VA, VB, VO = Vector(), Vector(), Vector(), Vector()
local CERCLE = {}                                    -- directions du bord du disque, calculées une fois
for i = 0, NS do local t = i / NS * 6.2832; CERCLE[i] = DR * math.cos(t) + DU * math.sin(t) end
local COL = Color(0, 0, 0, 0)
local function couleur(r, g, b, a) COL.r, COL.g, COL.b, COL.a = r, g, b, math.max(0, math.min(255, a)) return COL end
local function lisse(x) x = math.max(0, math.min(1, x)) return x * x * (3 - 2 * x) end

local function disque(cx, cy, rr, r, g, b, a)        -- disque plein dans le plan du ciel, décalé de (cx, cy) en rayons
  VO:Set(DR); VO:Mul(cx * RAYON); VB:Set(DU); VB:Mul(cy * RAYON); VO:Add(VB); VO:Add(VC)
  mesh.Begin(MATERIAL_POLYGON, NS)
  for i = 0, NS - 1 do
    VA:Set(CERCLE[i]); VA:Mul(rr * RAYON); VA:Add(VO)
    mesh.Position(VA); mesh.Color(r, g, b, a); mesh.AdvanceVertex()
  end
  mesh.End()
end

local function anneau(r1, r2, r, g, b, a1, a2)      -- v4 : anneau dégradé, couleur pleine (se voit sur un ciel clair)
  mesh.Begin(MATERIAL_QUADS, NS)
  for i = 0, NS - 1 do
    VA:Set(CERCLE[i]); VA:Mul(r1 * RAYON); VA:Add(VC); mesh.Position(VA); mesh.Color(r, g, b, a1); mesh.AdvanceVertex()
    VA:Set(CERCLE[i]); VA:Mul(r2 * RAYON); VA:Add(VC); mesh.Position(VA); mesh.Color(r, g, b, a2); mesh.AdvanceVertex()
    VA:Set(CERCLE[i + 1]); VA:Mul(r2 * RAYON); VA:Add(VC); mesh.Position(VA); mesh.Color(r, g, b, a2); mesh.AdvanceVertex()
    VA:Set(CERCLE[i + 1]); VA:Mul(r1 * RAYON); VA:Add(VC); mesh.Position(VA); mesh.Color(r, g, b, a1); mesh.AdvanceVertex()
  end
  mesh.End()
end

local function couverture(TR, T)                     -- 0 : soleil libre ; 1 : éclipse totale
  if T >= BOUM then return 1 end
  local p = 0
  for k, tc in ipairs(CLOCHES) do if TR >= tc then p = (k - 1) / 4 + 0.25 * lisse((TR - tc) / 1.5) end end
  return p
end

-- v5 : dessinée par le lac après le colormod (comme les autres pièces) : le colormod pâlissait couronne et liseré.
-- Loin derrière la cathédrale, avec le test de profondeur : flèches et lames passent devant.
EC.MERS = { { -0.28, 0.22, 0.34, 120 }, { 0.12, 0.34, 0.26, 105 }, { 0.22, -0.05, 0.22, 95 },
  { -0.05, -0.32, 0.2, 90 }, { -0.42, -0.1, 0.16, 110 } }   -- v84 : x, y, rayon (en rayons de lune), opacité
EC.CRATERES = { { 0.45, 0.42, 0.07 }, { -0.12, -0.58, 0.09 }, { 0.55, -0.35, 0.06 }, { -0.6, 0.35, 0.05 },
  { 0.3, 0.6, 0.045 }, { -0.35, -0.45, 0.05 }, { 0.05, 0.08, 0.04 }, { 0.68, 0.1, 0.05 } }
function EC.dessin(TR, T)
  TA = T + (EC.H or 0)
  if not T or EC.coupee then return end
  local p = couverture(TR, T)
  local bleu = lisse((T - FLAMME) / 2)
  render.OverrideDepthEnable(true, false)
  render.CullMode(MATERIAL_CULLMODE_NONE)            -- v2 : le disque était tourné du mauvais côté (face arrière)
  VC:Set(DIR); VC:Mul(R); VC:Add(EyePos())
  render.SetMaterial(HALO)                           -- couronne : s'ouvre avec l'éclipse, flambe au boum
  local fl = (T >= BOUM and T < BOUM + 4) and 1.8 * math.exp(-(T - BOUM) * 0.8) or 0
  local cs = RAYON * (3.2 + 4 * p + 5 * fl)
  render.DrawSprite(VC, cs, cs, couleur(220 - 120 * bleu, 225 - 60 * bleu, 240, (60 + 150 * p) * (1 + fl)))
  if p < 1 then                                      -- le soleil pâle (caché peu à peu)
    render.SetColorMaterial()
    disque(0, 0, 1, 235, 232, 225, 255)
    for _, m in ipairs(EC.MERS) do disque(m[1], m[2], m[3], 168, 166, 160, m[4]) end      -- v84 : mers
    for _, c in ipairs(EC.CRATERES) do                                                   -- v84 : cratères
      disque(c[1] - 0.012, c[2] + 0.012, c[3], 250, 248, 242, 150)                       -- rebord éclairé
      disque(c[1], c[2], c[3] * 0.82, 150, 148, 142, 190)                                -- fond dans l'ombre
    end
    anneau(0.72, 1.0, 70, 68, 64, 0, 150)                                                -- v84 : bord assombri
    disque(0.38, -0.3, 1.0, 30, 30, 34, 95)                                              -- v84 : ombre de la sphère
  end
  if p > 0.6 then                                    -- v3 : la couronne, anneaux lumineux et jets autour du disque noir
    local k = lisse((p - 0.6) / 0.4) * (1 + fl)
    render.SetColorMaterial()
    local cr, cg = 235 - 150 * bleu, 238 - 80 * bleu
    anneau(0.98, 2.4, cr, cg, 255, math.min(255, 95 * k), 0)
    anneau(0.98, 1.3, cr, cg, 255, math.min(255, 210 * k), 0)
    render.SetMaterial(LUEUR)                         -- jets de la couronne, longueurs inégales, lent battement
    for i = 0, NS - 1, 3 do
      local L = 1.5 + 0.7 * math.abs(math.sin(i * 1.7)) + 0.15 * math.sin(TA * 0.7 + i)
      VA:Set(CERCLE[i]); VA:Mul(RAYON * 1.05); VA:Add(VC)
      VB:Set(CERCLE[i]); VB:Mul(RAYON * L); VB:Add(VC)
      render.DrawBeam(VA, VB, RAYON * 0.18, 0, 1, couleur(200 - 120 * bleu, 215 - 50 * bleu, 255, 120 * k))
    end
  end
  render.SetColorMaterial()                          -- le disque noir qui avance d'un quart à chaque cloche
  local dx = (1 - p) * 2.1
  disque(dx, (1 - p) * 0.35, 1.0, 4, 3, 6, 255)
  if p >= 0.98 then                                  -- liseré carmin (bleu à la fin), au bord du disque noir
    render.SetColorMaterial()
    anneau(0.99, 1.09, 230 - 180 * bleu, 20 + 90 * bleu, 30 + 225 * bleu, 255, 0)
  end
  render.CullMode(MATERIAL_CULLMODE_CCW)
  render.OverrideDepthEnable(false)
end

local prochain = 0
hook.Add("Think", "LacNoir_eclipse_scene", function()
  if CurTime() < prochain then return end
  prochain = CurTime() + 1
  EC.coupee = file.Exists("lac_mesure/eclipse_off.txt", "DATA")
end)
print("[lac_scene_complete] éclipse accrochée au lac")
return EC

end)()
